{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://raw.githubusercontent.com/anatoly-m-maslennikov/dset-specs-loops-framework/main/12_layer_gov/120_schemas/010_dset-gov-schemas-atom.schema.json",
  "title": "DSET atomic Markdown YAML property data",
  "description": "Base schema for the YAML property block of a DSET atomic Markdown artifact. Registered type routes are derived and never repeated in the carrier.",
  "type": "object",
  "required": [
    "artifact_type",
    "artifact_id",
    "scope_path",
    "priority",
    "llm_session_ids"
  ],
  "additionalProperties": true,
  "properties": {
    "revision_mode": false,
    "content_role": false,
    "governance_locus": false,
    "governance_origin": false,
    "relation_shape": false,
    "semantic_id": false,
    "status": false,
    "authority": false,
    "claim": false,
    "worktree_state": false,
    "artifact_type": {
      "$ref": "#/$defs/type_name"
    },
    "artifact_subtype": {
      "$ref": "#/$defs/type_name"
    },
    "artifact_id": {
      "$ref": "#/$defs/id"
    },
    "scope_path": {
      "type": "array",
      "minItems": 0,
      "uniqueItems": true,
      "items": {
        "type": "string",
        "pattern": "^[a-z][a-z0-9_-]*:[A-Za-z0-9][A-Za-z0-9._-]*$"
      }
    },
    "priority": {
      "enum": [
        "high",
        "medium",
        "low"
      ]
    },
    "llm_session_ids": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "pattern": "^[a-z][a-z0-9_-]*:[A-Za-z0-9._:-]+$"
      }
    },
    "relations": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/relation"
      }
    },
    "source_refs": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "string",
        "minLength": 1
      }
    }
  },
  "$defs": {
    "id": {
      "type": "string",
      "pattern": "^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)+$"
    },
    "type_name": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9]*(?:_[a-z0-9]+)*$"
    },
    "relation_type": {
      "enum": [
        "child_of",
        "analysis_of",
        "projection_of",
        "implementation_of",
        "check_of",
        "evidence_for",
        "resolution_of",
        "solution_for",
        "override_of",
        "replacement_of",
        "recurrence_of",
        "relates_to"
      ]
    },
    "relation": {
      "type": "object",
      "required": [
        "type",
        "targets"
      ],
      "additionalProperties": false,
      "properties": {
        "type": {
          "$ref": "#/$defs/relation_type"
        },
        "targets": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/id"
          }
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://raw.githubusercontent.com/anatoly-m-maslennikov/dset-specs-loops-framework/main/.carmadio/000_CARMADIO_METHODOLOGY/02_gov/schemas/change.schema.json",
  "title": "DSET change manifest",
  "type": "object",
  "required": [
    "schema_version",
    "id",
    "profile",
    "status",
    "packages",
    "pull_request",
    "requirements",
    "tests",
    "evals"
  ],
  "additionalProperties": false,
  "properties": {
    "schema_version": {
      "oneOf": [
        {
          "enum": [
            1.0,
            1.1
          ]
        },
        {
          "type": "string",
          "pattern": "^1\\.(?:0|1)-draft$"
        },
        {
          "const": "1.2"
        }
      ]
    },
    "id": {
      "type": "string",
      "minLength": 1
    },
    "slug": {
      "$ref": "#/$defs/kebab"
    },
    "profile": {
      "enum": [
        "small",
        "standard",
        "large",
        "defect",
        "adoption"
      ]
    },
    "status": {
      "enum": [
        "proposed",
        "in-progress",
        "failed",
        "verified",
        "archive-ready",
        "archived"
      ]
    },
    "primary_layer": {
      "$ref": "#/$defs/layer"
    },
    "affected_layers": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/layer"
      }
    },
    "workspace": {
      "$ref": "#/$defs/workspace"
    },
    "dependencies": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/dependency"
      }
    },
    "priority": {
      "$ref": "#/$defs/priority"
    },
    "llm_session_ids": {
      "$ref": "#/$defs/llm_session_ids"
    },
    "rationale": {
      "$ref": "#/$defs/rationale"
    },
    "target": {
      "$ref": "#/$defs/target"
    },
    "packages": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "string"
      }
    },
    "pull_request": {
      "$ref": "#/$defs/pr"
    },
    "release": {
      "oneOf": [
        {
          "$ref": "#/$defs/release"
        },
        {
          "$ref": "#/$defs/layered_release"
        }
      ]
    },
    "intake": {
      "$ref": "#/$defs/intake_ids"
    },
    "related_pull_requests": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/related_pr"
      }
    },
    "requirements": {
      "$ref": "#/$defs/legacy_ids"
    },
    "tests": {
      "$ref": "#/$defs/legacy_ids"
    },
    "evals": {
      "$ref": "#/$defs/legacy_ids"
    },
    "adrs": {
      "$ref": "#/$defs/legacy_ids"
    },
    "decisions": {
      "$ref": "#/$defs/decision_ids"
    },
    "contracts": {
      "$ref": "#/$defs/contract_ids"
    },
    "stories": {
      "$ref": "#/$defs/story_ids"
    },
    "outcomes": {
      "$ref": "#/$defs/outcome_ids"
    },
    "archive": {
      "oneOf": [
        {
          "$ref": "#/$defs/legacy_archive"
        },
        {
          "$ref": "#/$defs/layered_archive"
        }
      ]
    }
  },
  "$defs": {
    "layer": {
      "enum": [
        "meta",
        "gov",
        "tool",
        "skill",
        "ops"
      ]
    },
    "kebab": {
      "type": "string",
      "pattern": "^[a-z0-9]+(?:-[a-z0-9]+)*$"
    },
    "sha_or_pending": {
      "oneOf": [
        {
          "type": "string",
          "pattern": "^[0-9a-f]{40}$"
        },
        {
          "const": "pending"
        }
      ]
    },
