      "type": "object",
      "required": [
        "carrier",
        "sha256",
        "fragments"
      ],
      "additionalProperties": false,
      "properties": {
        "carrier": {
          "type": "string",
          "pattern": "^[^/\\\\]+$"
        },
        "sha256": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        },
        "fragments": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "$ref": "#/$defs/fragment"
