"""Provide DSET artifact emission behavior."""

from __future__ import annotations

import re
from collections.abc import Mapping, Sequence
from pathlib import Path
from typing import Any

from .artifact_routing import parse_artifact_route, route_issues
from .layout import LAYERS, discover_layout
from .lineage import collect_artifact_relations
from .settings import load_project_settings
from .structured_data import load

# SESSION_PATTERN validates session pattern; this module owns the accepted syntax.
SESSION_PATTERN = re.compile(r"^[a-z][a-z0-9_-]*:[A-Za-z0-9._:-]+$")
# AUTHORITY_PATTERN validates authority pattern; this module owns the accepted syntax.
AUTHORITY_PATTERN = re.compile(r"^(?:operator|repository|external):[A-Za-z0-9._:-]+$")

# MEDIUM_FIELDS defines medium fields; this module owns the default.
MEDIUM_FIELDS = (
    "authority",
    "claim",
    "revision_mode",
    "content_role",
    "governance_locus",
    "scope_path",
    "llm_session_ids",
    "material_links",
    "priority",
    "acceptance",
    "promotion",
)
# HIGH_FIELDS defines high fields; this module owns the default.
HIGH_FIELDS = (
    "boundary",
    "lineage",
    "conflict_state",
    "verification_obligation",
)
# FIELD_QUESTIONS defines field questions; this module owns the default.
FIELD_QUESTIONS = {
    "authority": "Who or what authorizes this atomic claim?",
    "claim": "What is the one precise primary claim to preserve?",
    "revision_mode": "How may this artifact change?",
    "content_role": "What one contribution does this artifact make?",
    "governance_locus": (
        "Does this artifact govern an internal subject, an external subject, "
        "or an explicit relation?"
    ),
    "scope_path": "What canonical structural path owns this artifact?",
    "llm_session_ids": "Which explicit LLM session IDs produced this candidate?",
    "material_links": "Which material parent or related artifact IDs apply?",
    "promotion": "What is the immediately broader enabled scope, if any?",
    "boundary": "What exact boundary and exclusions make the claim immutable?",
    "priority": "What effective project priority applies to this artifact?",
    "lineage": "Which immediate parent IDs apply, including an explicit empty list?",
    "acceptance": "What is the explicit acceptance or recording state?",
    "conflict_state": "Is any applicable authority conflict unresolved?",
    "verification_obligation": "What proof obligation applies, including none?",
}
# ALLOWED_PROMOTION_STEPS defines allowed promotion steps; this module owns the default.
ALLOWED_PROMOTION_STEPS = frozenset(
    {
        ("feature", "feature_group"),
        ("feature", "project"),
        ("feature_group", "project"),
        ("layer", "project"),
    }
)


def assess_artifact_candidate(
    root: Path, candidate: Mapping[str, Any]
) -> dict[str, Any]:
    """Assess artifact candidate using the declared repository contract."""
    settings, settings_issues = load_project_settings(root)
    if settings_issues:
        raise ValueError("; ".join(settings_issues))
    strictness = settings.artifact_creation_strictness
    fields = MEDIUM_FIELDS + (HIGH_FIELDS if strictness == "high" else ())
    diagnostics: list[dict[str, str]] = []
    questions: list[str] = []

    for field in fields:
        if not _has_explicit_value(candidate, field):
            diagnostics.append(
                {
                    "code": "CARMADIO-ARTIFACT-MISSING",
                    "field": field,
                    "message": f"material field is not explicit: {field}",
                }
            )
            questions.append(FIELD_QUESTIONS[field])

    diagnostics.extend(_shape_diagnostics(candidate))
    diagnostics.extend(_value_diagnostics(root, candidate, settings.priority_scale))
    unknown_diagnostics, unknown_questions = _unknown_diagnostics(candidate)
    diagnostics.extend(unknown_diagnostics)
    questions.extend(unknown_questions)

    scope_model, scope_diagnostics = _repository_scope_model(root)
    diagnostics.extend(scope_diagnostics)
    promotion = _assess_promotion(candidate, scope_model)
    if promotion["status"] == "invalid":
        diagnostics.append(
            {
                "code": "CARMADIO-ARTIFACT-PROMOTION",
                "field": "promotion.parent_scope",
                "message": str(
                    promotion.get("reason", "promotion assessment is invalid")
                ),
            }
        )
    elif promotion["status"] == "proposal-required":
        diagnostics.append(
            {
                "code": "CARMADIO-ARTIFACT-PROMOTION-AUTHORITY",
                "field": "promotion.disposition",
                "message": (
                    "eligible broader-scope promotion needs operator disposition"
                ),
            }
        )
        questions.append(str(promotion["question"]))
    elif promotion["status"] == "promote-before-emission":
        diagnostics.append(
            {
                "code": "CARMADIO-ARTIFACT-PROMOTE-FIRST",
                "field": "scope_path",
                "message": "rebuild the candidate at the accepted broader scope",
            }
        )

    result = {
        "schema_version": "1.0",
        "strictness": strictness,
        "emission_allowed": not diagnostics,
        "diagnostics": diagnostics,
        "questions": _unique(questions),
        "promotion": promotion,
        "writes_performed": False,
    }
    if not route_issues(candidate):
        result["route"] = parse_artifact_route(candidate).as_dict()
    return result


def _has_explicit_value(candidate: Mapping[str, Any], field: str) -> bool:
    """Handle explicit value using the declared repository contract."""
    if field not in candidate:
        return False
    value = candidate[field]
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    return True


def _shape_diagnostics(candidate: Mapping[str, Any]) -> list[dict[str, str]]:
    """Handle diagnostics using the declared repository contract."""
    diagnostics = [
        {
            "code": "CARMADIO-ARTIFACT-ROUTE",
            "field": _route_issue_field(issue),
            "message": issue,
        }
        for issue in route_issues(candidate)
    ]
    for field in ("llm_session_ids", "material_links", "lineage"):
        if field in candidate and not _is_string_sequence(candidate[field]):
            diagnostics.append(
                {
                    "code": "CARMADIO-ARTIFACT-SHAPE",
                    "field": field,
                    "message": f"{field} must be a list of strings",
                }
            )
    if "promotion" in candidate and not isinstance(candidate["promotion"], Mapping):
        diagnostics.append(
            {
                "code": "CARMADIO-ARTIFACT-PROMOTION",
                "field": "promotion",
                "message": "promotion must be an object",
            }
        )
    return diagnostics


def _value_diagnostics(
    root: Path, candidate: Mapping[str, Any], priorities: Sequence[str]
) -> list[dict[str, str]]:
    """Handle diagnostics using the declared repository contract."""
    diagnostics: list[dict[str, str]] = []
    authority = candidate.get("authority")
    if isinstance(authority, str) and not AUTHORITY_PATTERN.fullmatch(authority):
        diagnostics.append(
            {
                "code": "CARMADIO-ARTIFACT-AUTHORITY",
                "field": "authority",
                "message": (
                    "authority must use operator:, repository:, or external: "
                    "with a stable authority ID"
                ),
            }
        )
    sessions = candidate.get("llm_session_ids")
    if _is_string_sequence(sessions):
        assert isinstance(sessions, Sequence) and not isinstance(sessions, str)
        normalized = [str(item) for item in sessions]
        if len(normalized) != len(set(normalized)) or any(
            not SESSION_PATTERN.fullmatch(item) for item in normalized
        ):
            diagnostics.append(
                {
                    "code": "CARMADIO-ARTIFACT-SESSION",
                    "field": "llm_session_ids",
                    "message": "LLM session IDs must be unique provider:id values",
                }
            )
    priority = candidate.get("priority")
    if isinstance(priority, str) and priority not in {*priorities, "unknown"}:
        diagnostics.append(
            {
                "code": "CARMADIO-ARTIFACT-PRIORITY",
                "field": "priority",
                "message": "priority is not in the repository priority scale",
            }
        )
    acceptance = candidate.get("acceptance")
    if isinstance(acceptance, str) and acceptance not in {"proposed", "accepted"}:
        diagnostics.append(
            {
                "code": "CARMADIO-ARTIFACT-ACCEPTANCE",
                "field": "acceptance",
                "message": "acceptance must be proposed or accepted",
            }
        )
    conflict_state = candidate.get("conflict_state")
    if isinstance(conflict_state, str) and conflict_state not in {
        "clear",
        "unresolved",
    }:
        diagnostics.append(
            {
                "code": "CARMADIO-ARTIFACT-CONFLICT",
                "field": "conflict_state",
                "message": "conflict_state must be clear or unresolved",
            }
        )
    diagnostics.extend(_link_diagnostics(root, candidate))
    return diagnostics


def _link_diagnostics(root: Path, candidate: Mapping[str, Any]) -> list[dict[str, str]]:
    """Handle diagnostics using the declared repository contract."""
    requested: set[str] = set()
    for field in ("material_links", "lineage"):
        value = candidate.get(field)
        if _is_string_sequence(value):
            assert isinstance(value, Sequence) and not isinstance(value, str)
            requested.update(str(item) for item in value)
    if not requested:
        return []
    known: set[str] = set()
    try:
        nodes, relation_issues = collect_artifact_relations(root)
        if not relation_issues:
            for node in nodes.values():
                known.update((node.id, node.artifact_id))
    except (OSError, ValueError):
        pass
    missing = sorted(requested - known)
    if not missing:
        return []
    return [
        {
            "code": "CARMADIO-ARTIFACT-LINK",
            "field": "material_links",
            "message": f"linked artifact IDs do not resolve: {', '.join(missing)}",
        }
    ]


def _unknown_diagnostics(
    candidate: Mapping[str, Any],
) -> tuple[list[dict[str, str]], list[str]]:
    """Handle diagnostics using the declared repository contract."""
    raw_unknowns = candidate.get("unknowns", [])
    if not isinstance(raw_unknowns, Sequence) or isinstance(raw_unknowns, str):
        return (
            [
                {
                    "code": "CARMADIO-ARTIFACT-SHAPE",
                    "field": "unknowns",
                    "message": "unknowns must be a list of objects",
                }
            ],
            ["Which candidate details remain unknown, and are they material?"],
        )
    diagnostics: list[dict[str, str]] = []
    questions: list[str] = []
    for index, item in enumerate(raw_unknowns):
        if not isinstance(item, Mapping):
            diagnostics.append(
                {
                    "code": "CARMADIO-ARTIFACT-SHAPE",
                    "field": f"unknowns[{index}]",
                    "message": "unknown entry must be an object",
                }
            )
            continue
        if item.get("material") is not True:
            continue
        field = str(item.get("field", f"unknowns[{index}]"))
        question = str(item.get("question", "")).strip()
        diagnostics.append(
            {
                "code": "CARMADIO-ARTIFACT-AMBIGUOUS",
                "field": field,
                "message": "material ambiguity blocks immutable emission",
            }
        )
        questions.append(question or f"What precise value resolves {field}?")
    return diagnostics, questions


def _assess_promotion(
    candidate: Mapping[str, Any], scope_model: Mapping[str, Any] | None
) -> dict[str, Any]:
    """Assess promotion using the declared repository contract."""
    raw = candidate.get("promotion")
    if not isinstance(raw, Mapping):
        return {"status": "not-assessed", "eligible": False}
    scope = _scope_from_path(candidate.get("scope_path"))
    if (
        scope is None
        and candidate.get("scope_path") == []
        and scope_model is not None
    ):
        scope = dict(scope_model["project_scope"])
    if not _valid_scope(scope):
        return {"status": "invalid", "eligible": False}
    assert isinstance(scope, Mapping)
    current_key = (str(scope["kind"]), str(scope["id"]))
    if scope_model is None or current_key not in scope_model["scopes"]:
        return {
            "status": "invalid",
            "eligible": False,
            "reason": "scope is not enabled by the repository manifest",
        }
    parent = raw.get("parent_scope")
    if parent is None:
        if scope_model["parents"].get(current_key) is not None:
            return {
                "status": "invalid",
                "eligible": False,
                "reason": "the enabled local scope requires its immediate parent",
            }
        return {
            "status": "not-applicable",
            "eligible": False,
            "reason": "no broader enabled scope",
        }
    if not _valid_scope(parent):
        return {"status": "invalid", "eligible": False}
    assert isinstance(parent, Mapping)
    current_kind = str(scope["kind"])
    parent_kind = str(parent["kind"])
    parent_key = (parent_kind, str(parent["id"]))
    actual_parent = scope_model["parents"].get(current_key)
    if actual_parent != parent_key:
        return {
            "status": "invalid",
            "eligible": False,
            "reason": "parent_scope is not the manifest-defined immediate parent",
        }
    if (current_kind, parent_kind) not in ALLOWED_PROMOTION_STEPS:
        return {
            "status": "invalid",
            "eligible": False,
            "reason": "parent_scope is not an allowed immediate broader step",
        }
    affected = raw.get("affected_children")
    actual_children = scope_model["children"].get(parent_key, ())
    affected_items: tuple[str, ...] = ()
    if _is_string_sequence(affected):
        assert isinstance(affected, Sequence) and not isinstance(affected, str)
        affected_items = tuple(str(item) for item in affected)
    affected_matches = set(affected_items) == set(actual_children)
    eligible = (
        raw.get("applies_unchanged") is True
        and raw.get("local_context_required") is False
        and affected_matches
        and bool(actual_children)
    )
    if not eligible:
        return {
            "status": "keep-local",
            "eligible": False,
            "reason": "claim changes across children or requires local context",
        }
    disposition = raw.get("disposition")
    affected_children = list(affected_items)
    proposal = (
        f"Promote the unchanged claim from {scope['kind']}:{scope['id']} to "
        f"{parent['kind']}:{parent['id']} for {', '.join(affected_children)}?"
    )
    if disposition == "keep_local":
        status = "declined"
    elif disposition == "promote":
        status = "promote-before-emission"
    else:
        status = "proposal-required"
    return {
        "status": status,
        "eligible": True,
        "from_scope": dict(scope),
        "to_scope": dict(parent),
        "affected_children": affected_children,
        "question": proposal,
        "automatic": False,
    }


def _repository_scope_model(
    root: Path,
) -> tuple[dict[str, Any] | None, list[dict[str, str]]]:
    """Handle scope model using the declared repository contract."""
    try:
        layout = discover_layout(root)
        manifest = load(layout.manifest_path)
    except (OSError, ValueError) as error:
        return None, [
            {
                "code": "CARMADIO-ARTIFACT-REPOSITORY",
                "field": "scope_path",
                "message": f"repository scope authority is unavailable: {error}",
            }
        ]
    project = manifest.get("project") if isinstance(manifest, Mapping) else None
    project_id = project.get("id") if isinstance(project, Mapping) else None
    if not isinstance(project_id, str) or not project_id.strip():
        return None, [
            {
                "code": "CARMADIO-ARTIFACT-REPOSITORY",
                "field": "scope_path",
                "message": "project manifest requires project.id",
            }
        ]
    project_key = ("project", project_id)
    scopes: set[tuple[str, str]] = {project_key}
    parents: dict[tuple[str, str], tuple[str, str]] = {}
    children: dict[tuple[str, str], tuple[str, ...]] = {}
    if layout.layered:
        layer_keys = [("layer", layer) for layer in LAYERS]
        scopes.update(layer_keys)
        parents.update({key: project_key for key in layer_keys})
        children[project_key] = LAYERS
    return {
        "scopes": scopes,
        "parents": parents,
        "children": children,
        "project_scope": {"kind": "project", "id": project_id},
    }, []


def _valid_scope(value: object) -> bool:
    """Handle scope using the declared repository contract."""
    return (
        isinstance(value, Mapping)
        and isinstance(value.get("kind"), str)
        and bool(str(value["kind"]).strip())
        and isinstance(value.get("id"), str)
        and bool(str(value["id"]).strip())
    )


def _scope_from_path(value: object) -> dict[str, str] | None:
    """Return the leaf structural owner used by promotion checks."""
    if not isinstance(value, list) or not value:
        return None
    leaf = value[-1]
    if not isinstance(leaf, str) or ":" not in leaf:
        return None
    kind, identifier = leaf.split(":", 1)
    scope = {"kind": kind, "id": identifier}
    return scope if _valid_scope(scope) else None


def _route_issue_field(issue: str) -> str:
    """Recover the route field named at the start of a validation issue."""
    field = issue.split(" ", 1)[0]
    return field.split("[", 1)[0]


def _is_string_sequence(value: object) -> bool:
    return (
        isinstance(value, Sequence)
        and not isinstance(value, str)
        and all(isinstance(item, str) and bool(item.strip()) for item in value)
    )


def _unique(values: Sequence[str]) -> list[str]:
    return list(dict.fromkeys(value for value in values if value))

"""Provide DSET commit provenance behavior."""

from __future__ import annotations

import hashlib
import re
import subprocess
from collections.abc import Mapping
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .diagnostics import Diagnostic
from .layout import discover_layout
from .semantic_types import build_semantic_classification_index
from .structured_data import load

# ID_PATTERN validates id pattern; this module owns the accepted syntax.
ID_PATTERN = re.compile(r"[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)+")
# SESSION_PATTERN validates session pattern; this module owns the accepted syntax.
SESSION_PATTERN = re.compile(r"^[a-z][a-z0-9_-]*:[A-Za-z0-9._:-]+$")
# COMMIT_PATTERN validates commit pattern; this module owns the accepted syntax.
COMMIT_PATTERN = re.compile(r"^[0-9a-f]{40}$")
# DIGEST_PATTERN validates digest pattern; this module owns the accepted syntax.
DIGEST_PATTERN = re.compile(r"^[0-9a-f]{64}$")
# CORRECTION_FIELDS defines correction fields; this module owns the default.
CORRECTION_FIELDS = {
    "commit",
    "original_message_sha256",
    "mode",
    "decision_ids",
    "verifies",
    "resolves",
    "session",
    "rationale",
}


@dataclass(frozen=True)
class CommitRecord:
    """Represent commit record behavior and state."""

    commit: str
    message: str
    message_sha256: str


def validate_commit_provenance(root: Path) -> list[Diagnostic]:
    """Validate commit provenance using the declared repository contract."""
    root = root.resolve()
    if not (root / ".git").exists():
        return []
    manifest_path = discover_layout(root).manifest_path
    manifest = load(manifest_path)
    raw_policy = (
        manifest.get("commit_provenance") if isinstance(manifest, dict) else None
    )
    if not isinstance(raw_policy, Mapping):
        return [
            Diagnostic(
                "CARMADIO-E168",
                manifest_path,
                "project manifest requires commit_provenance policy",
            )
        ]
    start = raw_policy.get("start_commit")
    if not isinstance(start, str) or not start:
        return [
            Diagnostic(
                "CARMADIO-E168",
                manifest_path,
                "commit_provenance.start_commit is required",
            )
        ]
    if not _has_head(root):
        return []
    try:
        base = _resolve_base(root, manifest_path, start)
        commits = _commits_after(root, base)
        known = {
            str(row["id"]): (str(row["type"]), str(row["subtype"]))
            for row in build_semantic_classification_index(root)
        }
    except (OSError, ValueError, subprocess.CalledProcessError) as error:
        return [Diagnostic("CARMADIO-E168", manifest_path, str(error))]
    return [
        Diagnostic("CARMADIO-E168", manifest_path, problem)
        for problem in validate_commit_history(
            commits, known, raw_policy.get("corrections", [])
        )
    ]


def validate_commit_history(
    commits: list[CommitRecord],
    known: Mapping[str, tuple[str, str]],
    raw_corrections: object,
) -> list[str]:
    """Validate commit history using the declared repository contract."""
    corrections, problems = _parse_corrections(raw_corrections, commits)
    for record in commits:
        original_problems = validate_commit_message(record.message, known)
        correction = corrections.get(record.commit)
        if correction is None:
            problems.extend(
                f"commit {record.commit[:12]}: {problem}"
                for problem in original_problems
            )
            continue
        if not original_problems:
            problems.append(
                f"correction for commit {record.commit} is unnecessary because "
                "the original provenance is valid"
            )
            continue
        corrected_message = _corrected_message(correction)
        problems.extend(
            f"correction for commit {record.commit}: {problem}"
            for problem in validate_commit_message(corrected_message, known)
        )
    return problems


def validate_commit_message(
    message: str, known: Mapping[str, tuple[str, str]]
) -> list[str]:
    """Validate commit message using the declared repository contract."""
    trailers = _trailers(message)
    sessions = trailers.get("Session", [])
    if len(sessions) != 1 or not SESSION_PATTERN.fullmatch(sessions[0]):
        session_problem = "requires exactly one valid Session trailer"
    else:
        session_problem = ""
    implements = _ids(trailers.get("Implements", []))
    decisions = _ids(trailers.get("Decision", []))
    verifies = _ids(trailers.get("Verifies", []))
    problems: list[str] = [session_problem] if session_problem else []
    if implements and (decisions or verifies):
        problems.append("cannot mix implementation and evidence provenance modes")
    elif implements:
        problems.extend(_authority_reference_problems("Implements", implements, known))
    elif decisions and verifies:
        problems.extend(_authority_reference_problems("Decision", decisions, known))
        problems.extend(_known_reference_problems("Verifies", verifies, known))
    else:
        problems.append(
            "requires Implements, or the evidence pair Decision and Verifies"
        )
    resolves = _ids(trailers.get("Resolves", []))
    for identifier in resolves:
        classification = known.get(identifier)
        if classification is None:
            problems.append(f"Resolves references unknown ID: {identifier}")
        elif classification[0] != "problem":
            problems.append(f"Resolves must reference a Problem: {identifier}")
    return problems


def _parse_corrections(
    raw_corrections: object, commits: list[CommitRecord]
) -> tuple[dict[str, Mapping[str, Any]], list[str]]:
    """Parse corrections using the declared repository contract."""
    if not isinstance(raw_corrections, list):
        return {}, ["commit_provenance.corrections must be a list"]
    records = {record.commit: record for record in commits}
    corrections: dict[str, Mapping[str, Any]] = {}
    problems: list[str] = []
    for index, raw in enumerate(raw_corrections, start=1):
        prefix = f"commit_provenance.corrections[{index}]"
        if not isinstance(raw, Mapping):
            problems.append(f"{prefix} must be a mapping")
            continue
        fields = set(raw)
        if fields != CORRECTION_FIELDS:
            missing = sorted(CORRECTION_FIELDS - fields)
            extra = sorted(fields - CORRECTION_FIELDS)
            details: list[str] = []
            if missing:
                details.append(f"missing {', '.join(missing)}")
            if extra:
                details.append(f"unknown {', '.join(extra)}")
            problems.append(f"{prefix} fields are invalid: {'; '.join(details)}")
            continue
        commit = raw.get("commit")
        if not isinstance(commit, str) or not COMMIT_PATTERN.fullmatch(commit):
            problems.append(f"{prefix}.commit requires one full lowercase SHA")
            continue
        if commit in corrections:
            problems.append(f"duplicate provenance correction for commit {commit}")
            continue
        record = records.get(commit)
        if record is None:
            problems.append(
                f"provenance correction commit is outside the validated range: {commit}"
            )
            continue
        digest = raw.get("original_message_sha256")
        if not isinstance(digest, str) or not DIGEST_PATTERN.fullmatch(digest):
            problems.append(f"{prefix}.original_message_sha256 is invalid")
            continue
        if digest != record.message_sha256:
            problems.append(
                f"provenance correction message digest mismatch for commit {commit}"
            )
            continue
        mode = raw.get("mode")
        if mode not in {"implementation", "evidence"}:
            problems.append(f"{prefix}.mode must be implementation or evidence")
            continue
        if not _valid_id_list(raw.get("decision_ids"), allow_empty=False):
            problems.append(f"{prefix}.decision_ids requires unique canonical IDs")
            continue
        verifies = raw.get("verifies")
        if not _valid_id_list(verifies, allow_empty=mode == "implementation"):
            problems.append(
                f"{prefix}.verifies must be empty for implementation or contain "
                "unique canonical IDs for evidence"
            )
            continue
        if mode == "implementation" and verifies:
            problems.append(f"{prefix}.verifies must be empty for implementation")
            continue
        if not _valid_id_list(raw.get("resolves"), allow_empty=True):
            problems.append(f"{prefix}.resolves must contain unique canonical IDs")
            continue
        session = raw.get("session")
        if not isinstance(session, str) or not SESSION_PATTERN.fullmatch(session):
            problems.append(f"{prefix}.session requires exactly one valid session ID")
            continue
        rationale = raw.get("rationale")
        if not isinstance(rationale, str) or not rationale.strip():
            problems.append(f"{prefix}.rationale requires non-empty text")
            continue
        corrections[commit] = raw
    return corrections, problems


def _valid_id_list(value: object, *, allow_empty: bool) -> bool:
    if not isinstance(value, list) or (not allow_empty and not value):
        return False
    if not all(isinstance(item, str) and ID_PATTERN.fullmatch(item) for item in value):
        return False
    return len(value) == len(set(value))


def _corrected_message(correction: Mapping[str, Any]) -> str:
    """Handle message using the declared repository contract."""
    label = "Implements" if correction["mode"] == "implementation" else "Decision"
    lines = [f"{label}: {', '.join(correction['decision_ids'])}"]
    if correction["verifies"]:
        lines.append(f"Verifies: {', '.join(correction['verifies'])}")
    if correction["resolves"]:
        lines.append(f"Resolves: {', '.join(correction['resolves'])}")
    lines.append(f"Session: {correction['session']}")
    return "\n".join(lines)


def _resolve_base(root: Path, manifest_path: Path, start: str) -> str | None:
    """Resolve base using the declared repository contract."""
    if start == "root":
        return None
    if start == "manifest-addition":
        relative = manifest_path.relative_to(root).as_posix()
        completed = subprocess.run(
            [
                "git",
                "log",
                "--reverse",
                "--format=%H",
                "--diff-filter=A",
                "--",
                relative,
            ],
            cwd=root,
            check=True,
            capture_output=True,
            text=True,
        )
        commits = completed.stdout.split()
        return commits[0] if commits else None
    completed = subprocess.run(
        ["git", "rev-parse", "--verify", f"{start}^{{commit}}"],
        cwd=root,
        check=True,
        capture_output=True,
        text=True,
    )
    return completed.stdout.strip()


def _commits_after(root: Path, base: str | None) -> list[CommitRecord]:
    """Handle after using the declared repository contract."""
    revision = f"{base}..HEAD" if base else "HEAD"
    completed = subprocess.run(
        ["git", "rev-list", "--no-merges", "--reverse", revision],
        cwd=root,
        check=True,
        capture_output=True,
        text=True,
    )
    return [_read_commit(root, commit) for commit in completed.stdout.split()]


def _read_commit(root: Path, commit: str) -> CommitRecord:
    """Read commit using the declared repository contract."""
    completed = subprocess.run(
        ["git", "cat-file", "commit", commit],
        cwd=root,
        check=True,
        capture_output=True,
    )
    _headers, separator, message = completed.stdout.partition(b"\n\n")
    if not separator:
        raise ValueError(f"commit object has no message boundary: {commit}")
    return CommitRecord(
        commit=commit,
        message=message.decode("utf-8", errors="surrogateescape"),
        message_sha256=hashlib.sha256(message).hexdigest(),
    )


def _has_head(root: Path) -> bool:
    """Handle head using the declared repository contract."""
    completed = subprocess.run(
        ["git", "rev-parse", "--verify", "HEAD"],
        cwd=root,
        check=False,
        capture_output=True,
        text=True,
    )
    return completed.returncode == 0


def _trailers(message: str) -> dict[str, list[str]]:
    """Handle trailers using the declared repository contract."""
    found: dict[str, list[str]] = {}
    for line in message.splitlines():
        key, separator, value = line.partition(":")
        if separator and key in {
            "Implements",
            "Decision",
            "Verifies",
            "Resolves",
            "Session",
        }:
            found.setdefault(key, []).append(value.strip())
    return found


def _ids(values: list[str]) -> set[str]:
    return {identifier for value in values for identifier in ID_PATTERN.findall(value)}


def _authority_reference_problems(
    label: str,
    identifiers: set[str],
    known: Mapping[str, tuple[str, str]],
) -> list[str]:
    problems = _known_reference_problems(label, identifiers, known)
    for identifier in identifiers:
        if identifier in known and known[identifier][0] != "decision":
            problems.append(f"{label} must reference a Decision: {identifier}")
    return problems


def _known_reference_problems(
    label: str,
    identifiers: set[str],
    known: Mapping[str, tuple[str, str]],
) -> list[str]:
    """Handle reference problems using the declared repository contract."""
    if not identifiers:
        return [f"{label} requires at least one canonical ID"]
    return [
        f"{label} references unknown ID: {identifier}"
        for identifier in sorted(identifiers)
        if identifier not in known
    ]

"""Provide DSET compilation behavior."""

from __future__ import annotations

import hashlib
import re
from pathlib import Path
from typing import Any

from .identity import iter_control_files, logical_part
from .layout import LAYERS, discover_layout
from .semantic_atoms import collect_semantic_atoms
from .semantic_types import build_semantic_classification_index
from .structured_data import StructuredDataError, dump, load

# DECISION_FIELDS defines decision fields; this module owns the default.
DECISION_FIELDS = ("requirements", "contracts", "stories", "outcomes")
# IGNORED_PARTS defines ignored parts; this module owns the default.
IGNORED_PARTS = frozenset(
    {
        ".git",
        ".cache",
        ".venv",
        "__pycache__",
        "dist",
        "generated",
        "templates",
        "archive",
    }
)


def build_compilation_index(root: Path) -> dict[str, Any]:
    """Build compilation index using the declared repository contract."""
    root = root.resolve()
    sources = _authority_sources(root)
    projections = _projection_paths(root)
    records: list[dict[str, Any]] = []
    missing: list[str] = []
    for identifier, source in sorted(sources.items()):
        owners = [
            (path, _projection_fragments(path, identifier)) for path in projections
        ]
        owners = [(path, fragments) for path, fragments in owners if fragments]
        if not owners:
            missing.append(identifier)
            continue
        records.append(
            {
                "id": identifier,
                "source": {
                    "carrier": source.name,
                    "sha256": _digest(source),
                },
                "projections": [
                    {
                        "carrier": path.name,
                        "sha256": _digest(path),
                        "fragments": fragments,
                    }
                    for path, fragments in owners
                ],
            }
        )
    if missing:
        raise ValueError(
            "active Decision authority lacks an evergreen projection: "
            + ", ".join(missing)
        )
    return {
        "schema_version": "1.0",
        "records": records,
    }


def compilation_path(root: Path) -> Path:
    """Handle path using the declared repository contract."""
    layout = discover_layout(root.resolve())
    generated = (
        layout.traceability_path.parent
        if layout.layered
        else layout.carmadio_root / "generated"
    )
    suffix = ".toml" if layout.manifest_path.suffix == ".toml" else ".yaml"
    return layout.structured_file(generated, f"compilation{suffix}")


def rendered_compilation(root: Path) -> str:
    """Handle compilation using the declared repository contract."""
    return dump(build_compilation_index(root), compilation_path(root))


def compilation_is_fresh(root: Path) -> bool:
    """Handle is fresh using the declared repository contract."""
    path = compilation_path(root)
    try:
        rendered = rendered_compilation(root)
    except ValueError:
        return False
    return path.is_file() and path.read_text(encoding="utf-8") == rendered


def write_compilation(root: Path) -> Path:
    """Write compilation using the declared repository contract."""
    path = compilation_path(root)
    content = rendered_compilation(root)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(content, encoding="utf-8")
    temporary.replace(path)
    return path


def active_authority_ids(root: Path) -> set[str]:
    """Handle authority ids using the declared repository contract."""
    return set(_authority_sources(root.resolve()))


def projected_authority_ids(root: Path) -> set[str]:
    """Return authorities with an explicit evergreen claim fragment."""
    root = root.resolve()
    sources = _authority_sources(root)
    projections = _projection_paths(root)
    return {
        identifier
        for identifier in sources
        if any(_projection_fragments(path, identifier) for path in projections)
    }


def _authority_sources(root: Path) -> dict[str, Path]:
    """Collect every active Decision authority carrier."""
    archived = {
        str(item["id"])
        for item in build_semantic_classification_index(root)
        if item.get("archived") is True
    }
    sources: dict[str, Path] = {}
    _collect_atomic_authority(root, archived, sources)
    _collect_legacy_decisions(root, archived, sources)
    _collect_package_authority(root, archived, sources)
    return sources


def _collect_atomic_authority(
    root: Path, archived: set[str], sources: dict[str, Path]
) -> None:
    """Collect accepted atomic Decisions that remain active."""
    atoms, diagnostics = collect_semantic_atoms(root)
    if diagnostics:
        raise ValueError(diagnostics[0].message)
    for atom in atoms.values():
        if (
            atom.semantic_type == "decision"
            and atom.emission_status == "accepted"
            and atom.semantic_id not in archived
        ):
            sources[atom.semantic_id] = root / atom.path


def _collect_legacy_decisions(
    root: Path, archived: set[str], sources: dict[str, Path]
) -> None:
    """Collect accepted pre-atom Decision documents."""
    layout = discover_layout(root)
    paths = iter_control_files(root, "*.md") if layout.separated else root.rglob("*.md")
    for path in paths:
        if _ignored(root, path) or (
            path.parent.name != "decision"
            and not path.name.lower().startswith("decision-")
        ):
            continue
        text = _read(path)
        match = re.search(r"\*\*Decision ID:\*\*\s*`([^`]+)`", text)
        if not match or "**Status:** accepted" not in text:
            continue
        identifier = match.group(1)
        if identifier not in archived:
            sources[identifier] = path


def _collect_package_authority(
    root: Path, archived: set[str], sources: dict[str, Path]
) -> None:
    """Collect compatibility Decision lists from package carriers."""
    for path in discover_layout(root).structured_named_files(root, "package"):
        if _ignored(root, path) or "specs" not in path.parts:
            continue
        try:
            data = load(path)
        except (OSError, UnicodeError, StructuredDataError):
            continue
        if not isinstance(data, dict):
            continue
        for field in DECISION_FIELDS:
            values = data.get(field, [])
            if not isinstance(values, list):
                continue
            for identifier in values:
                if isinstance(identifier, str) and identifier not in archived:
                    sources.setdefault(identifier, path)


def _projection_paths(root: Path) -> list[Path]:
    """Handle paths using the declared repository contract."""
    layout = discover_layout(root)
    if layout.recursive or layout.separated:
        prefixes = ("specification-", "procedure-", "plan-", "navigation-")
        owners = (
            layout.project_root,
            *(layout.layer_root(layer) for layer in LAYERS),
            layout.carmadio_root,
        )
        return [
            path
            for owner in owners
            for path in sorted(owner.rglob("*.md"))
            if not _ignored(root, path) and path.name.lower().startswith(prefixes)
        ]
    if layout.slim:
        prefixes = (
            "specification-",
            "procedure-",
            "plan-",
            "dset-specification-",
        )
        return [
            path
            for path in sorted(layout.carmadio_root.rglob("*.md"))
            if not _ignored(root, path) and path.name.lower().startswith(prefixes)
        ]
    return [
        path
        for path in sorted(root.rglob("*.md"))
        if not _ignored(root, path)
        and ("specs" in path.parts or "governance" in path.parts)
    ]


def _ignored(root: Path, path: Path) -> bool:
    """Handle ignored using the declared repository contract."""
    relative = path.relative_to(root)
    if relative.parts[:1] == (".carmadio_runtime",) or relative.parts[:2] == (
        ".carmadio",
        "runtime",
    ):
        return True
    return any(
        logical_part(part) in IGNORED_PARTS
        or (part.startswith(".") and part not in {".github", ".carmadio"})
        for part in relative.parts
    )


def _read(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except (OSError, UnicodeError):
        return ""


def _projection_fragments(path: Path, identifier: str) -> list[dict[str, Any]]:
    """Extract only explicit evergreen claim structures, never loose mentions."""
    lines = _read(path).splitlines()
    fragments: list[dict[str, Any]] = []
    escaped = re.escape(identifier)
    heading = re.compile(rf"^(#{{1,6}})\s+`?{escaped}`?(?:\s|$)")
    table = re.compile(rf"^\|\s*`?{escaped}`?\s*\|")
    labeled = re.compile(rf"^\*\*[^*\n]*\b{escaped}\b[^*\n]*:\*\*")
    for index, line in enumerate(lines):
        match = heading.match(line)
        kind: str | None = None
        end = index + 1
        if match:
            kind = "section"
            level = len(match.group(1))
            while end < len(lines):
                next_heading = re.match(r"^(#{1,6})\s+", lines[end])
                if next_heading and len(next_heading.group(1)) <= level:
                    break
                end += 1
        elif table.match(line):
            kind = "table-row"
        elif labeled.match(line):
            kind = "labeled-block"
            while end < len(lines) and lines[end].strip():
                end += 1
        if kind is None:
            continue
        content = "\n".join(lines[index:end]).strip()
        fragments.append(
            {
                "kind": kind,
                "line": index + 1,
                "sha256": hashlib.sha256(content.encode()).hexdigest(),
            }
        )
    return fragments


def _digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

"""Configure optional DSET governance surfaces.

Commands inspect or preview one repository-local ``carmadio_settings.toml``.
Writes require an explicit execute flag and preserve unrelated TOML text.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path

from .errors import DsetCommandError
from .settings import GOVERNANCE_SURFACE_KEYS, selected_settings_path
from .toml_codec import TomlCodecError
from .toml_codec import load as load_toml

# SURFACE_IDS maps readable CLI identities to canonical TOML keys.
SURFACE_IDS = {
    key.replace("_", "-"): key for key in GOVERNANCE_SURFACE_KEYS
}
# _TABLE_HEADER recognizes the one owned settings table.
_TABLE_HEADER = re.compile(r"^\s*\[governance_surfaces\]\s*(?:#.*)?$")
# _ANY_TABLE_HEADER recognizes the boundary of the next TOML table.
_ANY_TABLE_HEADER = re.compile(r"^\s*\[\[?[A-Za-z0-9_.\"'-]+\]?\]\s*(?:#.*)?$")


@dataclass(frozen=True)
class SurfaceChange:
    """Describe one previewed governance-surface state change."""

    settings_path: Path
    surface_id: str
    before: bool
    after: bool
    changed: bool

    def as_dict(self) -> dict[str, str | bool]:
        """Return a stable command-facing representation."""
        return {
            "settings_path": self.settings_path.as_posix(),
            "surface": self.surface_id,
            "before": self.before,
            "after": self.after,
            "changed": self.changed,
        }


def surface_states(root: Path) -> dict[str, bool]:
    """Return all registered surface states, defaulting missing keys to false."""
    path, table = _surface_table(root)
    unknown = sorted(set(table) - set(GOVERNANCE_SURFACE_KEYS))
    if unknown:
        raise _settings_error(
            path,
            "unknown governance surface: " + ", ".join(unknown),
        )
    states: dict[str, bool] = {}
    for surface_id, key in SURFACE_IDS.items():
        value = table.get(key, False)
        if not isinstance(value, bool):
            raise _settings_error(path, f"governance_surfaces.{key} must be boolean")
        states[surface_id] = value
    return states


def plan_surface_change(
    root: Path,
    surface_id: str,
    *,
    active: bool,
) -> SurfaceChange:
    """Preview one activation or deactivation without changing the repository."""
    canonical_id = _surface_id(surface_id)
    states = surface_states(root)
    before = states[canonical_id]
    return SurfaceChange(
        settings_path=selected_settings_path(root),
        surface_id=canonical_id,
        before=before,
        after=active,
        changed=before != active,
    )


def execute_surface_change(change: SurfaceChange) -> None:
    """Apply a previewed change while preserving unrelated TOML text."""
    if not change.changed:
        return
    path = change.settings_path
    text = path.read_text(encoding="utf-8")
    updated = _updated_settings_text(
        text,
        SURFACE_IDS[change.surface_id],
        change.after,
    )
    path.write_text(updated, encoding="utf-8")


def surface_recommendations(root: Path) -> tuple[dict[str, str], ...]:
    """Recommend only reactivation supported by an existing retained carrier."""
    states = surface_states(root)
    recommendations: list[dict[str, str]] = []
    for surface_id, active in states.items():
        if active:
            continue
        carriers = _matching_carriers(root, surface_id)
        if carriers:
            recommendations.append(
                {
                    "surface": surface_id,
                    "reason": "inactive surface has retained carrier",
                    "evidence": carriers[0],
                }
            )
    return tuple(recommendations)


def _surface_table(root: Path) -> tuple[Path, dict[str, object]]:
    """Read the selected settings carrier and its optional surface table."""
    path = selected_settings_path(root)
    if not path.is_file():
        raise _settings_error(path, "DSET settings carrier does not exist")
    try:
        raw = load_toml(path)
    except (OSError, UnicodeError, TomlCodecError) as error:
        raise _settings_error(path, f"cannot read settings: {error}") from error
    table = raw.get("governance_surfaces", {})
    if not isinstance(table, dict):
        raise _settings_error(path, "governance_surfaces must be a TOML table")
    return path, table


def _surface_id(value: str) -> str:
    """Normalize and validate one operator-facing surface identity."""
    normalized = value.replace("_", "-")
    if normalized not in SURFACE_IDS:
        raise ValueError(
            "surface must be one of: " + ", ".join(SURFACE_IDS)
        )
    return normalized


def _updated_settings_text(text: str, key: str, active: bool) -> str:
    """Update one key and materialize explicit defaults for missing peers."""
    newline = "\r\n" if "\r\n" in text else "\n"
    lines = text.splitlines(keepends=True)
    table_start = _table_start(lines)
    rendered = "true" if active else "false"
    if table_start is None:
        separator = "" if not text or text.endswith(("\n", "\r")) else newline
        entries = [
            f"{name} = {rendered if name == key else 'false'}{newline}"
            for name in GOVERNANCE_SURFACE_KEYS
        ]
        return (
            text
            + separator
            + f"{newline}[governance_surfaces]{newline}"
            + "".join(entries)
        )

    table_end = _table_end(lines, table_start)
    found: set[str] = set()
    for index in range(table_start + 1, table_end):
        for name in GOVERNANCE_SURFACE_KEYS:
            pattern = re.compile(
                rf"^(\s*{re.escape(name)}\s*=\s*)(true|false)(\s*(?:#.*)?)(\r?\n)?$"
            )
            match = pattern.match(lines[index])
            if match is None:
                continue
            found.add(name)
            if name == key:
                ending = match.group(4) or ""
                lines[index] = (
                    f"{match.group(1)}{rendered}{match.group(3)}{ending}"
                )
            break
    missing = [
        f"{name} = {rendered if name == key else 'false'}{newline}"
        for name in GOVERNANCE_SURFACE_KEYS
        if name not in found
    ]
    lines[table_end:table_end] = missing
    return "".join(lines)


def _table_start(lines: list[str]) -> int | None:
    """Locate the optional surface table."""
    for index, line in enumerate(lines):
        if _TABLE_HEADER.match(line.rstrip("\r\n")):
            return index
    return None


def _table_end(lines: list[str], table_start: int) -> int:
    """Locate the first table after the surface table."""
    for index in range(table_start + 1, len(lines)):
        if _ANY_TABLE_HEADER.match(lines[index].rstrip("\r\n")):
            return index
    return len(lines)


def _matching_carriers(root: Path, surface_id: str) -> list[str]:
    """Return bounded retained carrier evidence for one inactive surface."""
    tokens = {
        "evergreen-specification": ("specification",),
        "test-plan": ("test-plan",),
        "evaluation-plan": ("eval-plan", "evaluation-plan"),
        "implementation-plan": ("implementation-plan",),
        "project-overview": ("overview", "project-health"),
        "architecture-view": ("architecture",),
    }[surface_id]
    matches: list[str] = []
    for path in sorted((root / ".carmadio").rglob("*")):
        if (
            not path.is_file()
            or ".carmadio_runtime" in path.parts
            or "000_CARMADIO_METHODOLOGY" in path.parts
        ):
            continue
        lowered = path.name.lower()
        if any(token in lowered for token in tokens):
            matches.append(path.relative_to(root).as_posix())
            if len(matches) == 3:
                break
    return matches


def _settings_error(path: Path, message: str) -> DsetCommandError:
    """Build a stable configuration diagnostic."""
    return DsetCommandError("CARMADIO-E173", path, message)

"""Provide DSET dependencies behavior."""

from __future__ import annotations

import re
from datetime import date
from pathlib import Path
from typing import Any

from .diagnostics import Diagnostic
from .layout import discover_layout
from .structured_data import StructuredDataError, load

# PACKAGE_BLOCK defines package block; this module owns the default.
PACKAGE_BLOCK = re.compile(r"(?ms)^\[\[package\]\]\n(.*?)(?=^\[\[package\]\]|\Z)")
# NAME defines name; this module owns the default.
NAME = re.compile(r'^name = "([^"]+)"$', re.MULTILINE)
# VERSION defines version; this module owns the default.
VERSION = re.compile(r'^version = "([^"]+)"$', re.MULTILINE)
# REGISTRY defines registry; this module owns the default.
REGISTRY = re.compile(r'^source = \{ registry = "([^"]+)" \}$', re.MULTILINE)
# SPDX defines spdx; this module owns the default.
SPDX = re.compile(r"^[A-Za-z0-9][A-Za-z0-9.+-]*$")


def dependency_policy_path(root: Path) -> Path:
    """Handle policy path using the declared repository contract."""
    layout = discover_layout(root.resolve())
    owner = layout.layer_root("implementation") if layout.layered else layout.carmadio_root
    local = layout._numbered_file(owner, "dependency-policy.toml")
    if local.is_file():
        return local
    if _repository_role(layout.manifest_path) == "framework-source-and-adopter":
        return layout._numbered_file(
            layout.framework_layer_root("implementation"),
            "dependency-policy.toml",
        )
    return local


def validate_dependency_policy(
    root: Path,
    *,
    policy_path: Path | None = None,
    today: date | None = None,
) -> list[Diagnostic]:
    """Validate dependency policy using the declared repository contract."""
    root = root.resolve()
    path = policy_path or dependency_policy_path(root)
    if not path.is_file():
        return []
    current_date = today or date.today()
    try:
        data = load(path)
    except (OSError, UnicodeError, StructuredDataError) as error:
        return [_diag(path, f"dependency policy cannot be parsed: {error}")]
    if not isinstance(data, dict):
        return [_diag(path, "dependency policy must be a mapping")]
    required = {
        "schema_version",
        "policy_id",
        "version",
        "authority",
        "exception_authority",
        "ecosystems",
        "allow",
        "deny",
        "exceptions",
    }
    diagnostics: list[Diagnostic] = []
    if set(data) != required or data.get("schema_version") != "1.0":
        return [_diag(path, "dependency policy envelope is invalid")]
    for field in ("policy_id", "version", "authority", "exception_authority"):
        if not isinstance(data.get(field), str) or not str(data[field]).strip():
            diagnostics.append(_diag(path, f"dependency policy {field} is required"))
    ecosystems = _ecosystems(root, path, data.get("ecosystems"), diagnostics)
    allowed = _records(path, data.get("allow"), "allow", diagnostics)
    denied = _records(path, data.get("deny"), "deny", diagnostics, sparse=True)
    exceptions = _exceptions(
        path,
        data.get("exceptions"),
        str(data.get("exception_authority", "")),
        current_date,
        diagnostics,
    )
    _unique_records(path, allowed, "allow", diagnostics)
    _unique_records(path, denied, "deny", diagnostics)
    _unique_records(path, exceptions, "exception", diagnostics)
    for ecosystem, config in ecosystems.items():
        if ecosystem != "python-uv":
            diagnostics.append(_diag(path, f"unsupported ecosystem: {ecosystem}"))
            continue
        locked = _uv_packages(root / config["lockfile"], diagnostics)
        local_name = _project_name(root / config["manifest"])
        locked = {key: value for key, value in locked.items() if key != local_name}
        policy_for_ecosystem = {
            (item["name"], item["version"]): item
            for item in allowed
            if item["ecosystem"] == ecosystem
        }
        active_exceptions = {
            (item["name"], item["version"]): item
            for item in exceptions
            if item["ecosystem"] == ecosystem and item["active"]
        }
        denied_names = {
            (item["name"], item.get("version"))
            for item in denied
            if item["ecosystem"] == ecosystem
        }
        for name, locked_item in locked.items():
            key = (name, locked_item["version"])
            exception = active_exceptions.get(key)
            if (
                (name, None) in denied_names or key in denied_names
            ) and exception is None:
                diagnostics.append(_diag(path, f"denied dependency is locked: {name}"))
                continue
            record = policy_for_ecosystem.get(key) or exception
            if record is None:
                diagnostics.append(
                    _diag(
                        path,
                        f"locked dependency is not allowed exactly: {name}=={key[1]}",
                    )
                )
                continue
            if record["registry"] != config["registry"]:
                diagnostics.append(
                    _diag(
                        path,
                        f"dependency violates ecosystem registry: {name}=={key[1]}",
                    )
                )
            if record["registry"] != locked_item["registry"]:
                diagnostics.append(
                    _diag(path, f"dependency registry drift: {name}=={key[1]}")
                )
        locked_keys = {(name, item["version"]) for name, item in locked.items()}
        for key in policy_for_ecosystem:
            if key not in locked_keys:
                diagnostics.append(
                    _diag(
                        path,
                        "allowed dependency is absent from lockfile: "
                        f"{key[0]}=={key[1]}",
                    )
                )
    return sorted(set(diagnostics))


def dependency_summary(root: Path) -> dict[str, Any]:
    """Handle summary using the declared repository contract."""
    path = dependency_policy_path(root)
    diagnostics = validate_dependency_policy(root, policy_path=path)
    data = load(path) if path.is_file() else {}
    return {
        "policy": path.relative_to(root.resolve()).as_posix(),
        "status": "pass" if not diagnostics else "fail",
        "allowed": len(data.get("allow", [])) if isinstance(data, dict) else 0,
        "denied": len(data.get("deny", [])) if isinstance(data, dict) else 0,
        "exceptions": len(data.get("exceptions", [])) if isinstance(data, dict) else 0,
        "diagnostics": [item.message for item in diagnostics],
    }


def _ecosystems(
    root: Path,
    path: Path,
    value: object,
    diagnostics: list[Diagnostic],
) -> dict[str, dict[str, str]]:
    """Handle ecosystems using the declared repository contract."""
    if not isinstance(value, list) or not value:
        diagnostics.append(_diag(path, "ecosystems must be a non-empty list"))
        return {}
    result: dict[str, dict[str, str]] = {}
    for item in value:
        fields = {"id", "manifest", "lockfile", "registry"}
        if not isinstance(item, dict) or set(item) != fields:
            diagnostics.append(_diag(path, "ecosystem entry is invalid"))
            continue
        if not all(isinstance(item[field], str) and item[field] for field in fields):
            diagnostics.append(_diag(path, "ecosystem values must be non-empty"))
            continue
        identifier = str(item["id"])
        if identifier in result:
            diagnostics.append(_diag(path, f"duplicate ecosystem: {identifier}"))
            continue
        for field in ("manifest", "lockfile"):
            target = root / str(item[field])
            if not target.is_file():
                diagnostics.append(
                    _diag(path, f"dependency {field} is missing: {item[field]}")
                )
        result[identifier] = {field: str(item[field]) for field in fields}
    return result


def _records(
    path: Path,
    value: object,
    label: str,
    diagnostics: list[Diagnostic],
    *,
    sparse: bool = False,
) -> list[dict[str, str]]:
    """Handle records using the declared repository contract."""
    if not isinstance(value, list):
        diagnostics.append(_diag(path, f"{label} must be a list"))
        return []
    records: list[dict[str, str]] = []
    full = {
        "ecosystem",
        "name",
        "version",
        "registry",
        "license",
        "provenance",
        "rationale",
    }
    sparse_fields = {"ecosystem", "name", "version", "rationale"}
    for item in value:
        if not isinstance(item, dict) or (
            set(item) != full
            and not (
                sparse
                and set(item) in ({"ecosystem", "name", "rationale"}, sparse_fields)
            )
        ):
            diagnostics.append(_diag(path, f"{label} dependency entry is invalid"))
            continue
        if not all(isinstance(raw, str) and raw.strip() for raw in item.values()):
            diagnostics.append(
                _diag(path, f"{label} dependency values must be non-empty")
            )
            continue
        if not sparse:
            if not SPDX.fullmatch(str(item["license"])):
                diagnostics.append(
                    _diag(path, f"{label} dependency license must be SPDX")
                )
            if not str(item["provenance"]).startswith("https://"):
                diagnostics.append(
                    _diag(path, f"{label} dependency provenance must use HTTPS")
                )
        records.append({str(key): str(raw) for key, raw in item.items()})
    return records


def _exceptions(
    path: Path,
    value: object,
    authority: str,
    current_date: date,
    diagnostics: list[Diagnostic],
) -> list[dict[str, Any]]:
    """Handle exceptions using the declared repository contract."""
    if not isinstance(value, list):
        diagnostics.append(_diag(path, "exceptions must be a list"))
        return []
    records: list[dict[str, Any]] = []
    required = {
        "id",
        "ecosystem",
        "name",
        "version",
        "registry",
        "license",
        "provenance",
        "authority",
        "expires_on",
        "rationale",
    }
    for item in value:
        if not isinstance(item, dict) or set(item) != required:
            diagnostics.append(_diag(path, "dependency exception entry is invalid"))
            continue
        if not all(isinstance(raw, str) and raw.strip() for raw in item.values()):
            diagnostics.append(
                _diag(path, "dependency exception values must be non-empty")
            )
            continue
        try:
            expiry = date.fromisoformat(str(item["expires_on"]))
        except ValueError:
            diagnostics.append(_diag(path, f"invalid exception expiry: {item['id']}"))
            continue
        active = expiry >= current_date
        if not active:
            diagnostics.append(
                _diag(path, f"dependency exception expired: {item['id']}")
            )
        if item["authority"] != authority:
            diagnostics.append(
                _diag(path, f"dependency exception authority mismatch: {item['id']}")
            )
        if not SPDX.fullmatch(str(item["license"])):
            diagnostics.append(
                _diag(path, f"dependency exception license must be SPDX: {item['id']}")
            )
        if not str(item["provenance"]).startswith("https://"):
            diagnostics.append(
                _diag(
                    path,
                    f"dependency exception provenance must use HTTPS: {item['id']}",
                )
            )
        record = {str(key): raw for key, raw in item.items()}
        record["active"] = active
        records.append(record)
    return records


def _unique_records(
    path: Path,
    records: list[dict[str, Any]],
    label: str,
    diagnostics: list[Diagnostic],
) -> None:
    """Handle records using the declared repository contract."""
    keys = [
        (item.get("ecosystem"), item.get("name"), item.get("version"))
        for item in records
    ]
    if len(keys) != len(set(keys)):
        diagnostics.append(_diag(path, f"duplicate {label} dependency entry"))


def _uv_packages(
    path: Path, diagnostics: list[Diagnostic]
) -> dict[str, dict[str, str]]:
    """Handle packages using the declared repository contract."""
    if not path.is_file():
        return {}
    text = path.read_text(encoding="utf-8")
    packages: dict[str, dict[str, str]] = {}
    for match in PACKAGE_BLOCK.finditer(text):
        block = match.group(1)
        name_match = NAME.search(block)
        version_match = VERSION.search(block)
        registry_match = REGISTRY.search(block)
        if name_match is None or version_match is None:
            diagnostics.append(_diag(path, "uv.lock package lacks name or version"))
            continue
        name = name_match.group(1)
        packages[name] = {
            "version": version_match.group(1),
            "registry": registry_match.group(1) if registry_match else "local",
        }
    return packages


def _project_name(path: Path) -> str:
    if not path.is_file():
        return ""
    text = path.read_text(encoding="utf-8")
    project = re.search(r'(?ms)^\[project\]\n.*?^name = "([^"]+)"$', text)
    return project.group(1) if project else ""


def _repository_role(manifest_path: Path) -> str | None:
    """Handle role using the declared repository contract."""
    try:
        manifest = load(manifest_path)
    except (OSError, UnicodeError, StructuredDataError):
        return None
    if not isinstance(manifest, dict):
        return None
    project = manifest.get("project")
    if not isinstance(project, dict):
        return None
    role = project.get("repository_role")
    return role if isinstance(role, str) else None


def _diag(path: Path, message: str) -> Diagnostic:
    return Diagnostic("CARMADIO-E163", path, message)

"""Provide DSET enforcement profiles behavior."""

from __future__ import annotations

import fnmatch
import json
import re
import subprocess
from datetime import date
from pathlib import Path, PurePosixPath
from typing import Any

from .diagnostics import Diagnostic
from .layout import discover_layout
from .structured_data import StructuredDataError, load

# PROFILE_SCHEMA_VERSION defines profile schema version; this module owns the default.
PROFILE_SCHEMA_VERSION = "1.0"
# GATE_IDS defines gate ids; this module owns the default.
GATE_IDS = (
    "conformance",
    "purity",
    "spec_sync",
    "typing_contracts",
    "lint_static_analysis",
    "secret_hygiene",
)
# PROFILE_STATUSES defines profile statuses; this module owns the default.
PROFILE_STATUSES = frozenset({"candidate", "active", "custom"})
# PROFILE_ROLES defines profile roles; this module owns the default.
PROFILE_ROLES = frozenset({"reference", "applied"})
# REVISION_POLICIES defines revision policies; this module owns the default.
REVISION_POLICIES = frozenset({"exact", "descendant"})
# GATE_STATUSES defines gate statuses; this module owns the default.
GATE_STATUSES = frozenset({"enforced", "ratcheted", "blocked", "not-applicable"})
# _ID validates id; this module owns the accepted syntax.
_ID = re.compile(r"^[a-z][a-z0-9-]*$")
# _SHA validates sha; this module owns the accepted syntax.
_SHA = re.compile(r"^[0-9a-f]{40}$")


def resolve_profile_path(root: Path, profile_id: str) -> Path:
    """Resolve an applied profile, with references limited to framework source."""

    layout = discover_layout(root.resolve())
    local = layout.structured_file(
        layout.layer_root("implementation") / "profiles", f"{profile_id}.toml"
    )
    if local.is_file():
        return local
    if _repository_role(layout.manifest_path) == "framework-source-and-adopter":
        try:
            return layout.find_template(
                Path("enforcement-profiles") / f"{profile_id}.toml"
            )
        except FileNotFoundError:
            pass
    raise FileNotFoundError(
        f"applied enforcement profile is missing: {profile_id}; "
        "framework references are not project-owned instances"
    )


def validate_profile_file(path: Path) -> tuple[dict[str, Any], list[Diagnostic]]:
    """Validate profile file using the declared repository contract."""
    try:
        data = load(path)
    except (OSError, UnicodeError, StructuredDataError) as error:
        return {}, [_diag(path, f"profile cannot be loaded: {error}")]
    if not isinstance(data, dict):
        return {}, [_diag(path, "profile must be a mapping")]
    return data, validate_profile_data(path, data)


def validate_profile_data(path: Path, data: dict[str, Any]) -> list[Diagnostic]:
    """Validate profile data using the declared repository contract."""
    diagnostics: list[Diagnostic] = []
    profile_id = data.get("id")
    status = data.get("status")
    profile_role = data.get("profile_role")
    if data.get("schema_version") != PROFILE_SCHEMA_VERSION:
        diagnostics.append(_diag(path, "schema_version must be 1.0"))
    if not isinstance(profile_id, str) or _ID.fullmatch(profile_id) is None:
        diagnostics.append(_diag(path, "profile id must be kebab-case"))
    if status not in PROFILE_STATUSES:
        diagnostics.append(_diag(path, "profile status is invalid"))
    if profile_role not in PROFILE_ROLES:
        diagnostics.append(_diag(path, "profile_role is invalid"))
    derived_from = data.get("derived_from")
    if profile_role == "applied" and not _nonempty(derived_from):
        diagnostics.append(_diag(path, "applied profile requires derived_from"))
    if profile_role == "reference" and derived_from is not None:
        diagnostics.append(_diag(path, "reference profile cannot set derived_from"))
    if data.get("target_revision_policy") not in REVISION_POLICIES:
        diagnostics.append(_diag(path, "target_revision_policy is invalid"))
    for field in ("version", "language_family"):
        if not _nonempty(data.get(field)):
            diagnostics.append(_diag(path, f"{field} must be non-empty"))

    evidence = _mapping(data.get("evidence"))
    revision = evidence.get("revision")
    upstream = evidence.get("upstream_revision")
    if not _https(evidence.get("repository")):
        diagnostics.append(_diag(path, "evidence repository must be HTTPS"))
    if not isinstance(revision, str) or _SHA.fullmatch(revision) is None:
        diagnostics.append(_diag(path, "evidence revision must be a full SHA"))
    if upstream is not None and (
        not isinstance(upstream, str) or _SHA.fullmatch(upstream) is None
    ):
        diagnostics.append(_diag(path, "upstream_revision must be a full SHA"))
    if not _nonempty(evidence.get("license")):
        diagnostics.append(_diag(path, "evidence license must be non-empty"))
    try:
        date.fromisoformat(str(evidence.get("observed_on")))
    except ValueError:
        diagnostics.append(_diag(path, "observed_on must be an ISO date"))

    toolchain = _mapping(data.get("toolchain"))
    scripts = _string_mapping(toolchain.get("scripts"))
    if not scripts:
        diagnostics.append(_diag(path, "toolchain scripts must be a mapping"))
    for field in ("runtime", "runtime_range", "package_manager", "lockfile"):
        if not _nonempty(toolchain.get(field)):
            diagnostics.append(_diag(path, f"toolchain {field} is missing"))

    scope = _mapping(data.get("scope"))
    for field in (
        "source_roots",
        "test_roots",
        "required_files",
        "generated_outputs",
        "exclusions",
    ):
        values = _string_list(scope.get(field))
        if values is None or not values:
            diagnostics.append(_diag(path, f"scope {field} must be non-empty"))
            continue
        for value in values:
            if not _safe_relative(value):
                diagnostics.append(_diag(path, f"unsafe profile path: {value}"))

    counts = _int_mapping(_mapping(data.get("observed")).get("file_counts"))
    for field in ("source_typescript", "test_typescript", "lint_files"):
        if field not in counts:
            diagnostics.append(_diag(path, f"observed file count is missing: {field}"))

    baseline = _mapping(data.get("warning_baseline"))
    rules = _int_mapping(baseline.get("rules"))
    warning_count = baseline.get("warning_count")
    if baseline.get("revision") != revision:
        diagnostics.append(_diag(path, "warning baseline revision must match evidence"))
    if baseline.get("error_count") != 0:
        diagnostics.append(_diag(path, "hard errors cannot enter the warning baseline"))
    if not isinstance(warning_count, int) or warning_count < 0:
        diagnostics.append(_diag(path, "warning_count must be non-negative"))
    elif warning_count != sum(rules.values()):
        diagnostics.append(_diag(path, "warning_count must equal per-rule counts"))
    if baseline.get("policy") != "shrink-only":
        diagnostics.append(_diag(path, "warning baseline policy must be shrink-only"))

    sequence = _string_list(data.get("canonical_sequence"))
    if sequence is None or not sequence or len(sequence) != len(set(sequence)):
        diagnostics.append(
            _diag(path, "canonical_sequence must be unique and non-empty")
        )
        sequence = []
    gates = data.get("gates")
    seen: set[str] = set()
    blocked = False
    if not isinstance(gates, list):
        diagnostics.append(_diag(path, "gates must be a list"))
    else:
        for item in gates:
            if not isinstance(item, dict):
                diagnostics.append(_diag(path, "every gate must be a mapping"))
                continue
            gate_id = item.get("id")
            gate_status = item.get("status")
            if not isinstance(gate_id, str) or gate_id not in GATE_IDS:
                diagnostics.append(_diag(path, f"unknown gate id: {gate_id}"))
                continue
            if gate_id in seen:
                diagnostics.append(_diag(path, f"duplicate gate: {gate_id}"))
            seen.add(gate_id)
            if gate_status not in GATE_STATUSES:
                diagnostics.append(_diag(path, f"invalid gate status: {gate_id}"))
            commands = _string_list(item.get("commands"))
            if commands is None:
                diagnostics.append(_diag(path, f"gate commands are invalid: {gate_id}"))
                commands = []
            for command in commands:
                if command not in sequence:
                    diagnostics.append(
                        _diag(
                            path,
                            f"gate command is outside canonical sequence: {command}",
                        )
                    )
            if gate_status in {"enforced", "ratcheted"} and not commands:
                diagnostics.append(
                    _diag(path, f"enforced gate has no command: {gate_id}")
                )
            if gate_status in {"blocked", "not-applicable"} and not _nonempty(
                item.get("reason")
            ):
                diagnostics.append(_diag(path, f"gate reason is missing: {gate_id}"))
            if gate_status == "blocked":
                blocked = True
    if seen != set(GATE_IDS):
        missing = ", ".join(sorted(set(GATE_IDS) - seen))
        diagnostics.append(_diag(path, f"profile must define all six gates: {missing}"))

    blockers = _string_list(data.get("known_blockers"))
    if blockers is None:
        diagnostics.append(_diag(path, "known_blockers must be a list"))
        blockers = []
    if status == "active" and (blockers or blocked):
        diagnostics.append(_diag(path, "active profile cannot retain blockers"))
    promotion = _mapping(data.get("promotion"))
    if not _string_list(promotion.get("requires")):
        diagnostics.append(_diag(path, "promotion requirements must be non-empty"))
    return diagnostics


def inspect_target(
    profile_path: Path,
    profile: dict[str, Any],
    target: Path,
) -> dict[str, Any]:
    """Inspect pinned target structure without executing target-owned commands."""

    target = target.resolve()
    diagnostics = validate_profile_data(profile_path, profile)
    revision = _git(target, "rev-parse", "HEAD")
    expected_revision = _mapping(profile.get("evidence")).get("revision")
    revision_policy = profile.get("target_revision_policy")
    if revision_policy == "exact" and revision != expected_revision:
        diagnostics.append(
            _diag(target, f"target revision drift: {revision or 'unavailable'}")
        )
    elif revision_policy == "descendant" and (
        not isinstance(expected_revision, str)
        or not _git_is_ancestor(target, expected_revision)
    ):
        diagnostics.append(
            _diag(target, "target revision is not descended from profile evidence")
        )

    scope = _mapping(profile.get("scope"))
    required_files = _string_list(scope.get("required_files")) or []
    for relative in required_files:
        if not (target / relative).is_file():
            diagnostics.append(
                _diag(target / relative, "required profile file is missing")
            )

    package_path = target / "package.json"
    try:
        package = json.loads(package_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        diagnostics.append(_diag(package_path, f"package.json cannot be read: {error}"))
        package = {}
    actual_scripts = package.get("scripts", {}) if isinstance(package, dict) else {}
    expected_scripts = _string_mapping(
        _mapping(profile.get("toolchain")).get("scripts")
    )
    for name, command in expected_scripts.items():
        if not isinstance(actual_scripts, dict) or actual_scripts.get(name) != command:
            diagnostics.append(_diag(package_path, f"target script drift: {name}"))

    tracked = _git_files(target)
    source_roots = _string_list(scope.get("source_roots")) or []
    test_roots = _string_list(scope.get("test_roots")) or []
    counts = {
        "source_typescript": _count_typescript(tracked, source_roots),
        "test_typescript": _count_typescript(tracked, test_roots),
    }
    counts["lint_files"] = counts["source_typescript"] + counts["test_typescript"]
    expected_counts = _int_mapping(_mapping(profile.get("observed")).get("file_counts"))
    for name, expected in expected_counts.items():
        if counts.get(name) != expected:
            diagnostics.append(
                _diag(
                    target, f"target file population drift: {name}={counts.get(name)}"
                )
            )

    blockers = _string_list(profile.get("known_blockers")) or []
    return {
        "schema_version": PROFILE_SCHEMA_VERSION,
        "profile": profile.get("id"),
        "profile_role": profile.get("profile_role"),
        "profile_status": profile.get("status"),
        "target_revision_policy": revision_policy,
        "profile_path": profile_path.as_posix(),
        "target": target.as_posix(),
        "target_revision": revision,
        "file_counts": counts,
        "known_blockers": blockers,
        "promotion_eligible": not diagnostics and not blockers,
        "diagnostics": [item.render(target) for item in sorted(set(diagnostics))],
        "commands_executed": False,
    }


def _count_typescript(paths: list[str], roots: list[str]) -> int:
    """Handle typescript using the declared repository contract."""
    return sum(
        1
        for path in paths
        if path.endswith((".ts", ".tsx"))
        and any(
            path == root or path.startswith(root.rstrip("/") + "/") for root in roots
        )
    )


def _git(root: Path, *args: str) -> str | None:
    result = subprocess.run(
        ["git", *args], cwd=root, check=False, capture_output=True, text=True
    )
    return result.stdout.strip() if result.returncode == 0 else None


def _git_is_ancestor(root: Path, ancestor: str) -> bool:
    """Handle is ancestor using the declared repository contract."""
    result = subprocess.run(
        ["git", "merge-base", "--is-ancestor", ancestor, "HEAD"],
        cwd=root,
        check=False,
        capture_output=True,
        text=True,
    )
    return result.returncode == 0


def _repository_role(manifest_path: Path) -> str | None:
    """Handle role using the declared repository contract."""
    try:
        manifest = load(manifest_path)
    except (OSError, UnicodeError, StructuredDataError):
        return None
    if not isinstance(manifest, dict):
        return None
    project = manifest.get("project")
    if not isinstance(project, dict):
        return None
    role = project.get("repository_role")
    return role if isinstance(role, str) else None


def _git_files(root: Path) -> list[str]:
    """Handle files using the declared repository contract."""
    result = subprocess.run(
        ["git", "ls-files", "-z"], cwd=root, check=False, capture_output=True
    )
    if result.returncode:
        return []
    return [item.decode("utf-8") for item in result.stdout.split(b"\0") if item]


def _safe_relative(value: str) -> bool:
    """Handle relative using the declared repository contract."""
    path = PurePosixPath(value)
    return (
        bool(value)
        and "\\" not in value
        and not path.is_absolute()
        and ".." not in path.parts
        and not fnmatch.fnmatchcase(value, "*/./*")
    )


def _mapping(value: object) -> dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _string_mapping(value: object) -> dict[str, str]:
    """Handle mapping using the declared repository contract."""
    if not isinstance(value, dict):
        return {}
    return {
        str(key): item
        for key, item in value.items()
        if isinstance(key, str) and isinstance(item, str) and item.strip()
    }


def _int_mapping(value: object) -> dict[str, int]:
    """Handle mapping using the declared repository contract."""
    if not isinstance(value, dict):
        return {}
    return {
        str(key): item
        for key, item in value.items()
        if isinstance(key, str) and isinstance(item, int) and item >= 0
    }


def _string_list(value: object) -> list[str] | None:
    if not isinstance(value, list) or not all(
        isinstance(item, str) and item.strip() for item in value
    ):
        return None
    return list(value)


def _nonempty(value: object) -> bool:
    return isinstance(value, str) and bool(value.strip())


def _https(value: object) -> bool:
    return isinstance(value, str) and value.startswith("https://")


def _diag(path: Path, message: str) -> Diagnostic:
    return Diagnostic("CARMADIO-E167", path, message)

"""Provide DSET evidence behavior."""

from __future__ import annotations

import re
from collections.abc import Iterable
from datetime import datetime
from pathlib import Path
from typing import Any

from .diagnostics import Diagnostic
from .frontmatter import FrontmatterError
from .frontmatter import load as load_frontmatter
from .identity import has_logical_part

# ID_PATTERN validates id pattern; this module owns the accepted syntax.
ID_PATTERN = re.compile(r"^[A-Z0-9]+(?:-[A-Z0-9]+)+$")
# SESSION_PATTERN validates session pattern; this module owns the accepted syntax.
SESSION_PATTERN = re.compile(r"^[a-z][a-z0-9_-]*:[A-Za-z0-9._:-]+$")
# EVIDENCE_SUBTYPES defines evidence subtypes; this module owns the default.
EVIDENCE_SUBTYPES = frozenset(
    {"test_result", "evaluation_result", "review_report", "run_record"}
)
# POLARITIES defines polarities; this module owns the default.
POLARITIES = frozenset({"supports", "contradicts", "mixed", "inconclusive"})
# CURRENTNESS defines currentness; this module owns the default.
CURRENTNESS = frozenset({"current", "stale", "superseded"})
# REQUIRED_FIELDS defines required fields; this module owns the default.
REQUIRED_FIELDS = frozenset(
    {
        "schema_version",
        "artifact_type",
        "artifact_subtype",
        "artifact_id",
        "priority",
        "llm_session_ids",
        "subject",
        "producer",
        "method",
        "context",
        "evidence_location",
        "polarity",
        "currentness",
        "reopen_when",
        "relations",
    }
)
# OPTIONAL_FIELDS defines optional fields; this module owns the default.
OPTIONAL_FIELDS = frozenset(
    {
        "observed_at",
        "validity_window",
        "independent_producer",
        "rival_explanations",
        "limitations",
        "rationale",
    }
)


def validate_evidence_records(
    root: Path,
    paths: Iterable[Path],
    legacy_paths: frozenset[str],
    *,
    allow_unversioned_legacy: bool = False,
) -> list[Diagnostic]:
    """Validate native Evidence Records while preserving a finite legacy set."""
    root = root.resolve()
    diagnostics: list[Diagnostic] = []
    for candidate in paths:
        path = candidate.resolve()
        if path.suffix.lower() != ".md" or has_logical_part(
            path.relative_to(root), {"templates"}
        ):
            continue
        relative = path.relative_to(root).as_posix()
        diagnostics.extend(
            _validate_evidence_candidate(
                path,
                relative in legacy_paths,
                allow_unversioned_legacy,
            )
        )
    return diagnostics


def _validate_evidence_candidate(
    path: Path,
    legacy: bool,
    allow_unversioned_legacy: bool,
) -> list[Diagnostic]:
    """Validate one candidate after repository routing selected it."""
    try:
        parsed = load_frontmatter(path)
    except (OSError, UnicodeError, FrontmatterError) as error:
        return [] if legacy else [_diag(path, str(error))]
    metadata = parsed[0] if parsed is not None else None
    artifact_type = metadata.get("artifact_type") if metadata is not None else None
    if legacy:
        return _legacy_type_diagnostics(path, artifact_type)
    if _allowed_unversioned(metadata, artifact_type, allow_unversioned_legacy):
        return []
    if artifact_type != "evidence_record":
        return []
    if parsed is None or parsed[2] != "toml":
        return [_diag(path, "new Evidence Records require TOML frontmatter")]
    assert metadata is not None
    return _validate_native_record(path, metadata)


def _legacy_type_diagnostics(path: Path, artifact_type: object) -> list[Diagnostic]:
    """Reject a legacy compatibility carrier that declares another type."""
    if artifact_type in {None, "evidence_record"}:
        return []
    return [
        _diag(
            path,
            "legacy evidence compatibility path has a conflicting artifact type",
        )
    ]


def _allowed_unversioned(
    metadata: dict[str, Any] | None,
    artifact_type: object,
    enabled: bool,
) -> bool:
    """Return whether explicit migration compatibility admits this carrier."""
    return bool(
        enabled
        and artifact_type == "evidence_record"
        and metadata is not None
        and "schema_version" not in metadata
    )


def _validate_native_record(path: Path, data: dict[str, Any]) -> list[Diagnostic]:
    """Validate native record using the declared repository contract."""
    diagnostics: list[Diagnostic] = []
    keys = set(data)
    missing = sorted(REQUIRED_FIELDS - keys)
    unknown = sorted(keys - REQUIRED_FIELDS - OPTIONAL_FIELDS)
    if missing:
        diagnostics.append(
            _diag(path, "Evidence Record is missing fields: " + ", ".join(missing))
        )
    if unknown:
        diagnostics.append(
            _diag(path, "Evidence Record has unknown fields: " + ", ".join(unknown))
        )
    if data.get("schema_version") != "1.0":
        diagnostics.append(_diag(path, "Evidence Record schema_version must be 1.0"))
    if data.get("artifact_type") != "evidence_record":
        diagnostics.append(_diag(path, "artifact_type must be evidence_record"))
    if data.get("artifact_subtype") not in EVIDENCE_SUBTYPES:
        diagnostics.append(_diag(path, "Evidence Record subtype is invalid"))
    _required_id(path, data.get("artifact_id"), "artifact_id", diagnostics)
    _nonempty(path, data.get("priority"), "priority", diagnostics)
    _sessions(path, data.get("llm_session_ids"), diagnostics)
    _subject(path, data.get("subject"), diagnostics)
    _producer(path, data.get("producer"), diagnostics)
    _method(path, data.get("method"), diagnostics)
    _nonempty_list(path, data.get("context"), "context", diagnostics)
    _nonempty(path, data.get("evidence_location"), "evidence_location", diagnostics)
    if data.get("polarity") not in POLARITIES:
        diagnostics.append(_diag(path, "Evidence Record polarity is invalid"))
    if data.get("currentness") not in CURRENTNESS:
        diagnostics.append(_diag(path, "Evidence Record currentness is invalid"))
    _nonempty(path, data.get("reopen_when"), "reopen_when", diagnostics)
    _observation_time(path, data, diagnostics)
    _relations(path, data.get("relations"), diagnostics)
    _optional_extensions(path, data, diagnostics)
    return diagnostics


def _subject(path: Path, value: object, diagnostics: list[Diagnostic]) -> None:
    """Handle subject using the declared repository contract."""
    if not isinstance(value, dict) or set(value) != {
        "id",
        "revision",
        "intended_use",
    }:
        diagnostics.append(
            _diag(path, "subject requires exactly id, revision, and intended_use")
        )
        return
    _required_id(path, value.get("id"), "subject.id", diagnostics)
    revision = value.get("revision")
    _nonempty(path, revision, "subject.revision", diagnostics)
    if isinstance(revision, str) and revision.strip().lower() == "pending":
        diagnostics.append(_diag(path, "subject.revision cannot be pending"))
    _nonempty(path, value.get("intended_use"), "subject.intended_use", diagnostics)


def _producer(path: Path, value: object, diagnostics: list[Diagnostic]) -> None:
    """Handle producer using the declared repository contract."""
    if not isinstance(value, dict) or set(value) != {"identity", "performed_work"}:
        diagnostics.append(
            _diag(path, "producer requires exactly identity and performed_work")
        )
        return
    _nonempty(path, value.get("identity"), "producer.identity", diagnostics)
    _nonempty(path, value.get("performed_work"), "producer.performed_work", diagnostics)


def _method(path: Path, value: object, diagnostics: list[Diagnostic]) -> None:
    if not isinstance(value, dict) or set(value) != {"description", "setup"}:
        diagnostics.append(_diag(path, "method requires exactly description and setup"))
        return
    _nonempty(path, value.get("description"), "method.description", diagnostics)
    _nonempty(path, value.get("setup"), "method.setup", diagnostics)


def _observation_time(
    path: Path, data: dict[str, Any], diagnostics: list[Diagnostic]
) -> None:
    """Handle time using the declared repository contract."""
    has_observed = "observed_at" in data
    has_window = "validity_window" in data
    if has_observed == has_window:
        diagnostics.append(
            _diag(
                path,
                "Evidence Record requires exactly one observed_at or validity_window",
            )
        )
        return
    if has_observed:
        _timestamp(path, data.get("observed_at"), "observed_at", diagnostics)
        return
    window = data.get("validity_window")
    if not isinstance(window, dict) or set(window) != {"from", "through"}:
        diagnostics.append(
            _diag(path, "validity_window requires exactly from and through")
        )
        return
    _timestamp(path, window.get("from"), "validity_window.from", diagnostics)
    _timestamp(path, window.get("through"), "validity_window.through", diagnostics)


def _relations(path: Path, value: object, diagnostics: list[Diagnostic]) -> None:
    """Handle relations using the declared repository contract."""
    if not isinstance(value, list) or not value:
        diagnostics.append(_diag(path, "Evidence Record requires relations"))
        return
    evidence_targets: list[str] = []
    for relation in value:
        if not isinstance(relation, dict):
            diagnostics.append(_diag(path, "every evidence relation must be a table"))
            continue
        if relation.get("type") == "evidence_for":
            target = relation.get("target")
            if isinstance(target, str) and ID_PATTERN.fullmatch(target):
                evidence_targets.append(target)
    if not evidence_targets:
        diagnostics.append(
            _diag(path, "Evidence Record requires a canonical evidence_for relation")
        )


def _optional_extensions(
    path: Path, data: dict[str, Any], diagnostics: list[Diagnostic]
) -> None:
    """Handle extensions using the declared repository contract."""
    if "independent_producer" in data and not isinstance(
        data["independent_producer"], bool
    ):
        diagnostics.append(_diag(path, "independent_producer must be boolean"))
    for field in ("rival_explanations", "limitations"):
        if field in data:
            _nonempty_list(path, data[field], field, diagnostics)
    if "rationale" in data:
        _nonempty(path, data["rationale"], "rationale", diagnostics)


def _sessions(path: Path, value: object, diagnostics: list[Diagnostic]) -> None:
    """Handle sessions using the declared repository contract."""
    if not isinstance(value, list):
        diagnostics.append(_diag(path, "llm_session_ids must be a list"))
        return
    if len(value) != len(set(str(item) for item in value)) or any(
        not isinstance(item, str) or SESSION_PATTERN.fullmatch(item) is None
        for item in value
    ):
        diagnostics.append(_diag(path, "llm_session_ids are invalid or duplicated"))


def _required_id(
    path: Path, value: object, field: str, diagnostics: list[Diagnostic]
) -> None:
    if not isinstance(value, str) or ID_PATTERN.fullmatch(value) is None:
        diagnostics.append(_diag(path, f"{field} must be a canonical ID"))


def _nonempty(
    path: Path, value: object, field: str, diagnostics: list[Diagnostic]
) -> None:
    if not isinstance(value, str) or not value.strip():
        diagnostics.append(_diag(path, f"{field} must be non-empty text"))


def _nonempty_list(
    path: Path, value: object, field: str, diagnostics: list[Diagnostic]
) -> None:
    """Handle list using the declared repository contract."""
    if (
        not isinstance(value, list)
        or not value
        or any(not isinstance(item, str) or not item.strip() for item in value)
    ):
        diagnostics.append(_diag(path, f"{field} must be a non-empty text list"))


def _timestamp(
    path: Path, value: object, field: str, diagnostics: list[Diagnostic]
) -> None:
    """Handle timestamp using the declared repository contract."""
    if not isinstance(value, str):
        diagnostics.append(_diag(path, f"{field} must be an ISO-8601 timestamp"))
        return
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        diagnostics.append(_diag(path, f"{field} must be an ISO-8601 timestamp"))
        return
    if parsed.tzinfo is None:
        diagnostics.append(_diag(path, f"{field} must include a timezone"))


def _diag(path: Path, message: str) -> Diagnostic:
    return Diagnostic("CARMADIO-E168", path, message)

"""Provide DSET external review behavior."""

from __future__ import annotations

import hashlib
import json
import re
import subprocess
from datetime import datetime
from pathlib import Path
from typing import Any

from .frontmatter import FrontmatterError
from .frontmatter import parse as parse_frontmatter
from .frontmatter import render as render_frontmatter
from .identity import find_unique_name
from .layout import discover_layout
from .project_data import project_section
from .settings import load_project_settings
from .structured_data import load

# ID_PATTERN validates id pattern; this module owns the accepted syntax.
ID_PATTERN = re.compile(r"^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)+$")
# FINDING_PATTERN validates finding pattern; this module owns the accepted syntax.
FINDING_PATTERN = re.compile(r"^[A-Z][A-Z0-9]*-REVIEW-FINDING-[0-9]{3,}$")
# SESSION_PATTERN validates session pattern; this module owns the accepted syntax.
SESSION_PATTERN = re.compile(r"^[a-z][a-z0-9_-]*:[A-Za-z0-9._:-]+$")
# SHA_PATTERN validates sha pattern; this module owns the accepted syntax.
SHA_PATTERN = re.compile(r"^[0-9a-f]{40}$")
# DISPOSITIONS defines dispositions; this module owns the default.
DISPOSITIONS = frozenset(
    {
        "reject",
        "defer",
        "route_problem",
        "route_question",
        "route_decision",
        "route_change",
        "route_evergreen",
        "route_proof",
    }
)


def create_review_packet(
    root: Path,
    output: Path,
    *,
    packet_id: str,
    artifacts: list[str],
    criteria: list[str],
    scope: str,
) -> Path:
    """Create review packet using the declared repository contract."""
    root = root.resolve()
    if not ID_PATTERN.fullmatch(packet_id) or "REVIEW-PACKET" not in packet_id:
        raise ValueError("packet_id must be a canonical REVIEW-PACKET ID")
    if not artifacts or len(set(artifacts)) != len(artifacts):
        raise ValueError("packet requires unique reviewed artifacts")
    if not criteria or any(not item.strip() for item in criteria):
        raise ValueError("packet requires non-empty review criteria")
    if not scope.strip():
        raise ValueError("packet requires a bounded scope")
    reviewed = [_file_identity(root, raw) for raw in artifacts]
    registry = project_section(root, "governance_registry")
    raw_rules = registry.get("rules", []) if isinstance(registry, dict) else []
    rules: list[dict[str, str]] = []
    for item in raw_rules:
        if not isinstance(item, dict) or item.get("applicability") != "applicable":
            continue
        rule_path = item.get("document")
        rule_id = item.get("id")
        if not isinstance(rule_path, str) or not isinstance(rule_id, str):
            continue
        identity = _file_identity(root, rule_path)
        rules.append({"id": rule_id, **identity})
    packet = {
        "schema_version": "1.0",
        "artifact_type": "plan",
        "artifact_id": packet_id.replace("REVIEW-PACKET", "PLAN"),
        "packet_id": packet_id,
        "repository": _repository_identity(root),
        "commit": _head(root),
        "scope": scope,
        "criteria": criteria,
        "reviewed_inputs": reviewed,
        "resolved_rules": sorted(rules, key=lambda item: item["id"]),
        "allowed_effects": ["read_only_report"],
    }
    content = _markdown(packet, "External review packet", _packet_body())
    return _write_new(output, content)


def validate_review_report(
    root: Path, packet_path: Path, report_path: Path
) -> dict[str, Any]:
    """Validate review report using the declared repository contract."""
    root = root.resolve()
    packet, _ = _read_markdown(packet_path)
    report, body = _read_markdown(report_path)
    _validate_packet(root, packet)
    settings, issues = load_project_settings(root)
    if issues:
        raise ValueError(issues[0])
    allowed_priorities = {*settings.priority_scale, "unknown"}
    _validate_report(packet, report, body, allowed_priorities)
    return {
        "report_id": report["artifact_id"],
        "packet_id": report["packet_id"],
        "reviewed_commit": report["reviewed_commit"],
        "report_sha256": _sha256(report_path),
        "finding_ids": [item["id"] for item in report["findings"]],
        "implementation_authorized": False,
    }


def reconcile_review(
    root: Path,
    packet_path: Path,
    report_path: Path,
    candidate_path: Path,
) -> dict[str, Any]:
    """Handle review using the declared repository contract."""
    validated = validate_review_report(root, packet_path, report_path)
    candidate = json.loads(candidate_path.read_text(encoding="utf-8"))
    if not isinstance(candidate, dict):
        raise ValueError("review reconciliation must be a JSON object")
    required = {
        "schema_version",
        "report_id",
        "report_sha256",
        "reconciled_at",
        "llm_session_ids",
        "findings",
    }
    if set(candidate) != required or candidate.get("schema_version") != "1.0":
        raise ValueError("review reconciliation envelope is invalid")
    if candidate.get("report_id") != validated["report_id"]:
        raise ValueError("reconciliation report_id does not match the report")
    if candidate.get("report_sha256") != validated["report_sha256"]:
        raise ValueError("reconciliation report digest does not match the report")
    _datetime(str(candidate.get("reconciled_at")), "reconciled_at")
    _sessions(candidate.get("llm_session_ids"))
    raw_findings = candidate.get("findings")
    if not isinstance(raw_findings, list):
        raise ValueError("reconciliation findings must be a list")
    reconciled = [_validate_disposition(item) for item in raw_findings]
    actual_ids = [item["finding_id"] for item in reconciled]
    expected_ids = list(validated["finding_ids"])
    if len(actual_ids) != len(set(actual_ids)):
        raise ValueError("reconciliation finding IDs must be unique")
    if set(actual_ids) != set(expected_ids):
        raise ValueError("every report finding requires exactly one disposition")
    ordered = sorted(
        reconciled, key=lambda item: expected_ids.index(item["finding_id"])
    )
    return {
        "schema_version": "1.0",
        "artifact_type": "evidence_record",
        "artifact_subtype": "review_report",
        "report_id": validated["report_id"],
        "report_sha256": validated["report_sha256"],
        "reconciled_at": candidate["reconciled_at"],
        "llm_session_ids": candidate["llm_session_ids"],
        "findings": ordered,
        "reopen_proof": sorted(
            {proof for item in ordered for proof in item.get("reopen_proof", [])}
        ),
        "implementation_authorized": False,
    }


def write_reconciliation(root: Path, output: Path, result: dict[str, Any]) -> Path:
    """Write reconciliation using the declared repository contract."""
    root = root.resolve()
    target = output.resolve()
    try:
        target.relative_to(root)
    except ValueError as error:
        raise ValueError(
            "reconciliation output must remain inside the repository"
        ) from error
    return _write_new(target, json.dumps(result, indent=2, sort_keys=True) + "\n")


def _validate_packet(root: Path, packet: dict[str, Any]) -> None:
    """Validate packet using the declared repository contract."""
    required = {
        "schema_version",
        "artifact_type",
        "artifact_id",
        "packet_id",
        "repository",
        "commit",
        "scope",
        "criteria",
        "reviewed_inputs",
        "resolved_rules",
        "allowed_effects",
    }
    if set(packet) != required or packet.get("schema_version") != "1.0":
        raise ValueError("review packet envelope is invalid")
    if packet.get("artifact_type") != "plan":
        raise ValueError("review packet must be classified as a plan")
    if packet.get("allowed_effects") != ["read_only_report"]:
        raise ValueError("review packet may authorize only a read-only report")
    if packet.get("repository") != _repository_identity(root):
        raise ValueError("review packet repository does not match the project")
    if not isinstance(packet.get("commit"), str) or not SHA_PATTERN.fullmatch(
        str(packet["commit"])
    ):
        raise ValueError("review packet requires an exact commit")
    reviewed_inputs = packet.get("reviewed_inputs")
    if not isinstance(reviewed_inputs, list) or not reviewed_inputs:
        raise ValueError("review packet requires exact input identities")
    for item in reviewed_inputs:
        if not _valid_identity(item, with_id=False):
            raise ValueError("review packet input identity is invalid")
    resolved_rules = packet.get("resolved_rules")
    if not isinstance(resolved_rules, list) or not resolved_rules:
        raise ValueError("review packet requires resolved governing rules")
    for item in resolved_rules:
        if not _valid_identity(item, with_id=True):
            raise ValueError("review packet rule identity is invalid")


def _validate_report(
    packet: dict[str, Any],
    report: dict[str, Any],
    body: str,
    allowed_priorities: set[str],
) -> None:
    """Validate report using the declared repository contract."""
    required = {
        "schema_version",
        "artifact_type",
        "artifact_subtype",
        "artifact_id",
        "packet_id",
        "priority",
        "reviewer",
        "llm_session_ids",
        "reviewed_commit",
        "reviewed_inputs",
        "method",
        "observed_at",
        "limitations",
        "findings",
    }
    if set(report) != required or report.get("schema_version") != "1.0":
        raise ValueError("review report envelope is invalid")
    if (report.get("artifact_type"), report.get("artifact_subtype")) != (
        "evidence_record",
        "review_report",
    ):
        raise ValueError("review report classification is invalid")
    if report.get("packet_id") != packet.get("packet_id"):
        raise ValueError("review report packet_id does not match")
    if report.get("reviewed_commit") != packet.get("commit"):
        raise ValueError("review report commit does not match the packet")
    if report.get("reviewed_inputs") != packet.get("reviewed_inputs"):
        raise ValueError("review report inputs do not match the packet")
    if report.get("priority") not in allowed_priorities:
        raise ValueError("review report priority is invalid")
    reviewer = report.get("reviewer")
    reviewer_keys = {"identity", "host", "model", "tool_version"}
    if not isinstance(reviewer, dict) or set(reviewer) != reviewer_keys:
        raise ValueError("reviewer identity envelope is invalid")
    if any(
        not isinstance(value, str) or not value.strip() for value in reviewer.values()
    ):
        raise ValueError("reviewer identity values must be non-empty")
    _sessions(report.get("llm_session_ids"))
    if not isinstance(report.get("method"), str) or not report["method"].strip():
        raise ValueError("review report method is required")
    _datetime(str(report.get("observed_at")), "observed_at")
    limitations = report.get("limitations")
    if not isinstance(limitations, list) or not all(
        isinstance(item, str) and item.strip() for item in limitations
    ):
        raise ValueError("review report limitations must be an explicit list")
    findings = report.get("findings")
    if not isinstance(findings, list):
        raise ValueError("review report findings must be a list")
    finding_ids: list[str] = []
    for finding in findings:
        _validate_finding(finding, allowed_priorities)
        assert isinstance(finding, dict)
        finding_ids.append(str(finding["id"]))
    if len(finding_ids) != len(set(finding_ids)):
        raise ValueError("review finding IDs must be unique")
    if not body.strip():
        raise ValueError("review report requires a findings body")


def _validate_finding(finding: object, allowed_priorities: set[str]) -> None:
    """Validate finding using the declared repository contract."""
    fields = {
        "id",
        "priority",
        "evidence",
        "confidence",
        "impact",
        "proposed_disposition",
    }
    if not isinstance(finding, dict) or set(finding) != fields:
        raise ValueError("review finding envelope is invalid")
    identifier = finding.get("id")
    if not isinstance(identifier, str) or not FINDING_PATTERN.fullmatch(identifier):
        raise ValueError("review finding ID is invalid")
    if finding.get("priority") not in allowed_priorities:
        raise ValueError("review finding priority is invalid")
    if finding.get("confidence") not in {"low", "medium", "high"}:
        raise ValueError("review finding confidence is invalid")
    if finding.get("proposed_disposition") not in DISPOSITIONS:
        raise ValueError("review finding proposed disposition is invalid")
    for key in ("evidence", "impact"):
        if not isinstance(finding.get(key), str) or not finding[key].strip():
            raise ValueError(f"review finding {key} is required")


def _validate_disposition(value: object) -> dict[str, Any]:
    """Validate disposition using the declared repository contract."""
    if not isinstance(value, dict):
        raise ValueError("every reconciliation finding must be an object")
    allowed = {
        "finding_id",
        "disposition",
        "rationale",
        "target_id",
        "reopen_proof",
    }
    if not set(value).issubset(allowed):
        raise ValueError("reconciliation finding contains unknown fields")
    finding_id = value.get("finding_id")
    disposition = value.get("disposition")
    rationale = value.get("rationale")
    if not isinstance(finding_id, str) or not FINDING_PATTERN.fullmatch(finding_id):
        raise ValueError("reconciliation finding_id is invalid")
    if disposition not in DISPOSITIONS:
        raise ValueError("reconciliation disposition is invalid")
    if not isinstance(rationale, str) or not rationale.strip():
        raise ValueError("every reconciliation disposition requires rationale")
    routed = str(disposition).startswith("route_")
    target_id = value.get("target_id")
    valid_target = isinstance(target_id, str) and bool(ID_PATTERN.fullmatch(target_id))
    if routed != valid_target:
        raise ValueError("routed findings require one canonical target_id")
    reopen = value.get("reopen_proof", [])
    if not isinstance(reopen, list) or not all(
        isinstance(item, str) and ID_PATTERN.fullmatch(item) for item in reopen
    ):
        raise ValueError("reopen_proof must contain canonical IDs")
    result = {
        "finding_id": finding_id,
        "disposition": disposition,
        "rationale": rationale,
        "reopen_proof": sorted(set(reopen)),
    }
    if routed:
        result["target_id"] = target_id
    return result


def _read_markdown(path: Path) -> tuple[dict[str, Any], str]:
    """Read markdown using the declared repository contract."""
    try:
        parsed = parse_frontmatter(path.read_text(encoding="utf-8"))
    except FrontmatterError as error:
        raise ValueError(
            f"review artifact frontmatter is invalid: {path}: {error}"
        ) from error
    if parsed is None:
        raise ValueError(f"review artifact requires TOML or YAML frontmatter: {path}")
    data, body, _format = parsed
    return data, body


def _file_identity(root: Path, raw: str) -> dict[str, str]:
    candidate = find_unique_name(root, raw)
    return {"carrier": candidate.name, "sha256": _sha256(candidate)}


def _valid_identity(value: object, *, with_id: bool) -> bool:
    """Handle identity using the declared repository contract."""
    if not isinstance(value, dict):
        return False
    fields = {"carrier", "sha256"}
    if with_id:
        fields.add("id")
    if set(value) != fields:
        return False
    carrier = value.get("carrier")
    digest = value.get("sha256")
    identifier = value.get("id")
    return (
        isinstance(carrier, str)
        and bool(carrier)
        and Path(carrier).name == carrier
        and isinstance(digest, str)
        and bool(re.fullmatch(r"[0-9a-f]{64}", digest))
        and (
            not with_id
            or (isinstance(identifier, str) and bool(ID_PATTERN.fullmatch(identifier)))
        )
    )


def _repository_identity(root: Path) -> str:
    """Handle identity using the declared repository contract."""
    manifest = load(discover_layout(root).manifest_path)
    project = manifest.get("project", {}) if isinstance(manifest, dict) else {}
    value = project.get("repository_slug") or project.get("id")
    if not isinstance(value, str) or not value:
        raise ValueError("project manifest requires repository identity")
    return value


def _head(root: Path) -> str:
    """Handle head using the declared repository contract."""
    completed = subprocess.run(
        ["git", "rev-parse", "HEAD"],
        cwd=root,
        check=False,
        capture_output=True,
        text=True,
    )
    value = completed.stdout.strip()
    if completed.returncode or not SHA_PATTERN.fullmatch(value):
        raise ValueError("review packet requires a Git repository with an exact HEAD")
    return value


def _sessions(value: object) -> None:
    """Handle sessions using the declared repository contract."""
    if not isinstance(value, list) or len(value) != len(set(map(str, value))):
        raise ValueError("llm_session_ids must be a unique list")
    if not all(
        isinstance(item, str) and SESSION_PATTERN.fullmatch(item) for item in value
    ):
        raise ValueError("llm_session_ids must use host-prefixed identities")


def _datetime(value: str, field: str) -> None:
    try:
        datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as error:
        raise ValueError(f"{field} must be an ISO 8601 timestamp") from error


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _markdown(metadata: dict[str, Any], title: str, body: str) -> str:
    return render_frontmatter(metadata, f"\n# {title}\n\n{body.rstrip()}\n")


def _packet_body() -> str:
    return (
        "Review only the exact commit, input digests, rules, scope, and criteria "
        "in the envelope. Return a report; do not edit the project or authorize repair."
    )


def _write_new(path: Path, content: str) -> Path:
    """Write new using the declared repository contract."""
    path = path.resolve()
    if path.exists():
        raise FileExistsError(f"refusing existing review artifact: {path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    return path

"""Read and render DSET Markdown property envelopes."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from .toml_codec import TomlCodecError
from .toml_codec import dumps as dump_toml
from .toml_codec import loads as load_toml
from .yaml_properties import YamlPropertiesError
from .yaml_properties import dumps as dump_yaml
from .yaml_properties import loads as load_yaml


class FrontmatterError(ValueError):
    """A Markdown frontmatter envelope is malformed or unsupported."""


def parse(text: str) -> tuple[dict[str, Any], str, str] | None:
    """Return ``(metadata, body, format)`` or ``None`` without frontmatter."""

    lines = text.splitlines(keepends=True)
    if not lines:
        return None
    delimiter = lines[0].strip()
    if delimiter not in {"+++", "---"}:
        return None
    for index, line in enumerate(lines[1:], start=1):
        if line.strip() != delimiter:
            continue
        payload = "".join(lines[1:index])
        if delimiter == "+++":
            try:
                value = load_toml(payload)
            except TomlCodecError as error:
                raise FrontmatterError(str(error)) from error
            format_name = "toml"
        else:
            try:
                value = load_yaml(payload)
            except YamlPropertiesError as error:
                raise FrontmatterError(str(error)) from error
            format_name = "yaml"
        if not isinstance(value, dict):
            raise FrontmatterError("frontmatter root must be a mapping")
        return (
            value,
            "".join(lines[index + 1 :]),
            format_name,
        )
    raise FrontmatterError("frontmatter opening delimiter has no closing delimiter")


def load(path: Path) -> tuple[dict[str, Any], str, str] | None:
    """Read frontmatter from a Markdown path."""

    return parse(path.read_text(encoding="utf-8"))


def metadata(path: Path) -> dict[str, Any] | None:
    """Read only a frontmatter mapping, returning ``None`` when absent."""

    parsed = load(path)
    return parsed[0] if parsed is not None else None


def format_for_path(path: Path, *, default: str = "toml") -> str:
    """Preserve an existing envelope during compatibility-mode regeneration."""

    try:
        parsed = load(path)
    except (OSError, UnicodeError, FrontmatterError):
        return default
    return parsed[2] if parsed is not None else default


def render(metadata: dict[str, Any], body: str, *, format: str = "toml") -> str:
    """Render a complete Markdown envelope in the requested format."""

    if format == "toml":
        return f"+++\n{dump_toml(metadata)}+++\n{body}"
    if format == "yaml":
        payload = dump_yaml(metadata)
        return f"---\n{payload}---\n{body}"
    raise FrontmatterError(f"unsupported frontmatter format: {format}")

"""Provide DSET governance behavior."""

from __future__ import annotations

import difflib
import hashlib
import re
import shutil
from pathlib import Path
from typing import Any, cast

from .diagnostics import Diagnostic
from .errors import DsetCommandError
from .identity import find_unique_name
from .layout import (
    LAYER_DIRECTORIES,
    LAYER_ID_TOKENS,
    LAYERS,
    discover_layout,
    has_manifest,
    layer_key_from_id_token,
)
from .project_data import project_section, write_project_section
from .structured_data import StructuredDataError, dump, load

# RULE_PATTERN validates rule pattern; this module owns the accepted syntax.
RULE_PATTERN = re.compile(r"^[A-Z0-9]+(?:-[A-Z0-9]+)+$")
# WORKFLOW_PATTERN validates workflow pattern; this module owns the accepted syntax.
WORKFLOW_PATTERN = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
# SHA256_PATTERN validates sha256 pattern; this module owns the accepted syntax.
SHA256_PATTERN = re.compile(r"^[0-9a-f]{64}$")
# CUSTOMIZATION defines customization; this module owns the default.
CUSTOMIZATION = {"unmodified", "custom"}
# APPLICABILITY defines applicability; this module owns the default.
APPLICABILITY = {"applicable", "not-applicable"}
# RULE_LAYERS defines rule layers; this module owns the default.
RULE_LAYERS = set(LAYER_ID_TOKENS.values())
# RULE_LAYER_RANK defines rule layer rank; this module owns the default.
RULE_LAYER_RANK = {LAYER_ID_TOKENS[layer]: index for index, layer in enumerate(LAYERS)}
# GOVERNANCE_SCHEMA_VERSION defines governance schema version; this module owns the default.
GOVERNANCE_SCHEMA_VERSION = 1.1
# SLIM_RULE_TARGETS defines slim rule targets; this module owns the default.
SLIM_RULE_TARGETS = {
    "architecture.md": "specification-architecture.md",
    "build-rules.md": "specification-build-rules.md",
    "domain-spec-authoring.md": "procedure-domain-spec-authoring.md",
    "test-planning.md": "procedure-test-planning.md",
    "eval-planning.md": "procedure-evaluation-planning.md",
    "supportability.md": "specification-supportability.md",
    "artifact-maintenance.md": "specification-artifact-maintenance.md",
    "work-items.md": "specification-work-items.md",
    "artifact-classification.md": "specification-artifact-classification.md",
    "delegation-budget.md": "procedure-delegation-budget.md",
    "skill-runs.md": "procedure-skill-runs.md",
    "release.md": "procedure-release.md",
    "lifecycle-orchestration.md": "procedure-lifecycle-orchestration.md",
    "diagnosis.md": "procedure-diagnosis.md",
    "prototyping.md": "procedure-prototyping.md",
}


def find_repository(start: Path) -> Path:
    """Find repository using the declared repository contract."""
    current = start.resolve()
    if current.is_file():
        current = current.parent
    for candidate in (current, *current.parents):
        if has_manifest(candidate):
            return candidate
    raise FileNotFoundError(f"DSET project root not found from: {start}")


def validate_governance(
    root: Path, expected_profile: str | None = None
) -> list[Diagnostic]:
    """Validate governance using the declared repository contract."""
    root = root.resolve()
    layout = discover_layout(root)
    manifest_path = layout.manifest_path
    if expected_profile is None:
        try:
            manifest = load(manifest_path)
        except (OSError, StructuredDataError):
            manifest = {}
        profiles = manifest.get("profiles", {}) if isinstance(manifest, dict) else {}
        if isinstance(profiles, dict):
            selected = profiles.get("repository_governance")
            expected_profile = str(selected) if selected else None
    if not expected_profile:
        return [
            _diag(
                "CARMADIO-E137",
                manifest_path,
                "repository-governance profile is not selected",
            )
        ]
    registry_path = layout.governance_path
    if not registry_path.is_file():
        return [_diag("CARMADIO-E130", registry_path, "governance registry is missing")]
    try:
        data = project_section(root, "governance_registry")
    except (OSError, ValueError, StructuredDataError) as error:
        return [_diag("CARMADIO-E131", registry_path, str(error))]
    if not isinstance(data, dict):
        return [_diag("CARMADIO-E131", registry_path, "registry must be a mapping")]
    return validate_governance_registry(root, registry_path, data, expected_profile)


def validate_governance_registry(
    root: Path,
    registry_path: Path,
    data: dict[str, Any],
    expected_profile: str,
) -> list[Diagnostic]:
    """Validate governance registry using the declared repository contract."""
    root = root.resolve()
    layout = discover_layout(root)
    diagnostics: list[Diagnostic] = []
    if data.get("schema_version") != GOVERNANCE_SCHEMA_VERSION:
        diagnostics.append(
            _diag(
                "CARMADIO-E131",
                registry_path,
                "unsupported governance registry schema version",
            )
        )
    profile = data.get("profile")
    if not isinstance(profile, dict):
        return [_diag("CARMADIO-E137", registry_path, "profile must be a mapping")]
    if profile.get("id") != expected_profile:
        diagnostics.append(
            _diag(
                "CARMADIO-E137",
                registry_path,
                "registry profile does not match the selected project profile",
            )
        )
    profile_version = profile.get("version")
    if not isinstance(profile_version, str) or not profile_version:
        diagnostics.append(
            _diag("CARMADIO-E137", registry_path, "profile version is missing")
        )
    profile_custom = profile.get("customization")
    if profile_custom not in CUSTOMIZATION:
        diagnostics.append(
            _diag("CARMADIO-E139", registry_path, "invalid profile customization status")
        )

    rules = data.get("rules")
    if not isinstance(rules, list) or not rules:
        return diagnostics + [
            _diag("CARMADIO-E131", registry_path, "rules must be a non-empty list")
        ]
    rule_items = [item for item in rules if isinstance(item, dict)]
    if len(rule_items) != len(rules):
        diagnostics.append(
            _diag("CARMADIO-E131", registry_path, "every rule must be a mapping")
        )
    by_id: dict[str, dict[str, Any]] = {}
    actual_custom: set[str] = set()
    for rule in rule_items:
        rule_id = rule.get("id")
        if not isinstance(rule_id, str) or not RULE_PATTERN.fullmatch(rule_id):
            diagnostics.append(
                _diag("CARMADIO-E131", registry_path, f"invalid rule ID: {rule_id}")
            )
            continue
        if rule_id in by_id:
            diagnostics.append(
                _diag("CARMADIO-E132", registry_path, f"duplicate rule owner: {rule_id}")
            )
            continue
        by_id[rule_id] = rule
        layer = rule.get("layer")
        if layer not in RULE_LAYERS:
            diagnostics.append(
                _diag("CARMADIO-E131", registry_path, f"invalid rule layer: {rule_id}")
            )
        owner = rule.get("owner")
        if not isinstance(owner, str) or not owner.strip():
            diagnostics.append(
                _diag("CARMADIO-E131", registry_path, f"missing rule owner: {rule_id}")
            )
        applicability = rule.get("applicability")
        if applicability not in APPLICABILITY:
            diagnostics.append(
                _diag(
                    "CARMADIO-E137",
                    registry_path,
                    f"invalid applicability for {rule_id}: {applicability}",
                )
            )
        if applicability == "not-applicable" and not str(rule.get("reason", "")):
            diagnostics.append(
                _diag(
                    "CARMADIO-E137",
                    registry_path,
                    f"not-applicable rule requires a reason: {rule_id}",
                )
            )
        local = _rule_carrier(root, rule)
        if local is None:
            diagnostics.append(
                _diag(
                    "CARMADIO-E134",
                    registry_path,
                    f"rule document identity is missing or ambiguous: {rule_id}",
                )
            )
            continue
        if not local.is_file():
            diagnostics.append(
                _diag("CARMADIO-E133", local, f"governing document is missing: {rule_id}")
            )
            continue
        if layout.layered and layer in RULE_LAYERS:
            expected_root = (
                layout.framework_layer_root(layer_key_from_id_token(str(layer)))
                if layout.recursive or layout.separated
                else layout.layer_root(layer_key_from_id_token(str(layer)))
            )
            if not layout.slim:
                expected_root /= "governance"
            if not _is_within(local, expected_root):
                diagnostics.append(
                    _diag(
                        "CARMADIO-E134",
                        local,
                        f"rule is outside its owning layer: {rule_id}/{layer}",
                    )
                )
        source = rule.get("source")
        source_sha = source.get("sha256") if isinstance(source, dict) else None
        if not isinstance(source_sha, str) or not SHA256_PATTERN.fullmatch(source_sha):
            diagnostics.append(
                _diag("CARMADIO-E139", registry_path, f"invalid source digest: {rule_id}")
            )
            continue
        customization = rule.get("customization")
        if customization not in CUSTOMIZATION:
            diagnostics.append(
                _diag("CARMADIO-E139", registry_path, f"invalid customization: {rule_id}")
            )
            continue
        if customization == "custom":
            actual_custom.add(rule_id)
        if customization == "unmodified" and _sha256(local) != source_sha:
            diagnostics.append(
                _diag(
                    "CARMADIO-E139",
                    local,
                    f"local rule changed without custom status: {rule_id}",
                )
            )
    if profile_custom == "unmodified" and actual_custom:
        diagnostics.append(
            _diag(
                "CARMADIO-E139", registry_path, "custom rules require custom profile status"
            )
        )

    diagnostics.extend(_validate_dependencies(registry_path, by_id))
    diagnostics.extend(_validate_precedence(registry_path, by_id))
    workflows = data.get("workflows")
    workflow_items = workflows if isinstance(workflows, list) else []
    if not workflow_items:
        diagnostics.append(
            _diag("CARMADIO-E136", registry_path, "workflows must be a non-empty list")
        )
    workflow_ids: set[str] = set()
    for workflow in workflow_items:
        if not isinstance(workflow, dict):
            diagnostics.append(
                _diag("CARMADIO-E136", registry_path, "every workflow must be a mapping")
            )
            continue
        workflow_id = workflow.get("id")
        if (
            not isinstance(workflow_id, str)
            or not WORKFLOW_PATTERN.fullmatch(workflow_id)
            or workflow_id in workflow_ids
        ):
            diagnostics.append(
                _diag("CARMADIO-E136", registry_path, f"invalid workflow: {workflow_id}")
            )
            continue
        workflow_ids.add(workflow_id)
        selected = workflow.get("rules")
        if not isinstance(selected, list) or not selected:
            diagnostics.append(
                _diag(
                    "CARMADIO-E136", registry_path, f"workflow has no rules: {workflow_id}"
                )
            )
            continue
        seen: set[str] = set()
        for rule_id in selected:
            if not isinstance(rule_id, str) or rule_id not in by_id:
                diagnostics.append(
                    _diag(
                        "CARMADIO-E131",
                        registry_path,
                        f"workflow references missing rule owner: {rule_id}",
                    )
                )
                continue
            rule = by_id[rule_id]
            if rule.get("applicability") != "applicable":
                diagnostics.append(
                    _diag(
                        "CARMADIO-E137",
                        registry_path,
                        f"workflow selects incompatible rule: {rule_id}",
                    )
                )
            dependencies = rule.get("depends_on", [])
            if isinstance(dependencies, list) and not set(dependencies).issubset(seen):
                diagnostics.append(
                    _diag(
                        "CARMADIO-E135",
                        registry_path,
                        "workflow dependency order is invalid: "
                        f"{workflow_id}/{rule_id}",
                    )
                )
            seen.add(rule_id)
    diagnostics.extend(
        _validate_wrappers(root, registry_path, data.get("wrappers"), workflow_ids)
    )
    return sorted(set(diagnostics))


def resolve_workflow(
    root: Path, workflow_id: str
) -> tuple[dict[str, Any] | None, list[Diagnostic]]:
    """Resolve workflow using the declared repository contract."""
    root = root.resolve()
    diagnostics = validate_governance(root)
    if diagnostics:
        return None, diagnostics
    path = discover_layout(root).governance_path
    data = project_section(root, "governance_registry")
    workflow = next(
        (
            item
            for item in data["workflows"]
            if isinstance(item, dict) and item.get("id") == workflow_id
        ),
        None,
    )
    if workflow is None:
        return None, [_diag("CARMADIO-E136", path, f"unknown workflow: {workflow_id}")]
    by_id = {item["id"]: item for item in data["rules"]}
    wrapper = next(
        (
            item
            for item in data.get("wrappers", [])
            if isinstance(item, dict) and item.get("workflow") == workflow_id
        ),
        None,
    )
    rules: list[dict[str, Any]] = []
    for rule_id in workflow["rules"]:
        rule = by_id[rule_id]
        source = rule["source"]
        local = _rule_carrier(root, rule)
        if local is None:
            return None, [
                _diag(
                    "CARMADIO-E134",
                    path,
                    f"rule document identity is missing or ambiguous: {rule_id}",
                )
            ]
        rules.append(
            {
                "id": rule_id,
                "layer": rule["layer"],
                "document": rule.get("document", local.name),
                "owner": rule["owner"],
                "applicability": rule["applicability"],
                "precedence_over": list(rule["precedence_over"]),
                "customization": rule["customization"],
                "source_profile": source["profile"],
                "source_version": source["version"],
                "sha256": _sha256(local),
            }
        )
    profile = data["profile"]
    return (
        {
            "workflow_id": workflow_id,
            "profile": profile["id"],
            "profile_version": profile["version"],
            "customization": profile["customization"],
            "rules": rules,
            "wrapper": wrapper,
            "conflicts": [],
            "conflict_resolution": {
                "status": "unavailable",
                "coverage": [],
                "reason_code": "CARMADIO-CONFLICT-RESOLUTION-UNAVAILABLE",
            },
        },
        [],
    )


def materialize_governance(
    source_root: Path,
    target_root: Path,
    profile_id: str = "core-v1",
    *,
    install_wrappers: bool = False,
) -> Path:
    """Handle governance using the declared repository contract."""
    source_root = source_root.resolve()
    target_root = target_root.resolve()
    source_layout = discover_layout(source_root)
    target_layout = discover_layout(target_root)
    manifest = target_layout.manifest_path
    if not manifest.is_file():
        raise DsetCommandError("CARMADIO-E001", manifest, "project manifest is missing")
    if target_layout.separated:
        raise DsetCommandError(
            "CARMADIO-E140",
            manifest,
            "schema 1.5 installs methodology as one edition; use methodology sync",
        )
    try:
        profile_path = source_layout.find_template(
            Path("governance") / profile_id / "profile.yaml"
        )
    except (FileNotFoundError, ValueError) as error:
        raise DsetCommandError(
            "CARMADIO-E140",
            source_layout.template_roots[0]
            / "governance"
            / profile_id
            / "profile.yaml",
            str(error),
        ) from error
    profile = cast(dict[str, Any], load(profile_path))
    project = cast(dict[str, Any], load(manifest))
    release = project.get("release", {})
    release_not_applicable = (
        isinstance(release, dict) and release.get("status") == "not-applicable"
    )
    if profile.get("id") != profile_id:
        raise DsetCommandError(
            "CARMADIO-E140", profile_path, "governance profile identity mismatch"
        )
    registry_path = target_layout.governance_path
    rules = cast(list[dict[str, Any]], profile.get("rules", []))
    profile_relative = Path("governance") / profile_id

    def source_template(relative: Path) -> Path:
        """Handle template using the declared repository contract."""
        try:
            return source_layout.find_template(relative)
        except (FileNotFoundError, ValueError) as error:
            raise DsetCommandError(
                "CARMADIO-E140", source_layout.template_roots[0] / relative, str(error)
            ) from error

    readme_template = source_template(profile_relative / "README.md")
    templates: dict[str, Path] = {}
    targets: dict[str, Path] = {}
    governance_roots = {target_layout.governance_root}
    for item in rules:
        rule_id = str(item.get("id", ""))
        layer = item.get("layer")
        if layer not in RULE_LAYERS:
            raise DsetCommandError(
                "CARMADIO-E140", profile_path, f"invalid rule layer: {rule_id}/{layer}"
            )
        templates[rule_id] = source_template(profile_relative / str(item["template"]))
        destination = target_layout.governance_root
        if target_layout.layered:
            destination = (
                target_layout.framework_layer_root(layer_key_from_id_token(str(layer)))
                if target_layout.recursive or target_layout.separated
                else target_layout.layer_root(layer_key_from_id_token(str(layer)))
            )
            if not target_layout.slim:
                destination /= "governance"
            governance_roots.add(destination)
        target_name = str(item["target"])
        if target_layout.slim:
            target_name = SLIM_RULE_TARGETS.get(target_name, target_name)
        targets[rule_id] = destination / target_name
    hub_path = target_layout.governance_root / (
        "navigation-governance.md" if target_layout.slim else "README.md"
    )
    existing = [path for path in targets.values() if path.exists()]
    if hub_path.exists():
        existing.append(hub_path)
    registry_exists = False
    if registry_path.is_file():
        try:
            registry_exists = bool(project_section(target_root, "governance_registry"))
        except ValueError:
            registry_exists = False
    if registry_exists or existing:
        occupied = registry_path if registry_exists else sorted(existing)[0]
        raise FileExistsError(f"governance destination already exists: {occupied}")
    copied_wrappers: list[Path] = []
    for destination in sorted(governance_roots):
        destination.mkdir(parents=True, exist_ok=target_layout.slim)
    try:
        _write_governance_hub(
            readme_template,
            hub_path,
            layered=target_layout.layered,
            slim=target_layout.slim,
            separated=target_layout.separated,
        )
        rendered_rules: list[dict[str, Any]] = []
        for item in rules:
            rule_id = str(item["id"])
            template = templates[rule_id]
            target = targets[rule_id]
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(template, target)
            applicability = item.get("applicability", "applicable")
            reason = item.get("reason", "selected by the local profile")
            if item["id"] == "CARMADIO-RULE-RELEASE" and release_not_applicable:
                applicability = "not-applicable"
                reason = str(release.get("reason"))
            dependencies = list(item.get("depends_on", []))
            if release_not_applicable:
                dependencies = [
                    dependency
                    for dependency in dependencies
                    if dependency != "CARMADIO-RULE-RELEASE"
                ]
            rendered_rules.append(
                {
                    "id": rule_id,
                    "layer": item["layer"],
                    "document": target.name,
                    "owner": "project",
                    "applicability": applicability,
                    "reason": reason,
                    "depends_on": dependencies,
                    "precedence_over": list(item.get("precedence_over", [])),
                    "customization": "unmodified",
                    "source": {
                        "profile": profile_id,
                        "version": str(profile["version"]),
                        "template": template.name,
                        "sha256": _sha256(template),
                    },
                }
            )
        wrappers: list[dict[str, Any]] = []
        for item in cast(list[dict[str, Any]], profile.get("wrappers", [])):
            if release_not_applicable and item.get("workflow") == "release":
                continue
            skill = str(item["skill"])
            source = _wrapper_carrier(source_root, item)
            wrapper_target = _wrapper_carrier(target_root, item)
            if source is None:
                raise FileNotFoundError(f"source skill wrapper is missing: {skill}")
            if wrapper_target is None:
                wrapper_target = target_root / "skills" / skill / "SKILL.md"
            if source_root != target_root and install_wrappers:
                folder = wrapper_target.parent
                if folder.exists():
                    raise FileExistsError(f"wrapper destination exists: {folder}")
                shutil.copytree(source.parent, folder)
                copied_wrappers.append(folder)
            if wrapper_target.is_file():
                wrappers.append(
                    {
                        "workflow": item["workflow"],
                        "skill": skill,
                        "sha256": _sha256(source),
                    }
                )
        rendered_workflows = []
        for workflow in cast(list[dict[str, Any]], profile["workflows"]):
            if release_not_applicable and workflow.get("id") == "release":
                continue
            rendered = dict(workflow)
            if release_not_applicable:
                rendered["rules"] = [
                    rule
                    for rule in cast(list[str], workflow.get("rules", []))
                    if rule != "CARMADIO-RULE-RELEASE"
                ]
            rendered_workflows.append(rendered)
        registry = {
            "schema_version": profile.get("schema_version", GOVERNANCE_SCHEMA_VERSION),
            "profile": {
                "id": profile_id,
                "version": str(profile["version"]),
                "customization": "unmodified",
            },
            "rules": rendered_rules,
            "workflows": rendered_workflows,
            "wrappers": wrappers,
        }
        if target_layout.recursive or target_layout.separated:
            write_project_section(target_root, "governance_registry", registry)
        else:
            registry_path.write_text(dump(registry, registry_path), encoding="utf-8")
    except Exception:
        if registry_path.exists() and not (
            target_layout.recursive or target_layout.separated
        ):
            registry_path.unlink()
        hub_path.unlink(missing_ok=True)
        for target in targets.values():
            target.unlink(missing_ok=True)
        if not target_layout.slim:
            for destination in sorted(governance_roots, reverse=True):
                if destination.exists():
                    shutil.rmtree(destination)
        for wrapper in copied_wrappers:
            if wrapper.exists():
                shutil.rmtree(wrapper)
        raise
    return registry_path


def _write_governance_hub(
    source: Path,
    target: Path,
    *,
    layered: bool,
    slim: bool = False,
    separated: bool = False,
) -> None:
    """Write governance hub using the declared repository contract."""
    content = source.read_text(encoding="utf-8")
    if layered:
        for layer in ("meta", "tool", "skill", "implementation", "ops"):
            for source_directory in (layer, LAYER_DIRECTORIES[layer]):
                content = content.replace(
                    f"../../../../{source_directory}/templates/governance/core-v1/",
                    f"../../{layer}/governance/",
                )
    if slim:
        layer_names = {
            "meta": "01_meta" if separated else "01_layer_meta",
            "tool": "03_tool" if separated else "03_layer_tool",
            "skill": "04_skill" if separated else "04_layer_skill",
            "implementation": (
                "05_implementation" if separated else "05_layer_implementation"
            ),
            "ops": "06_ops" if separated else "06_layer_ops",
        }
        replacements = {
            "architecture.md": "specification-architecture.md",
            (
                "../../tool/governance/build-rules.md"
            ): f"../{layer_names['tool']}/specification-build-rules.md",
            (
                "../../meta/governance/domain-spec-authoring.md"
            ): f"../{layer_names['meta']}/procedure-domain-spec-authoring.md",
            (
                "../../meta/governance/test-planning.md"
            ): f"../{layer_names['meta']}/procedure-test-planning.md",
            (
                "../../meta/governance/eval-planning.md"
            ): f"../{layer_names['meta']}/procedure-evaluation-planning.md",
            (
                "../../skill/governance/diagnosis.md"
            ): f"../{layer_names['skill']}/procedure-diagnosis.md",
            (
                "../../skill/governance/prototyping.md"
            ): f"../{layer_names['skill']}/procedure-prototyping.md",
            (
                "../../ops/governance/supportability.md"
            ): f"../{layer_names['ops']}/specification-supportability.md",
            "artifact-maintenance.md": "specification-artifact-maintenance.md",
            "artifact-classification.md": "specification-artifact-classification.md",
            (
                "../../skill/governance/lifecycle-orchestration.md"
            ): f"../{layer_names['skill']}/procedure-lifecycle-orchestration.md",
            (
                "../../skill/governance/skill-runs.md"
            ): f"../{layer_names['skill']}/procedure-skill-runs.md",
            (
                "../../skill/governance/delegation-budget.md"
            ): f"../{layer_names['skill']}/procedure-delegation-budget.md",
            (
                "../../ops/governance/release.md"
            ): f"../{layer_names['ops']}/procedure-release.md",
            "work-items.md": "specification-work-items.md",
        }
        for old, new in replacements.items():
            content = content.replace(old, new)
    target.write_text(content, encoding="utf-8")


def refresh_customization(root: Path) -> Path:
    """Handle customization using the declared repository contract."""
    root = root.resolve()
    path = discover_layout(root).governance_path
    data = project_section(root, "governance_registry")
    custom = False
    for rule in cast(list[dict[str, Any]], data.get("rules", [])):
        local = _rule_carrier(root, rule)
        source = rule.get("source")
        source_sha = source.get("sha256") if isinstance(source, dict) else None
        if local is None or not local.is_file() or not isinstance(source_sha, str):
            continue
        status = "unmodified" if _sha256(local) == source_sha else "custom"
        rule["customization"] = status
        custom = custom or status == "custom"
    cast(dict[str, Any], data["profile"])["customization"] = (
        "custom" if custom else "unmodified"
    )
    write_project_section(root, "governance_registry", data)
    return path


def diff_governance(root: Path, source_root: Path) -> str:
    """Handle governance using the declared repository contract."""
    root = root.resolve()
    source_root = source_root.resolve()
    data = project_section(root, "governance_registry")
    output: list[str] = []
    for rule in cast(list[dict[str, Any]], data.get("rules", [])):
        source = cast(dict[str, Any], rule["source"])
        template = _unique_named_file(source_root / ".carmadio", source.get("template"))
        local = _rule_carrier(root, rule)
        if template is None or local is None:
            continue
        output.extend(
            difflib.unified_diff(
                template.read_text(encoding="utf-8").splitlines(keepends=True),
                local.read_text(encoding="utf-8").splitlines(keepends=True),
                fromfile=template.name,
                tofile=local.name,
            )
        )
    return "".join(output) or "No local governance differences.\n"


def _validate_dependencies(
    path: Path, by_id: dict[str, dict[str, Any]]
) -> list[Diagnostic]:
    """Validate dependencies using the declared repository contract."""
    diagnostics: list[Diagnostic] = []
    for rule_id, rule in by_id.items():
        dependencies = rule.get("depends_on", [])
        if not isinstance(dependencies, list):
            diagnostics.append(
                _diag("CARMADIO-E135", path, f"dependencies must be a list: {rule_id}")
            )
            continue
        for dependency in dependencies:
            if dependency not in by_id:
                diagnostics.append(
                    _diag(
                        "CARMADIO-E131",
                        path,
                        f"dependency has no rule owner: {rule_id}/{dependency}",
                    )
                )
                continue
            source_layer = rule.get("layer")
            dependency_layer = by_id[dependency].get("layer")
            if (
                source_layer in RULE_LAYER_RANK
                and dependency_layer in RULE_LAYER_RANK
                and RULE_LAYER_RANK[str(dependency_layer)]
                > RULE_LAYER_RANK[str(source_layer)]
            ):
                diagnostics.append(
                    _diag(
                        "CARMADIO-E151",
                        path,
                        "rule dependency creates backward layer authority: "
                        f"{rule_id}/{dependency}; resolve or re-home it, or "
                        "propose converting irreducible peer layers to features "
                        "with horizontal Contracts",
                    )
                )
    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(rule_id: str) -> None:
        """Handle visit using the declared repository contract."""
        if rule_id in visiting:
            diagnostics.append(
                _diag("CARMADIO-E135", path, f"rule dependency cycle includes: {rule_id}")
            )
            return
        if rule_id in visited:
            return
        visiting.add(rule_id)
        dependencies = by_id[rule_id].get("depends_on", [])
        if isinstance(dependencies, list):
            for dependency in dependencies:
                if isinstance(dependency, str) and dependency in by_id:
                    visit(dependency)
        visiting.remove(rule_id)
        visited.add(rule_id)

    for rule_id in by_id:
        visit(rule_id)
    return diagnostics


def _validate_precedence(
    path: Path, by_id: dict[str, dict[str, Any]]
) -> list[Diagnostic]:
    """Validate precedence using the declared repository contract."""
    diagnostics: list[Diagnostic] = []
    graph: dict[str, list[str]] = {}
    for rule_id, rule in by_id.items():
        precedence = rule.get("precedence_over")
        if not isinstance(precedence, list):
            diagnostics.append(
                _diag(
                    "CARMADIO-E150",
                    path,
                    f"precedence_over must be a list: {rule_id}",
                )
            )
            graph[rule_id] = []
            continue
        if len(precedence) != len(set(map(str, precedence))):
            diagnostics.append(
                _diag(
                    "CARMADIO-E150",
                    path,
                    f"precedence targets must be unique: {rule_id}",
                )
            )
        graph[rule_id] = []
        for target in precedence:
            if not isinstance(target, str) or target not in by_id:
                diagnostics.append(
                    _diag(
                        "CARMADIO-E150",
                        path,
                        f"precedence target has no rule owner: {rule_id}/{target}",
                    )
                )
                continue
            source_layer = rule.get("layer")
            target_layer = by_id[target].get("layer")
            if (
                source_layer in RULE_LAYER_RANK
                and target_layer in RULE_LAYER_RANK
                and RULE_LAYER_RANK[str(source_layer)]
                > RULE_LAYER_RANK[str(target_layer)]
            ):
                diagnostics.append(
                    _diag(
                        "CARMADIO-E151",
                        path,
                        "rule precedence creates backward layer authority: "
                        f"{rule_id}/{target}; resolve or re-home it, or propose "
                        "converting irreducible peer layers to features with "
                        "horizontal Contracts",
                    )
                )
            graph[rule_id].append(target)

    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(rule_id: str) -> None:
        """Handle visit using the declared repository contract."""
        if rule_id in visiting:
            diagnostics.append(
                _diag(
                    "CARMADIO-E150",
                    path,
                    f"rule precedence cycle includes: {rule_id}",
                )
            )
            return
        if rule_id in visited:
            return
        visiting.add(rule_id)
        for target in graph.get(rule_id, []):
            visit(target)
        visiting.remove(rule_id)
        visited.add(rule_id)

    for rule_id in by_id:
        visit(rule_id)
    return diagnostics


def _validate_wrappers(
    root: Path,
    registry_path: Path,
    raw: Any,
    workflow_ids: set[str],
) -> list[Diagnostic]:
    """Validate wrappers using the declared repository contract."""
    diagnostics: list[Diagnostic] = []
    wrappers = raw if isinstance(raw, list) else []
    seen: set[str] = set()
    for wrapper in wrappers:
        if not isinstance(wrapper, dict):
            diagnostics.append(
                _diag("CARMADIO-E138", registry_path, "every wrapper must be a mapping")
            )
            continue
        workflow = wrapper.get("workflow")
        if not isinstance(workflow, str) or workflow not in workflow_ids:
            diagnostics.append(
                _diag(
                    "CARMADIO-E138", registry_path, f"unknown wrapper workflow: {workflow}"
                )
            )
            continue
        if workflow in seen:
            diagnostics.append(
                _diag("CARMADIO-E138", registry_path, f"duplicate wrapper: {workflow}")
            )
        seen.add(workflow)
        path = _wrapper_carrier(root, wrapper)
        expected = wrapper.get("sha256")
        if path is None or not path.is_file():
            diagnostics.append(
                _diag("CARMADIO-E138", registry_path, f"wrapper is missing: {workflow}")
            )
        elif not isinstance(expected, str) or _sha256(path) != expected:
            diagnostics.append(
                _diag("CARMADIO-E138", path, f"wrapper identity mismatch: {workflow}")
            )
    return diagnostics


def _local_path(root: Path, raw: Any) -> Path | None:
    """Handle path using the declared repository contract."""
    if not isinstance(raw, str) or not raw or Path(raw).is_absolute():
        return None
    path = (root / raw).resolve()
    try:
        path.relative_to(root)
    except ValueError:
        return None
    return path


def _unique_named_file(control_root: Path, raw: Any) -> Path | None:
    """Handle named file using the declared repository contract."""
    if not isinstance(raw, str):
        return None
    try:
        root = control_root.parent if control_root.name == ".carmadio" else control_root
        return find_unique_name(root, raw)
    except (FileNotFoundError, ValueError):
        return None


def _wrapper_carrier(root: Path, wrapper: dict[str, Any]) -> Path | None:
    """Handle carrier using the declared repository contract."""
    skill = wrapper.get("skill")
    if isinstance(skill, str) and skill and Path(skill).name == skill:
        path = (root / "skills" / skill / "SKILL.md").resolve()
        try:
            path.relative_to(root.resolve())
        except ValueError:
            return None
        return path
    return _local_path(root, wrapper.get("path"))


def _rule_carrier(root: Path, rule: dict[str, Any]) -> Path | None:
    document = rule.get("document")
    if document is not None:
        return _unique_named_file(root / ".carmadio", document)
    return _local_path(root, rule.get("path"))


def _is_within(path: Path, parent: Path) -> bool:
    try:
        path.resolve().relative_to(parent.resolve())
    except ValueError:
        return False
    return True


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _diag(code: str, path: Path, message: str) -> Diagnostic:
    return Diagnostic(code=code, path=path, message=message)

"""Provide DSET identity behavior."""

from __future__ import annotations

import re
from collections.abc import Iterator
from pathlib import Path

# IDENTITY_FIELDS defines identity fields; this module owns the default.
IDENTITY_FIELDS = (
    "artifact_id",
    "semantic_id",
    "document_id",
    "rule_id",
)
# TEXT_SUFFIXES defines text suffixes; this module owns the default.
TEXT_SUFFIXES = {".json", ".md", ".toml", ".txt"}
# NUMBERED_PREFIX defines numbered prefix; this module owns the default.
NUMBERED_PREFIX = re.compile(r"^[0-9]+_")


def logical_part(name: str) -> str:
    """Return a numbered layout entry's semantic directory name."""

    return NUMBERED_PREFIX.sub("", name, count=1)


def has_logical_part(path: Path, names: set[str] | frozenset[str]) -> bool:
    """Handle logical part using the declared repository contract."""
    return any(logical_part(part) in names for part in path.parts)


def control_root(root: Path) -> Path:
    """Handle root using the declared repository contract."""
    return root.resolve() / ".carmadio"


def iter_control_files(root: Path, pattern: str = "*") -> Iterator[Path]:
    """Yield DSET carriers from the target project's control plane only."""

    directory = control_root(root)
    if not directory.is_dir():
        return
    yield from (path for path in sorted(directory.rglob(pattern)) if path.is_file())


def find_unique_name(root: Path, name: str) -> Path:
    """Find unique name using the declared repository contract."""
    if not name or Path(name).name != name:
        raise ValueError(f"DSET carrier name must not contain a path: {name}")
    matches = list(iter_control_files(root, name))
    if not matches:
        raise FileNotFoundError(f"DSET carrier name is missing: {name}")
    if len(matches) > 1:
        raise ValueError(f"DSET carrier name is not unique: {name}")
    return matches[0]


def find_unique_identity(root: Path, identity: str) -> Path:
    """Find unique identity using the declared repository contract."""
    if not identity or "/" in identity or "\\" in identity:
        raise ValueError(f"DSET identity must not contain a path: {identity}")
    escaped = re.escape(identity)
    field_pattern = re.compile(
        rf'^(?:{"|".join(IDENTITY_FIELDS)})\s*=\s*"{escaped}"\s*$',
        re.MULTILINE,
    )
    rule_pattern = re.compile(rf"\*\*Rule ID:\*\*\s*`{escaped}`")
    matches: list[Path] = []
    for path in iter_control_files(root):
        if path.suffix.lower() not in TEXT_SUFFIXES:
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            continue
        if field_pattern.search(text) or rule_pattern.search(text):
            matches.append(path)
    if not matches:
        raise FileNotFoundError(f"DSET identity is missing: {identity}")
    if len(matches) > 1:
        raise ValueError(f"DSET identity is not unique: {identity}")
    return matches[0]

