        return (self.carmadio_root / "changes",)

    @property
    def archive_change_roots(self) -> tuple[Path, ...]:
        """Archive change roots using the declared repository contract."""
        if self.slim:
            return (self.versions_root / "archive",)
        return tuple(path / "archive" for path in self.active_change_roots)

    @property
    def package_roots(self) -> tuple[Path, ...]:
        """Handle roots using the declared repository contract."""
        if self.recursive or self.separated:
            return ()
        if self.slim:
            return tuple(self.layer_root(layer) for layer in LAYERS)
        if self.layered:
            return tuple(
                self.layer_root(layer) / "specs" / "packages" for layer in LAYERS
            )
        return (self.carmadio_root / "specs" / "packages",)

    def schema_paths(self) -> Iterator[Path]:
        """Handle paths using the declared repository contract."""
        seen: dict[str, Path] = {}
        for root in self.schema_roots:
            if root.is_dir():
                for path in sorted(root.glob("*.schema.toml")):
                    previous = seen.get(path.name)
                    if previous is not None:
                        raise ValueError(
                            "schema is not unique: "
                            f"{path.name} ({previous.as_posix()}, {path.as_posix()})"
                        )
                    seen[path.name] = path
                    yield path

    def find_template(self, relative: str | Path) -> Path:
        """Find template using the declared repository contract."""
        if self.recursive or self.separated:
            return self._find_numbered_unique(self.template_roots, relative, "template")
        return self._find_unique(self.template_roots, relative, "template")

    def package_fragments(self) -> tuple[Path, ...]:
        """Handle fragments using the declared repository contract."""
        if self.recursive or self.separated:
            return ()
        if self.slim:
            return tuple(
                path
                for path in (
                    self.structured_file(self.layer_root(layer), "package.toml")
                    for layer in LAYERS
                )
                if path.is_file()
            )
        fragments: list[Path] = []
        for root in self.package_roots:
            if root.is_dir():
                fragments.extend(self.structured_named_files(root, "package"))
        return tuple(sorted(fragments))

    @staticmethod
    def structured_file(directory: Path, name: str) -> Path:
        """Resolve canonical TOML with explicit legacy YAML read fallback."""

        requested = directory / name
        if requested.suffix.lower() not in {".toml", ".yaml", ".yml"}:
            return requested
        stem = requested.with_suffix("")
        canonical = stem.with_suffix(".toml")
        legacy = (stem.with_suffix(".yaml"), stem.with_suffix(".yml"))
        if canonical.is_file():
            return canonical
        for candidate in legacy:
            if candidate.is_file():
                if _registered_snapshot_after_cutover(candidate):
                    return canonical
                return candidate
        return canonical if requested.suffix.lower() == ".toml" else requested

    @staticmethod
    def structured_named_files(root: Path, stem: str) -> tuple[Path, ...]:
        """Return one TOML-preferred carrier per directory for a basename."""

        by_parent: dict[Path, list[Path]] = {}
        for suffix in (".toml", ".yaml", ".yml"):
            for path in root.rglob(f"{stem}{suffix}"):
                by_parent.setdefault(path.parent, []).append(path)
        selected: list[Path] = []
        for parent, candidates in sorted(by_parent.items()):
            canonical = parent / f"{stem}.toml"
            selected.append(
                canonical if canonical in candidates else sorted(candidates)[0]
            )
        return tuple(selected)

    def active_change_root(self, layer: str | None = None) -> Path:
        """Handle change root using the declared repository contract."""
        if self.slim:
            return self.active_change_roots[0]
        if not self.layered:
            return self.active_change_roots[0]
        if layer is None:
            raise ValueError("schema 1.2 changes require an owning DSET layer")
        return self.layer_root(layer) / "changes"

    def archive_change_root(self, layer: str | None = None) -> Path:
        """Archive change root using the declared repository contract."""
        if self.slim:
            return self.archive_change_roots[0]
        return self.active_change_root(layer) / "archive"

    def find_change(self, change_id: str, *, archived: bool = False) -> Path:
        """Find change using the declared repository contract."""
        roots = self.archive_change_roots if archived else self.active_change_roots
        matches: list[Path] = []
        for root in roots:
            if not root.is_dir():
                continue
            if archived or self.layered:
                for path in root.iterdir():
                    manifest = self.structured_file(path, "change.yaml")
                    if not path.is_dir() or not manifest.is_file():
                        continue
                    try:
                        data = load(manifest)
                    except (OSError, ValueError, StructuredDataError):
                        continue
                    if isinstance(data, dict) and data.get("id") == change_id:
                        matches.append(path)
            else:
                candidate = root / change_id
                if candidate.is_dir():
                    matches.append(candidate)
        if not matches:
            state = "archived" if archived else "active"
            raise FileNotFoundError(f"{state} change does not exist: {change_id}")
        if len(matches) > 1:
            rendered = ", ".join(
                path.relative_to(self.root).as_posix() for path in matches
            )
            raise ValueError(f"change ID is not unique: {change_id} ({rendered})")
        return matches[0]

    def change_layer(self, change: Path) -> str | None:
        """Handle layer using the declared repository contract."""
        resolved = change.resolve()
        if self.slim:
            manifest = self.structured_file(resolved, "change.toml")
            try:
                data = load(manifest)
            except (OSError, ValueError, StructuredDataError) as error:
                raise ValueError(
                    f"cannot read Change layer: {manifest}: {error}"
                ) from error
            raw = data.get("primary_layer") if isinstance(data, dict) else None
            if not isinstance(raw, str) or raw.lower() not in LAYERS:
                raise ValueError(f"Change has no registered layer: {manifest}")
            return raw.lower()
        if not self.layered:
            return None
        for layer, root in self.layer_roots.items():
            try:
                resolved.relative_to(root / "changes")
            except ValueError:
                continue
            return layer
        raise ValueError(f"change is outside the DSET layout: {change}")

    def resolve_dset_path(self, relative: str | Path) -> Path:
        """Resolve dset path using the declared repository contract."""
        return self.carmadio_root / _canonical_relative(relative)

    def _owned_file(self, layer: str, name: str) -> Path:
        base = self.layer_root(layer) if self.layered else self.carmadio_root
        return self.structured_file(base, name)

    def _owned_directory(self, layer: str, name: str) -> Path:
        return self._owned_file(layer, name)

    def _preferred_name(self, stem: str) -> str:
        suffix = ".toml" if self.manifest_path.suffix == ".toml" else ".yaml"
        return f"{stem}{suffix}"

    @staticmethod
    def _numbered_directory(parent: Path, logical_name: str) -> Path:
        """Handle directory using the declared repository contract."""
        exact = parent / logical_name
        if exact.is_dir():
            return exact
        matches = (
            sorted(
                path
                for path in parent.iterdir()
                if path.is_dir() and _strip_numeric_prefix(path.name) == logical_name
            )
            if parent.is_dir()
            else []
        )
        if not matches:
            return exact
        if len(matches) > 1:
            rendered = ", ".join(path.as_posix() for path in matches)
            raise ValueError(
                f"methodology directory is not unique: {logical_name} ({rendered})"
            )
        return matches[0]

    @staticmethod
    def _numbered_file(parent: Path, logical_name: str) -> Path:
        """Handle file using the declared repository contract."""
        exact = parent / logical_name
        if exact.is_file():
            return exact
        requested = Path(logical_name)
        suffix = "".join(requested.suffixes)
        stem = requested.name[: -len(suffix)] if suffix else requested.name
        pattern = f"*-{stem}{suffix}"
        matches = sorted(parent.glob(pattern)) if parent.is_dir() else []
        if not matches:
            return exact
        if len(matches) > 1:
            rendered = ", ".join(path.as_posix() for path in matches)
            raise ValueError(
                f"methodology file is not unique: {logical_name} ({rendered})"
            )
        return matches[0]

    @staticmethod
    def _find_numbered_unique(
        roots: tuple[Path, ...], relative: str | Path, kind: str
    ) -> Path:
        """Find numbered unique using the declared repository contract."""
        normalized = _canonical_relative(relative)
        suffixes = [normalized]
        if normalized.suffix.lower() in {".toml", ".yaml", ".yml"}:
            stem = normalized.with_suffix("")
            suffixes = [
                stem.with_suffix(suffix) for suffix in (".toml", ".yaml", ".yml")
            ]
        candidates: list[Path] = []
        for root in roots:
            for candidate in suffixes:
                ending = "-".join(
                    _methodology_component(part) for part in candidate.parts
                )
                candidates.extend(root.rglob(f"*-{ending}"))
        matches = sorted({path for path in candidates if path.is_file()})
        if not matches:
            raise FileNotFoundError(f"{kind} is missing: {relative}")
        if len(matches) > 1:
            rendered = ", ".join(path.as_posix() for path in matches)
            raise ValueError(f"{kind} is not unique: {relative} ({rendered})")
        return matches[0]

    @staticmethod
    def _find_unique(roots: tuple[Path, ...], relative: str | Path, kind: str) -> Path:
        """Find unique using the declared repository contract."""
        normalized = _canonical_relative(relative)
        candidates: list[Path] = []
        for root in roots:
            requested = root / normalized
            if requested.suffix.lower() in {".toml", ".yaml", ".yml"}:
                stem = requested.with_suffix("")
                candidates.extend(
                    stem.with_suffix(suffix) for suffix in (".toml", ".yaml", ".yml")
                )
            else:
                candidates.append(requested)
        matches = [path for path in candidates if path.is_file()]
        if not matches:
            raise FileNotFoundError(f"{kind} is missing: {relative}")
        if len(matches) > 1:
            rendered = ", ".join(path.as_posix() for path in matches)
            raise ValueError(f"{kind} is not unique: {relative} ({rendered})")
        return matches[0]


def _strip_numeric_prefix(name: str) -> str:
    return re.sub(r"^\d{3}_", "", name, count=1)


def _methodology_component(name: str) -> str:
    """Handle component using the declared repository contract."""
    normalized = _strip_numeric_prefix(name)
    if normalized.lower() == "readme.md":
        return "hub.md"
    path = Path(normalized)
    suffix = "".join(path.suffixes)
    stem = normalized[: -len(suffix)] if suffix else normalized
    stem = stem.replace("—", "-").replace("–", "-")
    stem = re.sub(r"[^A-Za-z0-9]+", "-", stem).strip("-").lower()
    return f"{stem}{suffix.lower()}"


def discover_layout(root: Path) -> RepositoryLayout:
    """Discover a DSET layout, defaulting missing repositories to legacy paths."""

    root = root.resolve()
    legacy_root = root / LEGACY_DSET_ROOT
    current_root = root / CURRENT_DSET_ROOT
    legacy = _manifest_candidate(legacy_root / "dset.yaml")
    layered = _manifest_candidate(legacy_root / "scopes" / "meta" / "dset.yaml")
    slim = current_root / "carmadio_settings.toml"
    manifests = [path for path in (legacy, layered, slim) if path.is_file()]
    if len(manifests) > 1:
        raise ValueError(
            "DSET project has competing manifests: "
            + ", ".join(path.as_posix() for path in manifests)
        )
    manifest = slim if slim.is_file() else layered if layered.is_file() else legacy
    is_slim = slim.is_file()
    is_layered = is_slim or layered.is_file()
    version = _schema_version(manifest) if manifest.is_file() else None
    structure_layout = _structure_layout(manifest) if is_slim else None
    if is_slim and version not in {
        SLIM_SCHEMA_VERSION,
        RECURSIVE_SCHEMA_VERSION,
        *SEPARATED_SCHEMA_VERSIONS,
    }:
        raise ValueError(
            "hidden DSET manifest must declare schema 1.3, 1.4, "
            f"or 1.5-1.8: {slim}"
        )
    allowed_hidden_layouts = {
        LEGACY_SLIM_LAYOUT,
        NUMBERED_LAYER_LAYOUT,
        RECURSIVE_FRAMEWORK_LAYOUT,
        SEPARATED_METHODOLOGY_LAYOUT,
    }
    if is_slim and structure_layout not in allowed_hidden_layouts:
        raise ValueError(
            "hidden DSET manifest must select slim-v1, numbered-layers-v1, "
            "recursive-framework-v1, or separated-methodology-v1: "
            f"{slim}"
        )
    if (
        version == RECURSIVE_SCHEMA_VERSION
        and structure_layout != RECURSIVE_FRAMEWORK_LAYOUT
    ):
        raise ValueError(f"schema 1.4 must select recursive-framework-v1: {slim}")
    if (
        version == SLIM_SCHEMA_VERSION
        and structure_layout == RECURSIVE_FRAMEWORK_LAYOUT
    ):
        raise ValueError(f"recursive-framework-v1 requires schema 1.4: {slim}")
    if (
        version in SEPARATED_SCHEMA_VERSIONS
        and structure_layout != SEPARATED_METHODOLOGY_LAYOUT
    ):
        raise ValueError(
            f"schemas 1.5-1.8 must select separated-methodology-v1: {slim}"
        )
    if (
        version not in SEPARATED_SCHEMA_VERSIONS
        and structure_layout == SEPARATED_METHODOLOGY_LAYOUT
    ):
        raise ValueError(
            f"separated-methodology-v1 requires schema 1.5-1.8: {slim}"
        )
    if not is_slim and is_layered and version != LAYERED_SCHEMA_VERSION:
        raise ValueError(f"layered DSET manifest must declare schema 1.2: {layered}")
    if not is_layered and version is not None and version not in LEGACY_SCHEMA_VERSIONS:
        raise ValueError(
            f"central DSET manifest must declare schema 1.0 or 1.1: {legacy}"
        )
    scopes = legacy_root / "scopes"
    if is_slim:
        if structure_layout == SEPARATED_METHODOLOGY_LAYOUT:
            applied_directories = tuple(APPLIED_LAYER_DIRECTORIES.values())
            missing_layers = [
                path
                for path in (
                    current_root / METHODOLOGY_ROOT,
                    *(current_root / directory for directory in applied_directories),
                )
                if not path.is_dir()
            ]
            competing_names = (
                *LAYERS,
                *LAYER_DIRECTORIES.values(),
                *RECURSIVE_LAYER_DIRECTORIES.values(),
                "00_project",
                "10_versions",
                "100_project",
                "150_versions",
                "project",
                "versions",
            )
        elif structure_layout == RECURSIVE_FRAMEWORK_LAYOUT:
            framework_directories = tuple(RECURSIVE_LAYER_DIRECTORIES.values())
            project_directories = (
                "00_project",
                *framework_directories,
                "10_versions",
            )
            missing_layers = [
                path
                for path in (
                    *(current_root / directory for directory in project_directories),
                    *(root / directory for directory in project_directories),
                )
                if not path.is_dir()
            ]
            competing_names = (
                *LAYERS,
                *LAYER_DIRECTORIES.values(),
                "project",
                "versions",
            )
        else:
            layer_directories = (
                tuple(LAYER_DIRECTORIES.values())
                if structure_layout == NUMBERED_LAYER_LAYOUT
                else LAYERS
            )
            missing_layers = [
                current_root / directory
                for directory in layer_directories
                if not (current_root / directory).is_dir()
            ]
            competing_names = (
                tuple(LAYER_DIRECTORIES.values())
                if structure_layout == LEGACY_SLIM_LAYOUT
                else LAYERS
            )
        if missing_layers:
            raise ValueError(
                "hidden DSET project is missing fixed roots: "
                + ", ".join(path.as_posix() for path in missing_layers)
            )
        competing_layers = [
            current_root / directory
            for directory in competing_names
            if (current_root / directory).exists()
        ]
        if competing_layers:
            raise ValueError(
                "hidden DSET project has competing roots: "
                + ", ".join(path.as_posix() for path in competing_layers)
            )
        if scopes.exists():
            raise ValueError(
                f"layout conflict: schema 1.3 and legacy dset/scopes coexist: {scopes}"
            )
        if legacy_root.exists():
            raise ValueError(
                "layout conflict: schema 1.3 .carmadio root and legacy dset root "
                f"coexist: {legacy_root}"
            )
        old_settings = root / "carmadio_settings.toml"
        if old_settings.exists():
            raise ValueError(
                "layout conflict: schema 1.3 combined settings and retired root "
                f"settings coexist: {old_settings}"
            )
    elif is_layered:
        actual_layers = {path.name for path in scopes.iterdir() if path.is_dir()}
        if actual_layers != set(LAYERS):
            raise ValueError(
                "layered DSET project must contain exactly the fixed layer roots: "
                f"{', '.join(LAYERS)}"
            )
        conflicts = [
            legacy_root / relative
            for relative in LEGACY_AUTHORITY_PATHS
            if (legacy_root / relative).exists()
        ]
        if conflicts:
            rendered = ", ".join(path.as_posix() for path in conflicts)
            raise ValueError(
                "layout conflict: legacy and layered DSET authorities coexist: "
                f"{rendered}"
            )
    elif legacy.is_file() and scopes.exists():
        raise ValueError(
            f"layout conflict: legacy manifest and layered DSET roots coexist: {scopes}"
        )
    return RepositoryLayout(
        root=root,
        schema_version=version,
        layered=is_layered,
        structure_layout=structure_layout,
    )


def has_manifest(root: Path) -> bool:
    """Handle manifest using the declared repository contract."""
    root = root.resolve()
    return (
        (root / CURRENT_DSET_ROOT / "carmadio_settings.toml").is_file()
        or _manifest_candidate(root / LEGACY_DSET_ROOT / "dset.yaml").is_file()
        or (
            _manifest_candidate(
                root / LEGACY_DSET_ROOT / "scopes" / "meta" / "dset.yaml"
            )
        ).is_file()
    )


def _schema_version(path: Path) -> str | None:
    """Handle version using the declared repository contract."""
    try:
        data = load(path)
    except (OSError, ValueError, StructuredDataError):
        return None
    raw = data.get("schema_version") if isinstance(data, dict) else None
    if isinstance(raw, str):
        return raw
    if isinstance(raw, (int, float)) and not isinstance(raw, bool):
        return f"{float(raw):.1f}"
    return None


def _structure_layout(path: Path) -> str | None:
    """Handle layout using the declared repository contract."""
    try:
        data = load(path)
    except (OSError, ValueError, StructuredDataError):
        return None
    structure = data.get("structure") if isinstance(data, dict) else None
    raw = structure.get("layout") if isinstance(structure, dict) else None
    return raw if isinstance(raw, str) else None


def _canonical_relative(relative: str | PurePath) -> Path:
    """Handle relative using the declared repository contract."""
    raw = relative.as_posix() if isinstance(relative, PurePath) else str(relative)
    if (
        not raw
        or raw.startswith("/")
        or "\\" in raw
        or (len(raw) >= 2 and raw[0].isalpha() and raw[1] == ":")
    ):
        raise ValueError(f"path is not canonical relative POSIX: {raw}")
    segments = raw.split("/")
    if any(segment in {"", ".", ".."} for segment in segments):
        raise ValueError(f"path is not canonical relative POSIX: {raw}")
    return Path(*segments)


def _manifest_candidate(requested: Path) -> Path:
    return RepositoryLayout.structured_file(requested.parent, requested.name)


def _registered_snapshot_after_cutover(snapshot: Path) -> bool:
    """Refuse legacy read fallback once a registered repository has cut over."""

    resolved = snapshot.resolve()
    for root in (resolved.parent, *resolved.parents):
        registry_candidates = (
            root / "00_project/artifact-types.toml",
            root / "dset/scopes/gov/artifact-types.toml",
            root / "dset/scopes/gov/artifact-types.yaml",
            root / "dset/artifact-types.toml",
            root / "dset/artifact-types.yaml",
        )
        registry = next(
            (candidate for candidate in registry_candidates if candidate.is_file()),
            None,
        )
        if registry is None:
            continue
        cutover = (
            (root / ".carmadio/carmadio_settings.toml").is_file()
            or (root / "dset/carmadio_settings.toml").is_file()
            or (root / "dset/scopes/meta/dset.toml").is_file()
            or (root / "dset/dset.toml").is_file()
        )
        if not cutover:
            return False
        try:
            data = load(registry)
        except (OSError, ValueError, StructuredDataError):
            return False
        entries = data.get("legacy_structured") if isinstance(data, dict) else None
        if not isinstance(entries, list):
            return False
        for entry in entries:
            raw = entry.get("path") if isinstance(entry, dict) else None
            if isinstance(raw, str) and (root / raw).resolve() == resolved:
                return True
        return False
    return False

"""Provide DSET legacy authority behavior."""

from __future__ import annotations

import hashlib
import re
from pathlib import Path
from typing import Any

from .carrier_transitions import decode_historical_envelope
from .diagnostics import Diagnostic
from .layout import discover_layout
from .structured_data import StructuredDataError, dump, load

# ID_PATTERN validates id pattern; this module owns the accepted syntax.
ID_PATTERN = re.compile(r"^[A-Z0-9]+(?:-[A-Z0-9]+)+$")


def build_legacy_authority_ledger(root: Path) -> dict[str, Any]:
    """Digest-seal legacy Decision authority without freezing shared carriers."""
    from .semantic_types import build_semantic_classification_index

    root = root.resolve()
    records: list[dict[str, Any]] = []
    for row in build_semantic_classification_index(root):
        origins = [
            str(origin)
            for origin in row["origins"]
            if origin == "legacy_decision" or str(origin).startswith("package:")
        ]
        if row["type"] != "decision" or not origins:
            continue
        fragments: list[dict[str, str]] = []
        for origin in origins:
            for relative in row["carriers"]:
                path = root / str(relative)
                fragment = _authority_fragment(root, path, str(row["id"]), origin)
                if fragment is not None:
                    fragments.append(fragment)
        if not fragments:
            raise ValueError(f"legacy authority has no sealable fragment: {row['id']}")
        records.append(
            {
                "semantic_id": row["id"],
                "type": row["type"],
                "subtype": row["subtype"],
                "fragments": sorted(
                    fragments,
                    key=lambda item: (item["path"], item["selector"]),
                ),
            }
        )
    return {
        "schema_version": "1.0",
        "records": sorted(records, key=lambda item: str(item["semantic_id"])),
    }


def write_legacy_authority_ledger(root: Path) -> Path:
    """Write legacy authority ledger using the declared repository contract."""
    root = root.resolve()
    path = legacy_authority_ledger_path(root)
    content = dump(build_legacy_authority_ledger(root), path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(content, encoding="utf-8")
    temporary.replace(path)
    return path


def validate_legacy_authority_ledger(root: Path) -> list[Diagnostic]:
    """Validate legacy authority ledger using the declared repository contract."""
    root = root.resolve()
    path = legacy_authority_ledger_path(root)
    if not path.is_file():
        try:
            expected = build_legacy_authority_ledger(root)
        except (OSError, ValueError) as error:
            return [Diagnostic("CARMADIO-E167", path, str(error))]
        if expected["records"]:
            if not (root / ".git").exists():
                return []
            return [Diagnostic("CARMADIO-E167", path, "legacy authority ledger is missing")]
        return []
    try:
        actual = load(path)
    except (OSError, UnicodeError, StructuredDataError) as error:
        return [Diagnostic("CARMADIO-E167", path, f"invalid legacy ledger: {error}")]
    if _recorded_fragment_errors(root, actual):
        return [
            Diagnostic(
                "CARMADIO-E167",
                path,
                "legacy Decision authority changed without native successors",
            )
        ]
    return []


def legacy_shared_package_paths(root: Path) -> tuple[Path, ...]:
    """Return package carriers trusted as selector-sealed historical input."""

    root = root.resolve()
    ledger = _load_recorded_ledger(root)
    records = ledger.get("records") if isinstance(ledger, dict) else None
    if not isinstance(records, list):
        return ()
    paths: set[Path] = set()
    for record in records:
        fragments = record.get("fragments") if isinstance(record, dict) else None
        if not isinstance(fragments, list):
            continue
        for fragment in fragments:
            if not isinstance(fragment, dict):
                continue
            raw_path = fragment.get("path")
            current_path = fragment.get("current_path")
            selector = fragment.get("selector")
            if not isinstance(raw_path, str) or selector == "whole-carrier":
                continue
            active = current_path if isinstance(current_path, str) else raw_path
            candidate = (root / active).resolve()
            if (
                _within(root, candidate)
                and (
                    candidate.name in {"package.yaml", "package.yml"}
                    or candidate.name.endswith("package.legacy.toml")
                )
                and candidate.is_file()
            ):
                paths.add(candidate)
    return tuple(sorted(paths))


def legacy_authority_ids(root: Path) -> set[str]:
    """Expose historical IDs without making them current package ownership."""

    identifiers: set[str] = set()
    for path in legacy_shared_package_paths(root):
        try:
            data = _load_fragment_carrier(path)
        except (OSError, UnicodeError, StructuredDataError):
            continue
        if not isinstance(data, dict):
            continue
        for value in data.values():
            if isinstance(value, list):
                identifiers.update(
                    item
                    for item in value
                    if isinstance(item, str) and ID_PATTERN.fullmatch(item)
                )
    ledger = _load_recorded_ledger(root)
    records = ledger.get("records") if isinstance(ledger, dict) else None
    if isinstance(records, list):
        identifiers.update(
            str(record["semantic_id"])
            for record in records
            if isinstance(record, dict) and isinstance(record.get("semantic_id"), str)
        )
    return identifiers


def legacy_authority_ledger_path(root: Path) -> Path:
    """Handle authority ledger path using the declared repository contract."""
    layout = discover_layout(root.resolve())
    return layout.structured_file(layout.project_state_root, "legacy-authority.toml")


def _load_recorded_ledger(root: Path) -> dict[str, Any] | None:
    """Load recorded ledger using the declared repository contract."""
    path = legacy_authority_ledger_path(root)
    if not path.is_file():
        return None
    try:
        data = load(path)
    except (OSError, UnicodeError, StructuredDataError):
        return None
    return data if isinstance(data, dict) else None


def _recorded_fragment_errors(root: Path, ledger: object) -> list[str]:
    """Handle fragment errors using the declared repository contract."""
    if not isinstance(ledger, dict) or str(ledger.get("schema_version")) != "1.0":
        return ["legacy authority ledger schema_version must be 1.0"]
    records = ledger.get("records")
    if not isinstance(records, list):
        return ["legacy authority ledger records must be a list"]
    errors: list[str] = []
    seen: set[str] = set()
    for record in records:
        if not isinstance(record, dict) or not isinstance(
            record.get("semantic_id"), str
        ):
            errors.append("legacy authority record is malformed")
            continue
        semantic_id = str(record["semantic_id"])
        if semantic_id in seen:
            errors.append(f"duplicate legacy authority ID: {semantic_id}")
        seen.add(semantic_id)
        fragments = record.get("fragments")
        if not isinstance(fragments, list) or not fragments:
            errors.append(f"legacy authority has no fragments: {semantic_id}")
            continue
        for fragment in fragments:
            error = _validate_recorded_fragment(root, semantic_id, fragment)
            if error is not None:
                errors.append(error)
    return errors


def _validate_recorded_fragment(
    root: Path, semantic_id: str, fragment: object
) -> str | None:
    """Validate one sealed legacy authority fragment."""
    if not isinstance(fragment, dict):
        return f"legacy authority fragment is malformed: {semantic_id}"
    identity = _fragment_identity(fragment)
    if identity is None:
        return f"legacy authority fragment seal is incomplete: {semantic_id}"
    raw_path, selector, expected = identity
    raw_current = fragment.get("current_path")
    current_digest = fragment.get("current_sha256")
    transition_id = fragment.get("transition_id")
    transitioned = isinstance(raw_current, str)
    if transitioned and not all(
        isinstance(item, str) for item in (current_digest, transition_id)
    ):
        return f"legacy authority current seal is incomplete: {semantic_id}"
    active = str(raw_current) if transitioned else raw_path
    path = (root / active).resolve()
    if not _within(root, path) or not path.is_file():
        return f"legacy authority carrier is missing: {raw_path}"
    if selector == "whole-carrier":
        payload = path.read_bytes()
        expected = current_digest if transitioned else expected
    else:
        error = _validate_selected_fragment(
            path, raw_path, selector, semantic_id, transitioned, current_digest
        )
        if error is not None:
            return error
        payload = f"{selector}\n".encode()
    if hashlib.sha256(payload).hexdigest() != expected:
        return f"legacy authority fragment digest changed: {semantic_id}"
    return None


def _fragment_identity(fragment: dict[str, Any]) -> tuple[str, str, str] | None:
    """Return the required path, selector, and digest strings."""
    values = (fragment.get("path"), fragment.get("selector"), fragment.get("sha256"))
    if not all(isinstance(item, str) for item in values):
        return None
    return str(values[0]), str(values[1]), str(values[2])


def _validate_selected_fragment(
    path: Path,
    raw_path: str,
    selector: str,
    semantic_id: str,
    transitioned: bool,
    current_digest: object,
) -> str | None:
    """Validate a list-field selector and optional relocation digest."""
    if transitioned and hashlib.sha256(path.read_bytes()).hexdigest() != current_digest:
        return f"legacy authority current carrier digest changed: {semantic_id}"
    field, separator, selected_id = selector.partition(":")
    if not separator or selected_id != semantic_id:
        return f"legacy authority selector is invalid: {semantic_id}"
    try:
        data = _load_fragment_carrier(path)
    except (OSError, UnicodeError, StructuredDataError):
        return f"legacy authority carrier is invalid: {raw_path}"
    values = data.get(field) if isinstance(data, dict) else None
    if not isinstance(values, list) or semantic_id not in values:
        return f"legacy authority selector is missing: {semantic_id}"
    return None


def _load_fragment_carrier(path: Path) -> Any:
    if path.name.endswith(".legacy.toml"):
        return decode_historical_envelope(path.read_text(encoding="utf-8"))
    return load(path)


def _within(root: Path, path: Path) -> bool:
    try:
        path.relative_to(root)
    except ValueError:
        return False
    return True


def _authority_fragment(
    root: Path, path: Path, semantic_id: str, origin: str
) -> dict[str, str] | None:
    """Handle fragment using the declared repository contract."""
    if origin == "legacy_decision":
        if path.suffix != ".md" or not path.is_file():
            return None
        payload = path.read_bytes()
        selector = "whole-carrier"
    else:
        field = origin.partition(":")[2]
        try:
            data = load(path)
        except (OSError, UnicodeError, StructuredDataError):
            return None
        values = data.get(field, []) if isinstance(data, dict) else []
        if semantic_id not in values:
            return None
        selector = f"{field}:{semantic_id}"
        payload = f"{selector}\n".encode()
    return {
        "path": path.relative_to(root).as_posix(),
        "selector": selector,
        "sha256": hashlib.sha256(payload).hexdigest(),
    }

"""Provide DSET lifecycle behavior."""

from __future__ import annotations

import copy
import hashlib
import json
from collections.abc import Mapping
from typing import Any

# IMPLEMENT_CRITERIA defines implement criteria; this module owns the default.
IMPLEMENT_CRITERIA = (
    "decisions_reconciled",
    "evergreen_current",
    "proof_plan_complete",
    "implementation_plan_complete",
    "implementation_authorized",
    "implementation_complete",
)
# IMPLEMENT_WORKFLOWS defines implement workflows; this module owns the default.
IMPLEMENT_WORKFLOWS = (
    "decisions",
    "compile",
    "plan-proof",
    "plan-implementation",
    "implement",
)
# IMPLEMENTATION_MODES defines implementation modes; this module owns the default.
IMPLEMENTATION_MODES = frozenset({"lazy", "strict"})
# WORKFLOW_PROGRESS defines workflow progress; this module owns the default.
WORKFLOW_PROGRESS = {
    "decisions": "decisions_reconciled",
    "compile": "evergreen_current",
    "plan-proof": "proof_plan_complete",
    "plan-implementation": "implementation_plan_complete",
    "implement": "implementation_complete",
}


class LifecycleClosureError(ValueError):
    """Represent lifecycle closure error failures."""

    pass


def initial_closure(
    public_entrypoint: str,
    mode_id: str | None,
    *,
    implementation_mode: str = "lazy",
) -> dict[str, Any]:
    """Handle closure using the declared repository contract."""
    if public_entrypoint != "ca-implement":
        return {
            "schema_version": "1.0",
            "requested_mode": mode_id,
            "status": "direct",
            "criteria": {},
            "next_workflow": mode_id,
            "reason_code": "CARMADIO-RUNTIME-DIRECT",
            "history": [],
            "visited_states": [],
        }
    if implementation_mode not in IMPLEMENTATION_MODES:
        raise LifecycleClosureError(
            "implementation preparation mode must be lazy or strict"
        )
    if implementation_mode == "strict":
        return _strict_closure()

    closure = {
        "schema_version": "1.0",
        "requested_mode": "implement",
        "implementation_mode": "lazy",
        "status": "active",
        "criteria": {
            "decisions_reconciled": False,
            "evergreen_current": None,
            "proof_plan_complete": None,
            "implementation_plan_complete": None,
            "implementation_authorized": None,
            "implementation_complete": False,
        },
        "next_workflow": "decisions",
        "reason_code": "CARMADIO-RUNTIME-DECISIONS-FIRST",
        "history": [],
        "visited_states": [],
    }
    closure["visited_states"] = [_state_fingerprint(closure)]
    return closure


def advance_closure(
    raw: Mapping[str, Any],
    *,
    workflow_id: str | None = None,
    child_status: str = "succeeded",
    observations: Mapping[str, bool | None] | None = None,
) -> dict[str, Any]:
    """Handle closure using the declared repository contract."""
    closure = _validated_copy(raw)
    if closure["requested_mode"] != "implement":
        raise LifecycleClosureError("direct workflow has no prerequisite closure")
    if closure["implementation_mode"] == "strict":
        return _advance_strict_closure(
            closure,
            workflow_id=workflow_id,
            child_status=child_status,
            observations=observations,
        )
    if closure["status"] in {"completed", "stopped"}:
        raise LifecycleClosureError("closure is terminal")
    expected = closure.get("next_workflow")
    if workflow_id is not None and workflow_id != expected:
        raise LifecycleClosureError(
            f"workflow mismatch: expected {expected}, received {workflow_id}"
        )
    if workflow_id is None and not observations:
        raise LifecycleClosureError("an observation or completed workflow is required")
    if child_status not in {"succeeded", "failed", "stopped", "ambiguous"}:
        raise LifecycleClosureError("invalid child status")
    if workflow_id is not None and child_status != "succeeded":
        closure["status"] = "stopped"
        closure["next_workflow"] = None
        closure["reason_code"] = {
            "failed": "CARMADIO-RUNTIME-CHILD-FAILED",
            "stopped": "CARMADIO-RUNTIME-CHILD-STOPPED",
            "ambiguous": "CARMADIO-RUNTIME-AMBIGUOUS",
        }[child_status]
        closure["history"].append(
            {"workflow_id": workflow_id, "status": child_status, "progress": []}
        )
        return closure

    before = copy.deepcopy(closure["criteria"])
    if observations:
        for key, value in observations.items():
            if key not in IMPLEMENT_CRITERIA:
                raise LifecycleClosureError(f"unknown entry criterion: {key}")
            if value not in {True, False, None}:
                raise LifecycleClosureError(f"invalid criterion value: {key}")
            closure["criteria"][key] = value
    if workflow_id is not None:
        if workflow_id not in IMPLEMENT_WORKFLOWS:
            raise LifecycleClosureError(f"workflow is outside closure: {workflow_id}")
        closure["criteria"][WORKFLOW_PROGRESS[workflow_id]] = True

    progress = [
        key
        for key in IMPLEMENT_CRITERIA
        if before.get(key) != closure["criteria"].get(key)
    ]
    if not progress:
        closure["status"] = "stopped"
        closure["next_workflow"] = None
        closure["reason_code"] = "CARMADIO-RUNTIME-NO-PROGRESS"
    else:
        _select_next(closure)
    if workflow_id is not None:
        closure["history"].append(
            {"workflow_id": workflow_id, "status": child_status, "progress": progress}
        )

    fingerprint = _state_fingerprint(closure)
    if fingerprint in closure["visited_states"]:
        closure["status"] = "stopped"
        closure["next_workflow"] = None
        closure["reason_code"] = "CARMADIO-RUNTIME-REPEATED-STATE"
    else:
        closure["visited_states"].append(fingerprint)
    return closure


def _select_next(closure: dict[str, Any]) -> None:
    """Select next using the declared repository contract."""
    criteria = closure["criteria"]
    if criteria["decisions_reconciled"] is not True:
        _set_next(closure, "active", "decisions", "CARMADIO-RUNTIME-DECISIONS-FIRST")
    elif criteria["evergreen_current"] is None:
        _set_next(closure, "blocked", None, "CARMADIO-RUNTIME-CRITERIA-UNKNOWN")
    elif criteria["evergreen_current"] is False:
        _set_next(closure, "active", "compile", "CARMADIO-RUNTIME-COMPILE")
    elif criteria["proof_plan_complete"] is None:
        _set_next(closure, "blocked", None, "CARMADIO-RUNTIME-CRITERIA-UNKNOWN")
    elif criteria["proof_plan_complete"] is False:
        _set_next(closure, "active", "plan-proof", "CARMADIO-RUNTIME-PROOF-PLAN")
    elif criteria["implementation_plan_complete"] is None:
        _set_next(closure, "blocked", None, "CARMADIO-RUNTIME-CRITERIA-UNKNOWN")
    elif criteria["implementation_plan_complete"] is False:
        _set_next(
            closure,
            "active",
            "plan-implementation",
            "CARMADIO-RUNTIME-IMPLEMENTATION-PLAN",
        )
    elif criteria["implementation_authorized"] is not True:
        _set_next(
            closure,
            "authorization-required",
            None,
            "CARMADIO-RUNTIME-AUTHORIZATION-REQUIRED",
        )
    elif criteria["implementation_complete"] is not True:
        _set_next(closure, "ready", "implement", "CARMADIO-RUNTIME-IMPLEMENT")
    else:
        _set_next(closure, "completed", None, "CARMADIO-RUNTIME-COMPLETE")


def _strict_closure() -> dict[str, Any]:
    """Return the implementation-only boundary without a prerequisite chain.

    Readiness is deliberately determined by the selected local implementation
    workflow.  A caller can record a failed authoritative check as an
    observation, but this runtime never substitutes decisions or planning
    work for that stop.
    """

    closure = {
        "schema_version": "1.0",
        "requested_mode": "implement",
        "implementation_mode": "strict",
        "status": "ready",
        "criteria": {
            "decisions_reconciled": None,
            "evergreen_current": None,
            "proof_plan_complete": None,
            "implementation_plan_complete": None,
            "implementation_authorized": None,
            "implementation_complete": False,
        },
        "next_workflow": "implement",
        "reason_code": "CARMADIO-RUNTIME-STRICT-IMPLEMENT",
        "history": [],
        "visited_states": [],
    }
    closure["visited_states"] = [_state_fingerprint(closure)]
    return closure


def _advance_strict_closure(
    closure: dict[str, Any],
    *,
    workflow_id: str | None,
    child_status: str,
    observations: Mapping[str, bool | None] | None,
) -> dict[str, Any]:
    """Advance only the direct implementation or record an exact stop.

    Strict mode accepts no prerequisite child workflow.  The governing
    implementation workflow reports any missing/ambiguous accepted input as
    an observation, preserving its detail in the caller's handoff while this
    runtime provides a stable, machine-readable stop class.
    """

    if closure["status"] in {"completed", "stopped"}:
        raise LifecycleClosureError("closure is terminal")
    if child_status not in {"succeeded", "failed", "stopped", "ambiguous"}:
        raise LifecycleClosureError("invalid child status")
    if workflow_id not in {None, "implement"}:
        raise LifecycleClosureError(
            f"strict implementation accepts only implement, received {workflow_id}"
        )
    if workflow_id == "implement" and child_status != "succeeded":
        closure["status"] = "stopped"
        closure["next_workflow"] = None
        closure["reason_code"] = {
            "failed": "CARMADIO-RUNTIME-CHILD-FAILED",
            "stopped": "CARMADIO-RUNTIME-CHILD-STOPPED",
            "ambiguous": "CARMADIO-RUNTIME-AMBIGUOUS",
        }[child_status]
        closure["history"].append(
            {"workflow_id": workflow_id, "status": child_status, "progress": []}
        )
        return closure

    before = copy.deepcopy(closure["criteria"])
    if observations:
        for key, value in observations.items():
            if key not in IMPLEMENT_CRITERIA:
                raise LifecycleClosureError(f"unknown entry criterion: {key}")
            if value not in {True, False, None}:
                raise LifecycleClosureError(f"invalid criterion value: {key}")
            closure["criteria"][key] = value

    if _strict_inputs_insufficient(closure["criteria"]):
        _set_next(
            closure,
            "stopped",
            None,
            "CARMADIO-RUNTIME-STRICT-INPUTS-INSUFFICIENT",
        )
    elif closure["criteria"]["implementation_authorized"] is False:
        _set_next(
            closure,
            "authorization-required",
            None,
            "CARMADIO-RUNTIME-AUTHORIZATION-REQUIRED",
        )
    elif workflow_id == "implement":
        closure["criteria"]["implementation_complete"] = True
        _set_next(closure, "completed", None, "CARMADIO-RUNTIME-COMPLETE")
    elif observations:
        _set_next(
            closure,
            "ready",
            "implement",
            "CARMADIO-RUNTIME-STRICT-IMPLEMENT",
        )
    else:
        raise LifecycleClosureError("an observation or completed workflow is required")

    progress = [
        key
        for key in IMPLEMENT_CRITERIA
        if before.get(key) != closure["criteria"].get(key)
    ]
    if workflow_id is not None:
        closure["history"].append(
            {"workflow_id": workflow_id, "status": child_status, "progress": progress}
        )
    fingerprint = _state_fingerprint(closure)
    if closure["status"] != "stopped" and fingerprint in closure["visited_states"]:
        closure["status"] = "stopped"
        closure["next_workflow"] = None
        closure["reason_code"] = "CARMADIO-RUNTIME-REPEATED-STATE"
    elif fingerprint not in closure["visited_states"]:
        closure["visited_states"].append(fingerprint)
    return closure


def _strict_inputs_insufficient(criteria: Mapping[str, object]) -> bool:
    """Handle inputs insufficient using the declared repository contract."""
    return any(
        criteria.get(name) is False
        for name in (
            "decisions_reconciled",
            "evergreen_current",
            "proof_plan_complete",
            "implementation_plan_complete",
        )
    )


def _set_next(
    closure: dict[str, Any], status: str, workflow: str | None, reason: str
) -> None:
    closure["status"] = status
    closure["next_workflow"] = workflow
    closure["reason_code"] = reason


def _validated_copy(raw: Mapping[str, Any]) -> dict[str, Any]:
    """Handle copy using the declared repository contract."""
    closure = copy.deepcopy(dict(raw))
    if closure.get("schema_version") != "1.0":
        raise LifecycleClosureError("unsupported closure schema")
    criteria = closure.get("criteria")
    history = closure.get("history")
    visited = closure.get("visited_states")
    if not isinstance(criteria, dict):
        raise LifecycleClosureError("closure criteria are invalid")
    if not isinstance(history, list) or not isinstance(visited, list):
        raise LifecycleClosureError("closure history is invalid")
    implementation_mode = closure.setdefault("implementation_mode", "lazy")
    if implementation_mode not in IMPLEMENTATION_MODES:
        raise LifecycleClosureError("invalid implementation preparation mode")
    return closure


def _state_fingerprint(closure: Mapping[str, Any]) -> str:
    """Handle fingerprint using the declared repository contract."""
    payload = {
        "requested_mode": closure["requested_mode"],
        "implementation_mode": closure.get("implementation_mode", "lazy"),
        "criteria": closure["criteria"],
        "status": closure["status"],
        "next_workflow": closure["next_workflow"],
        "reason_code": closure["reason_code"],
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return f"state:{hashlib.sha256(encoded).hexdigest()}"

"""Provide DSET lineage behavior."""

from __future__ import annotations

import re
import subprocess
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .diagnostics import Diagnostic
from .frontmatter import FrontmatterError
from .frontmatter import metadata as frontmatter_metadata
from .identity import iter_control_files, logical_part
from .layout import ID_TOKEN_LAYERS, LAYERS, discover_layout
from .legacy_authority import legacy_authority_ids
from .semantic_types import SEMANTIC_SUBTYPES, build_semantic_classification_index
from .structured_data import StructuredDataError, load

# ID_PATTERN validates id pattern; this module owns the accepted syntax.
ID_PATTERN = re.compile(r"^[A-Z0-9]+(?:-[A-Z0-9]+)+$")
# SESSION_PATTERN validates session pattern; this module owns the accepted syntax.
SESSION_PATTERN = re.compile(r"^[a-z][a-z0-9_-]*:[A-Za-z0-9._:-]+$")
# ATOM_PATTERN validates atom pattern; this module owns the accepted syntax.
ATOM_PATTERN = re.compile(r"-ATOMIC-RECORD-([0-9]+)$")
# RELATION_TYPES defines relation types; this module owns the default.
RELATION_TYPES = frozenset(
    {
        "child_of",
        "analysis_of",
        "projection_of",
        "implementation_of",
        "check_of",
        "evidence_for",
        "resolution_of",
        "override_of",
        "replacement_of",
        "recurrence_of",
        "relates_to",
    }
)
# ACYCLIC_RELATION_TYPES defines acyclic relation types; this module owns the default.
ACYCLIC_RELATION_TYPES = frozenset(
    {"child_of", "override_of", "replacement_of", "recurrence_of"}
)
# PROJECTION_SOURCE_TYPES defines projection source types; this module owns the default.
PROJECTION_SOURCE_TYPES = frozenset(
    {"specification", "procedure", "plan", "derived_view", "navigation"}
)
# SEMANTIC_TYPES defines semantic types; this module owns the default.
SEMANTIC_TYPES = frozenset(SEMANTIC_SUBTYPES)
# SCOPE_KINDS defines scope kinds; this module owns the default.
SCOPE_KINDS = frozenset({"project", "layer", "feature_group", "feature"})
# REVERSE_FIELDS defines reverse fields; this module owns the default.
REVERSE_FIELDS = frozenset(
    {
        "parent_to",
        "analysis_by",
        "projection_by",
        "implemented_by",
        "checked_by",
        "evidence_from",
        "resolved_by",
        "overridden_by",
        "replaced_by",
        "recurs_as",
    }
)
# IGNORED_PARTS defines ignored parts; this module owns the default.
IGNORED_PARTS = frozenset(
    {
        ".git",
        ".mypy_cache",
        ".pytest_cache",
        ".ruff_cache",
        ".uv-cache",
        ".venv",
        "__pycache__",
        "dist",
        "templates",
    }
)


@dataclass(frozen=True)
class ProjectionRange:
    """Represent projection range behavior and state."""

    semantic_type: str
    subtype: str | None
    layer: str | None
    scope_kind: str
    scope_id: str
    through: str

    def as_dict(self) -> dict[str, Any]:
        """Handle dict using the declared repository contract."""
        data: dict[str, Any] = {
            "semantic_type": self.semantic_type,
            "scope": {"kind": self.scope_kind, "id": self.scope_id},
            "through": self.through,
        }
        if self.subtype is not None:
            data["subtype"] = self.subtype
        if self.layer is not None:
            data["layer"] = self.layer
        return data


@dataclass(frozen=True)
class ArtifactRelation:
    """Represent artifact relation behavior and state."""

    type: str
    target: str | None
    range: ProjectionRange | None
    origin: str

    def as_dict(self) -> dict[str, Any]:
        """Handle dict using the declared repository contract."""
        data: dict[str, Any] = {"type": self.type, "origin": self.origin}
        if self.target is not None:
            data["target"] = self.target
        if self.range is not None:
            data["range"] = self.range.as_dict()
        return data


@dataclass(frozen=True)
class RelationNode:
    """Represent relation node behavior and state."""

    id: str
    artifact_id: str
    path: str
    artifact_type: str | None
    semantic_type: str | None
    subtype: str | None
    layer: str | None
    scope_kind: str | None
    scope_id: str | None
    relations: tuple[ArtifactRelation, ...]

    @property
    def child_of(self) -> tuple[str, ...]:
        """Handle of using the declared repository contract."""
        return tuple(
            relation.target
            for relation in self.relations
            if relation.type == "child_of" and relation.target is not None
        )


@dataclass(frozen=True)
class _RawNode:
    """Represent raw node behavior and state."""

    node: RelationNode
    path: Path


def parse_authored_relations(
    path: Path,
    metadata: dict[str, Any],
    diagnostics: list[Diagnostic],
) -> tuple[ArtifactRelation, ...]:
    """Parse canonical relations and sealed legacy child_of compatibility."""
    _reject_reverse_fields(path, metadata, diagnostics)
    raw_relations = metadata.get("relations")
    raw_legacy = metadata.get("child_of")
    if raw_relations is not None and raw_legacy is not None:
        diagnostics.append(
            _diag(path, "relations and legacy child_of cannot be authored together")
        )
        return ()
    if raw_legacy is not None:
        return _parse_legacy_child_of(path, raw_legacy, diagnostics)
    if raw_relations is None:
        return ()
    if not isinstance(raw_relations, list) or not raw_relations:
        diagnostics.append(_diag(path, "relations must be a non-empty list"))
        return ()
    parsed = [
        relation
        for item in raw_relations
        if (relation := _parse_relation(path, item, diagnostics)) is not None
    ]
    _validate_local_uniqueness(path, parsed, diagnostics)
    return tuple(parsed)


def collect_artifact_relations(
    root: Path,
) -> tuple[dict[str, RelationNode], list[Diagnostic]]:
    """Collect canonical forward relations from governed Markdown artifacts."""
    root = root.resolve()
    raw_nodes, aliases, diagnostics = _collect_raw_nodes(root)
    inactive = _inactive_semantic_ids(root)
    known = _known_relation_ids(root) | set(aliases)
    nodes = _resolve_nodes(root, raw_nodes, aliases, known, inactive, diagnostics)
    diagnostics.extend(_cycle_diagnostics(root, nodes, inactive))
    diagnostics.extend(_range_diagnostics(root, nodes, inactive))
    diagnostics.extend(_replacement_diagnostics(root, nodes, inactive))
    diagnostics.extend(_recurrence_diagnostics(root, nodes, inactive))
    diagnostics.extend(_source_diagnostics(root, nodes))
    return nodes, sorted(set(diagnostics))


def build_relation_index(root: Path) -> list[dict[str, Any]]:
    """Build relation index using the declared repository contract."""
    nodes, diagnostics = collect_artifact_relations(root)
    if diagnostics:
        raise ValueError(diagnostics[0].message)
    rows: list[dict[str, Any]] = []
    for node in nodes.values():
        for relation in node.relations:
            row = {
                "source": node.id,
                "source_kind": "artifact",
                "source_artifact_id": node.artifact_id,
                "source_carrier": Path(node.path).name,
                **relation.as_dict(),
                "llm_session_ids": [],
            }
            rows.append(row)
    rows.extend(build_commit_implementation_relations(root))
    return sorted(rows, key=_relation_sort_key)


def build_commit_implementation_relations(root: Path) -> list[dict[str, Any]]:
    """Derive typed implementation relations from immutable Git trailers."""
    try:
        completed = subprocess.run(
            [
                "git",
                "log",
                "--no-merges",
                "--format=%H%x1f%B%x1e",
                "--",
                ".",
                ":(exclude)**/generated/**",
            ],
            cwd=root,
            check=True,
            capture_output=True,
            text=True,
        )
    except (OSError, subprocess.CalledProcessError):
        return []
    rows: list[dict[str, Any]] = []
    for record in completed.stdout.split("\x1e"):
        rows.extend(_commit_relations(record))
    return sorted(rows, key=_relation_sort_key)


def validate_artifact_relations(root: Path) -> list[Diagnostic]:
    """Validate artifact relations using the declared repository contract."""
    _, diagnostics = collect_artifact_relations(root)
    return diagnostics


def validate_artifact_lineage(root: Path) -> list[Diagnostic]:
    """Compatibility entrypoint for the renamed typed-relation validator."""
    return validate_artifact_relations(root)


def _collect_raw_nodes(
    root: Path,
) -> tuple[list[_RawNode], dict[str, str], list[Diagnostic]]:
    """Collect raw nodes using the declared repository contract."""
    raw_nodes: list[_RawNode] = []
    aliases: dict[str, str] = {}
    alias_paths: dict[str, Path] = {}
    diagnostics: list[Diagnostic] = []
    layout = discover_layout(root)
    paths = (
        iter_control_files(root, "*.md")
        if layout.separated
        else sorted(root.rglob("*.md"))
    )
    for path in paths:
        relative = path.relative_to(root)
        if any(logical_part(part) in IGNORED_PARTS for part in relative.parts):
            continue
        metadata = _frontmatter(path)
        if metadata is None:
            continue
        relations = parse_authored_relations(path, metadata, diagnostics)
        artifact_id = metadata.get("artifact_id")
        if artifact_id is None:
            if relations or any(field in metadata for field in REVERSE_FIELDS):
                diagnostics.append(
                    _diag(path, "artifact relations require artifact_id")
                )
            continue
        if not isinstance(artifact_id, str) or not ID_PATTERN.fullmatch(artifact_id):
            continue
        node = _node_from_metadata(root, path, artifact_id, metadata, relations)
        raw_nodes.append(_RawNode(node, path))
        _register_aliases(node, path, aliases, alias_paths, diagnostics)
    return raw_nodes, aliases, diagnostics


def _node_from_metadata(
    root: Path,
    path: Path,
    artifact_id: str,
    metadata: dict[str, Any],
    relations: tuple[ArtifactRelation, ...],
) -> RelationNode:
    """Handle from metadata using the declared repository contract."""
    semantic_id = metadata.get("semantic_id")
    node_id = artifact_id
    if (
        metadata.get("artifact_type") == "atomic_record"
        and isinstance(semantic_id, str)
        and ID_PATTERN.fullmatch(semantic_id)
    ):
        node_id = semantic_id
    scope = metadata.get("scope")
    scope_kind = scope.get("kind") if isinstance(scope, dict) else None
    scope_id = scope.get("id") if isinstance(scope, dict) else None
    semantic_type = metadata.get("type")
    subtype = metadata.get("subtype")
    return RelationNode(
        id=node_id,
        artifact_id=artifact_id,
        path=path.relative_to(root).as_posix(),
        artifact_type=_optional_text(metadata.get("artifact_type")),
        semantic_type=_optional_text(semantic_type),
        subtype=_optional_text(subtype),
        layer=_layer_from_id(node_id),
        scope_kind=_optional_text(scope_kind),
        scope_id=_optional_text(scope_id),
        relations=relations,
    )


def _register_aliases(
    node: RelationNode,
    path: Path,
    aliases: dict[str, str],
    alias_paths: dict[str, Path],
    diagnostics: list[Diagnostic],
) -> None:
    """Handle aliases using the declared repository contract."""
    for alias in {node.artifact_id, node.id}:
        previous = aliases.get(alias)
        if previous is not None and alias_paths[alias] != path:
            diagnostics.append(_diag(path, f"duplicate relation ID: {alias}"))
            continue
        aliases[alias] = node.id
        alias_paths[alias] = path


def _resolve_nodes(
    root: Path,
    raw_nodes: list[_RawNode],
    aliases: dict[str, str],
    known: set[str],
    inactive: set[str],
    diagnostics: list[Diagnostic],
) -> dict[str, RelationNode]:
    """Resolve nodes using the declared repository contract."""
    nodes: dict[str, RelationNode] = {}
    for raw in raw_nodes:
        resolved = tuple(
            _resolve_relation(raw, item, aliases, known, inactive, diagnostics)
            for item in raw.node.relations
        )
        nodes[raw.node.id] = RelationNode(
            **{**raw.node.__dict__, "relations": resolved},
        )
    _validate_resolved_uniqueness(root, nodes, diagnostics)
    return nodes


def _resolve_relation(
    raw: _RawNode,
    relation: ArtifactRelation,
    aliases: dict[str, str],
    known: set[str],
    inactive: set[str],
    diagnostics: list[Diagnostic],
) -> ArtifactRelation:
    """Resolve relation using the declared repository contract."""
    if relation.target is None:
        return relation
    canonical = aliases.get(relation.target, relation.target)
    unresolved = relation.target not in known
    legacy_inactive = raw.node.id in inactive and relation.origin == "legacy_child_of"
    if unresolved and not legacy_inactive:
        diagnostics.append(
            _diag(raw.path, f"unresolved {relation.type} target: {relation.target}")
        )
    if canonical == raw.node.id and not legacy_inactive:
        diagnostics.append(
            _diag(raw.path, f"artifact cannot be {relation.type} itself: {canonical}")
        )
    return ArtifactRelation(relation.type, canonical, relation.range, relation.origin)


def _parse_relation(
    path: Path,
    value: object,
    diagnostics: list[Diagnostic],
) -> ArtifactRelation | None:
    """Parse relation using the declared repository contract."""
    if not isinstance(value, dict):
        diagnostics.append(_diag(path, "every relation must be a mapping"))
        return None
    relation_type = value.get("type")
    if relation_type not in RELATION_TYPES:
        diagnostics.append(_diag(path, f"unknown relation type: {relation_type}"))
        return None
    allowed = {"type", "target", "range"}
    if set(value) - allowed:
        diagnostics.append(_diag(path, "relation has unknown or inverse fields"))
        return None
    has_target = "target" in value
    has_range = "range" in value
    if has_target == has_range:
        diagnostics.append(_diag(path, "relation requires exactly one target or range"))
        return None
    if has_range:
        if relation_type != "projection_of":
            diagnostics.append(_diag(path, "only projection_of accepts a range"))
            return None
        parsed_range = _parse_range(path, value["range"], diagnostics)
        return (
            ArtifactRelation(str(relation_type), None, parsed_range, "authored")
            if parsed_range is not None
            else None
        )
    target = value.get("target")
    if not isinstance(target, str) or not ID_PATTERN.fullmatch(target):
        diagnostics.append(_diag(path, f"invalid {relation_type} target: {target}"))
        return None
    return ArtifactRelation(str(relation_type), target, None, "authored")


def _parse_range(
    path: Path,
    value: object,
    diagnostics: list[Diagnostic],
) -> ProjectionRange | None:
    """Parse range using the declared repository contract."""
    if not isinstance(value, dict):
        diagnostics.append(_diag(path, "projection range must be a mapping"))
        return None
    allowed = {"semantic_type", "subtype", "layer", "scope", "through"}
    if set(value) - allowed:
        diagnostics.append(_diag(path, "projection range has unknown fields"))
        return None
    semantic_type = value.get("semantic_type")
    subtype = value.get("subtype")
    layer = value.get("layer")
    scope = value.get("scope")
    through = value.get("through")
    valid = semantic_type in SEMANTIC_TYPES
    valid = valid and _valid_range_subtype(semantic_type, subtype)
    valid = valid and (layer is None or layer in LAYERS)
    if not isinstance(scope, dict):
        diagnostics.append(_diag(path, "invalid projection range selector"))
        return None
    valid = valid and set(scope) == {"kind", "id"}
    valid = valid and scope.get("kind") in SCOPE_KINDS
    scope_id = scope.get("id")
    valid = valid and isinstance(scope_id, str) and bool(scope_id)
    valid = valid and isinstance(through, str) and bool(ATOM_PATTERN.search(through))
    if not valid or not isinstance(scope_id, str):
        diagnostics.append(_diag(path, "invalid projection range selector"))
        return None
    return ProjectionRange(
        semantic_type=str(semantic_type),
        subtype=str(subtype) if subtype is not None else None,
        layer=str(layer) if layer is not None else None,
        scope_kind=str(scope["kind"]),
        scope_id=scope_id,
        through=str(through),
    )


def _parse_legacy_child_of(
    path: Path,
    value: object,
    diagnostics: list[Diagnostic],
) -> tuple[ArtifactRelation, ...]:
    """Parse legacy child of using the declared repository contract."""
    if not isinstance(value, list) or not value:
        diagnostics.append(
            _diag(path, "legacy child_of must be a non-empty list of canonical IDs")
        )
        return ()
    targets: list[str] = []
    for target in value:
        if not isinstance(target, str) or not ID_PATTERN.fullmatch(target):
            diagnostics.append(_diag(path, f"invalid legacy child_of target: {target}"))
            continue
        targets.append(target)
    if len(set(targets)) != len(targets):
        diagnostics.append(_diag(path, "legacy child_of targets must be unique"))
    return tuple(
        ArtifactRelation("child_of", target, None, "legacy_child_of")
        for target in dict.fromkeys(targets)
    )


def _validate_local_uniqueness(
    path: Path,
    relations: list[ArtifactRelation],
    diagnostics: list[Diagnostic],
) -> None:
    """Validate local uniqueness using the declared repository contract."""
    keys = [_local_relation_key(item) for item in relations]
    if len(set(keys)) != len(keys):
        diagnostics.append(_diag(path, "relations must be unique"))
    targets = [item.target for item in relations if item.target is not None]
    if len(set(targets)) != len(targets):
        diagnostics.append(
            _diag(path, "one source-target pair must have one primary relation")
        )


def _validate_resolved_uniqueness(
    root: Path,
    nodes: dict[str, RelationNode],
    diagnostics: list[Diagnostic],
) -> None:
    """Validate resolved uniqueness using the declared repository contract."""
    for node in nodes.values():
        targets = [item.target for item in node.relations if item.target is not None]
        if len(set(targets)) != len(targets):
            diagnostics.append(
                _diag(
                    root / node.path,
                    "aliased source-target pair has more than one primary relation",
                )
            )


def _range_diagnostics(
    root: Path,
    nodes: dict[str, RelationNode],
    inactive: set[str],
) -> list[Diagnostic]:
    """Handle diagnostics using the declared repository contract."""
    diagnostics: list[Diagnostic] = []
    by_artifact = {node.artifact_id: node for node in nodes.values()}
    for node in nodes.values():
        for relation in node.relations:
            selector = relation.range
            if selector is None:
                continue
            through = by_artifact.get(selector.through)
            if through is None or through.artifact_type != "atomic_record":
                diagnostics.append(
                    _diag(
                        root / node.path,
                        "projection through must name an atom carrier",
                    )
                )
                continue
            candidates = [
                item
                for item in nodes.values()
                if _range_matches(item, selector) and item.id not in inactive
            ]
            if through not in candidates:
                diagnostics.append(
                    _diag(root / node.path, "projection frontier is outside its range")
                )
                continue
            latest = max(candidates, key=lambda item: _atom_sequence(item.artifact_id))
            if latest.artifact_id != selector.through:
                diagnostics.append(
                    _diag(
                        root / node.path,
                        f"stale projection frontier: latest is {latest.artifact_id}",
                    )
                )
    return diagnostics


def _range_matches(node: RelationNode, selector: ProjectionRange) -> bool:
    """Handle matches using the declared repository contract."""
    if node.artifact_type != "atomic_record":
        return False
    if node.semantic_type != selector.semantic_type:
        return False
    if selector.subtype is not None and (node.subtype or "none") != selector.subtype:
        return False
    if selector.layer is not None and node.layer != selector.layer:
        return False
    return node.scope_kind == selector.scope_kind and node.scope_id == selector.scope_id


def _replacement_diagnostics(
    root: Path,
    nodes: dict[str, RelationNode],
    inactive: set[str],
) -> list[Diagnostic]:
    """Require one replacement successor and an archived predecessor."""
    diagnostics: list[Diagnostic] = []
    successors: dict[str, str] = {}
    for node in nodes.values():
        for relation in node.relations:
            if relation.type != "replacement_of" or relation.target is None:
                continue
            previous = successors.get(relation.target)
            if previous is not None and previous != node.id:
                diagnostics.append(
                    _diag(
                        root / node.path,
                        f"replacement target already has successor: {previous}",
                    )
                )
            successors[relation.target] = node.id
            if relation.target not in inactive:
                diagnostics.append(
                    _diag(
                        root / node.path,
                        "replacement_of target must be archived",
                    )
                )
    return diagnostics


def _recurrence_diagnostics(
    root: Path,
    nodes: dict[str, RelationNode],
    inactive: set[str],
) -> list[Diagnostic]:
    """Validate new occurrences without reactivating archived atoms."""
    diagnostics: list[Diagnostic] = []
    for node in nodes.values():
        for relation in node.relations:
            if relation.type != "recurrence_of" or relation.target is None:
                continue
            target = nodes.get(relation.target)
            if node.artifact_type != "atomic_record" or node.semantic_type not in {
                "problem",
                "question",
            }:
                diagnostics.append(
                    _diag(
                        root / node.path,
                        "recurrence_of must originate from a Question or Problem atom",
                    )
                )
                continue
            if target is None:
                continue
            if target.semantic_type != node.semantic_type:
                diagnostics.append(
                    _diag(
                        root / node.path,
                        "recurrence_of requires the same semantic Type",
                    )
                )
            if relation.target not in inactive:
                diagnostics.append(
                    _diag(
                        root / node.path,
                        "recurrence_of target must be archived",
                    )
                )
    return diagnostics


def _source_diagnostics(
    root: Path,
    nodes: dict[str, RelationNode],
) -> list[Diagnostic]:
    """Handle diagnostics using the declared repository contract."""
    diagnostics: list[Diagnostic] = []
    for node in nodes.values():
        for relation in node.relations:
            if relation.origin == "legacy_child_of":
                continue
            message = _source_error(node, relation.type)
            if message is not None:
                diagnostics.append(_diag(root / node.path, message))
    return diagnostics


def _source_error(node: RelationNode, relation_type: str) -> str | None:
    """Handle error using the declared repository contract."""
    if relation_type == "analysis_of" and node.artifact_type != "analysis_report":
        return "analysis_of must originate from an Analysis Report"
    if (
        relation_type == "projection_of"
        and node.artifact_type not in PROJECTION_SOURCE_TYPES
    ):
        return "projection_of must originate from an evergreen artifact"
    if relation_type == "check_of" and not (
        node.semantic_type == "qa" and node.subtype in {"test_case", "evaluation_case"}
    ):
        return "check_of must originate from a Test Case or Evaluation Case atom"
    if relation_type == "evidence_for" and node.artifact_type != "evidence_record":
        return "evidence_for must originate from an Evidence Record"
    if relation_type == "override_of" and node.semantic_type != "decision":
        return "override_of must originate from Decision authority"
    if relation_type == "replacement_of" and node.artifact_type != "atomic_record":
        return "replacement_of must originate from an atomic artifact"
    if relation_type == "recurrence_of" and not (
        node.artifact_type == "atomic_record"
        and node.semantic_type in {"problem", "question"}
    ):
        return "recurrence_of must originate from a Question or Problem atom"
    if relation_type == "implementation_of" and node.artifact_type != "implementation":
        return "implementation_of must originate from implementation or a commit"
    return None


def _cycle_diagnostics(
    root: Path,
    nodes: dict[str, RelationNode],
    inactive: set[str],
) -> list[Diagnostic]:
    """Handle diagnostics using the declared repository contract."""
    graph: dict[str, list[str]] = {}
    for identifier, node in nodes.items():
        graph[identifier] = [
            str(item.target)
            for item in node.relations
            if item.type in ACYCLIC_RELATION_TYPES and item.target in nodes
        ]
    diagnostics: list[Diagnostic] = []
    state: dict[str, int] = {}
    for identifier in sorted(set(nodes) - inactive):
        _visit_cycle(identifier, [], graph, nodes, inactive, state, diagnostics, root)
    return diagnostics


def _visit_cycle(
    identifier: str,
    stack: list[str],
    graph: dict[str, list[str]],
    nodes: dict[str, RelationNode],
    inactive: set[str],
    state: dict[str, int],
    diagnostics: list[Diagnostic],
    root: Path,
) -> None:
    """Handle cycle using the declared repository contract."""
    if state.get(identifier) == 2:
        return
    if state.get(identifier) == 1:
        start = stack.index(identifier)
        cycle = [*stack[start:], identifier]
        diagnostics.append(
            _diag(
                root / nodes[identifier].path,
                "artifact relation cycle: " + " -> ".join(cycle),
            )
        )
        return
    state[identifier] = 1
    stack.append(identifier)
    for target in graph.get(identifier, []):
        if target not in inactive:
            _visit_cycle(
                target,
                stack,
                graph,
                nodes,
                inactive,
                state,
                diagnostics,
                root,
            )
    stack.pop()
    state[identifier] = 2


def _commit_relations(record: str) -> list[dict[str, Any]]:
    """Handle relations using the declared repository contract."""
    record = record.strip()
    if not record or "\x1f" not in record:
        return []
    commit, body = record.split("\x1f", 1)
    implements: set[str] = set()
    sessions: set[str] = set()
    for line in body.splitlines():
        if line.startswith("Implements:"):
            implements.update(re.findall(r"[A-Z0-9]+(?:-[A-Z0-9]+)+", line))
        elif line.startswith("Session:"):
            value = line.partition(":")[2].strip()
            if SESSION_PATTERN.fullmatch(value):
                sessions.add(value)
    return [
        {
            "source": commit,
            "source_kind": "commit",
            "type": "implementation_of",
            "target": target,
            "origin": "commit_trailer",
            "llm_session_ids": sorted(sessions),
        }
        for target in sorted(implements)
    ]


def _relation_sort_key(item: dict[str, Any]) -> tuple[str, str, str]:
    target = item.get("target")
    if target is None:
        target = repr(item.get("range", {}))
    return str(item["source"]), str(item["type"]), str(target)


def _local_relation_key(relation: ArtifactRelation) -> tuple[str, str]:
    locator = relation.target or repr(relation.range)
    return relation.type, locator


def _reject_reverse_fields(
    path: Path,
    metadata: dict[str, Any],
    diagnostics: list[Diagnostic],
) -> None:
    present = sorted(REVERSE_FIELDS & set(metadata))
    if present:
        diagnostics.append(
            _diag(path, "reverse relations must not be authored: " + ", ".join(present))
        )


def _known_relation_ids(root: Path) -> set[str]:
    """Handle relation ids using the declared repository contract."""
    layout = discover_layout(root)
    current = layout.recursive or layout.separated
    identifiers = set() if current else legacy_authority_ids(root)
    if current:
        identifiers.update(
            str(item["id"])
            for item in build_semantic_classification_index(root)
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        )
    if not current and layout.intake_path.is_file():
        data = load(layout.intake_path)
        items = data.get("items", []) if isinstance(data, dict) else []
        identifiers.update(
            str(item["id"])
            for item in items
            if isinstance(item, dict) and isinstance(item.get("id"), str)
        )
    if not layout.separated:
        for path in layout.structured_named_files(root, "package"):
            identifiers.update(_package_ids(path))
    return identifiers


def _package_ids(path: Path) -> set[str]:
    """Handle ids using the declared repository contract."""
    try:
        data = load(path)
    except (OSError, UnicodeError, StructuredDataError):
        return set()
    if not isinstance(data, dict):
        return set()
    identifiers: set[str] = set()
    for value in data.values():
        if isinstance(value, list):
            identifiers.update(
                str(item)
                for item in value
                if isinstance(item, str) and ID_PATTERN.fullmatch(item)
            )
    return identifiers


def _frontmatter(path: Path) -> dict[str, Any] | None:
    try:
        data = frontmatter_metadata(path)
    except (OSError, UnicodeError, FrontmatterError):
        return None
    return data if isinstance(data, dict) else None


def _inactive_semantic_ids(root: Path) -> set[str]:
    """Return semantic identities whose only carriers are archived."""
    return {
        str(item["id"])
        for item in build_semantic_classification_index(root)
        if item.get("archived") is True
    }


def _layer_from_id(identifier: str) -> str | None:
    """Handle from id using the declared repository contract."""
    for segment in identifier.split("-"):
        mapped = ID_TOKEN_LAYERS.get(segment.upper())
        if mapped is not None:
            return mapped
        lowered = segment.lower()
        if lowered in LAYERS:
            return lowered
    return None


def _atom_sequence(identifier: str) -> int:
    match = ATOM_PATTERN.search(identifier)
    return int(match.group(1)) if match else -1


def _optional_text(value: object) -> str | None:
    return str(value) if isinstance(value, str) else None


def _valid_range_subtype(semantic_type: object, subtype: object) -> bool:
    """Handle range subtype using the declared repository contract."""
    if subtype is None:
        return True
    if not isinstance(semantic_type, str) or not isinstance(subtype, str):
        return False
    if subtype == "none":
        return semantic_type != "qa"
    return subtype in SEMANTIC_SUBTYPES.get(semantic_type, frozenset())


def _diag(path: Path, message: str) -> Diagnostic:
    return Diagnostic("CARMADIO-E158", path, message)

"""Validate source carriers against the selected Local Python Tools profile."""

from __future__ import annotations

import ast
from collections.abc import Iterable
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .diagnostics import Diagnostic
from .toml_codec import load

# PROFILE_NAME identifies the only current concrete Python profile; methodology owns it.
PROFILE_NAME = "020_dset-implementation-local-python-tools-profile-v1.toml"
# PRIVATE_DOCSTRING_STATEMENT_LIMIT separates trivial helpers from documented behavior.
PRIVATE_DOCSTRING_STATEMENT_LIMIT = 5
# AUTHORITATIVE_PYTHON_ROOTS maps selected work areas to repository-owned source roots.
AUTHORITATIVE_PYTHON_ROOTS = (
    Path("dset_toolchain"),
    Path("tests"),
    Path("15_layer_implementation/100_python"),
    Path("15_layer_implementation/110_tests"),
)


@dataclass(frozen=True)
class PythonProfileLimits:
    """Hold executable size limits loaded from the selected profile."""

    function_exclusive: int
    module_maximum: int


def validate_local_python_profile(root: Path) -> list[Diagnostic]:
    """Validate every authoritative Python carrier for this framework source."""
    root = root.resolve()
    profile_path = _find_profile(root)
    try:
        limits = _load_limits(profile_path)
    except (OSError, TypeError, ValueError) as error:
        return [Diagnostic("CARMADIO-E180", profile_path, str(error))]
    diagnostics: list[Diagnostic] = []
    for path in _python_files(root):
        diagnostics.extend(_validate_file(path, limits))
    return sorted(set(diagnostics))


def _find_profile(root: Path) -> Path:
    """Resolve the one authoritative Local Python Tools profile carrier."""
    matches = sorted(root.rglob(PROFILE_NAME))
    source = [path for path in matches if ".carmadio" not in path.parts]
    if len(source) == 1:
        return source[0]
    if len(matches) == 1:
        return matches[0]
    raise FileNotFoundError(f"expected one selected profile named {PROFILE_NAME}")


def _load_limits(path: Path) -> PythonProfileLimits:
    """Load mandatory size limits without duplicating their numeric values."""
    data = load(path)
    limits = data.get("limits") if isinstance(data, dict) else None
    if not isinstance(limits, dict):
        raise ValueError("Local Python Tools profile requires a limits table")
    function_limit = limits.get("function_line_limit_exclusive")
    module_limit = limits.get("module_line_limit")
    if not isinstance(function_limit, int) or function_limit < 2:
        raise ValueError("function_line_limit_exclusive must be an integer above one")
    if not isinstance(module_limit, int) or module_limit < function_limit:
        raise ValueError("module_line_limit must be at least the function limit")
    return PythonProfileLimits(function_limit, module_limit)


def _python_files(root: Path) -> tuple[Path, ...]:
    """Enumerate authoritative root Python sources without installed mirrors."""
    paths = {
        path
        for relative in AUTHORITATIVE_PYTHON_ROOTS
        for path in (root / relative).rglob("*.py")
        if "__pycache__" not in path.parts
    }
    return tuple(sorted(paths))


def _validate_file(path: Path, limits: PythonProfileLimits) -> list[Diagnostic]:
    """Parse and validate one source carrier against static profile rules."""
    try:
        source = path.read_text(encoding="utf-8")
        tree = ast.parse(source, path.as_posix())
    except (OSError, UnicodeError, SyntaxError) as error:
        return [
            _diagnostic("CARMADIO-E180", path, f"Python carrier cannot be read: {error}")
        ]
    diagnostics = _module_diagnostics(path, source, tree, limits)
    diagnostics.extend(_definition_diagnostics(path, source, tree, limits))
    diagnostics.extend(_constant_diagnostics(path, source, tree))
    return diagnostics


def _module_diagnostics(
    path: Path,
    source: str,
    tree: ast.Module,
    limits: PythonProfileLimits,
) -> list[Diagnostic]:
    """Check module documentation, measured size, and indentation."""
    diagnostics: list[Diagnostic] = []
    if ast.get_docstring(tree, clean=False) is None:
        diagnostics.append(
            _diagnostic("CARMADIO-E181", path, "module docstring is missing")
        )
    measured = _measured_module_lines(source, tree)
    if measured > limits.module_maximum:
        diagnostics.append(
            _diagnostic(
                "CARMADIO-E182",
                path,
                f"module has {measured} measured lines; maximum is {limits.module_maximum}",
            )
        )
    if "\t" in source:
        diagnostics.append(
            _diagnostic("CARMADIO-E180", path, "tab indentation is prohibited")
        )
    return diagnostics


def _definition_diagnostics(
    path: Path,
    source: str,
    tree: ast.Module,
    limits: PythonProfileLimits,
) -> list[Diagnostic]:
    """Check classes and functions for size, documentation, and typing."""
    diagnostics: list[Diagnostic] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and ast.get_docstring(node) is None:
            diagnostics.append(
                _at("CARMADIO-E184", path, node, "class docstring is missing")
            )
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        measured = _measured_function_lines(source, node)
        if measured >= limits.function_exclusive:
            diagnostics.append(
                _at(
                    "CARMADIO-E183",
                    path,
                    node,
                    f"function has {measured} measured lines; exclusive limit is {limits.function_exclusive}",
                )
            )
        diagnostics.extend(_function_contract_diagnostics(path, node, measured))
    return diagnostics


def _function_contract_diagnostics(
    path: Path,
    node: ast.FunctionDef | ast.AsyncFunctionDef,
    measured: int,
) -> list[Diagnostic]:
    """Check one function's documentation and complete annotations."""
    diagnostics: list[Diagnostic] = []
    if _requires_docstring(path, node, measured) and ast.get_docstring(node) is None:
        diagnostics.append(
            _at("CARMADIO-E184", path, node, "function docstring is missing")
        )
    arguments = [*node.args.posonlyargs, *node.args.args, *node.args.kwonlyargs]
    if node.args.vararg is not None:
        arguments.append(node.args.vararg)
    if node.args.kwarg is not None:
        arguments.append(node.args.kwarg)
    missing = [
        argument.arg
        for argument in arguments
        if argument.arg not in {"self", "cls"} and argument.annotation is None
    ]
    if missing or node.returns is None:
        details = ", ".join(missing) if missing else "return"
        diagnostics.append(
            _at("CARMADIO-E185", path, node, f"annotations missing: {details}")
        )
    return diagnostics


def _requires_docstring(
    path: Path,
    node: ast.FunctionDef | ast.AsyncFunctionDef,
    measured: int,
) -> bool:
    """Return whether a function is public or nontrivial enough to document."""
    if path.parent.name == "tests" and node.name.startswith("test_"):
        return False
    if node.name.startswith("_"):
        return measured > PRIVATE_DOCSTRING_STATEMENT_LIMIT
    return True


def _constant_diagnostics(
    path: Path, source: str, tree: ast.Module
) -> list[Diagnostic]:
    """Check module constant placement and adjacent responsibility comments."""
    lines = source.splitlines()
    diagnostics: list[Diagnostic] = []
    declarations_ended = False
    for node in tree.body:
        if _is_import_or_docstring(node):
            continue
        names = _constant_names(node)
        if names:
            previous = lines[node.lineno - 2].strip() if node.lineno > 1 else ""
            if not previous.startswith("#"):
                diagnostics.append(
                    _at("CARMADIO-E186", path, node, "constant lacks documentation")
                )
            if declarations_ended:
                diagnostics.append(
                    _at(
                        "CARMADIO-E186",
                        path,
                        node,
                        "constant follows executable declarations",
                    )
                )
            continue
        declarations_ended = True
    return diagnostics


def _is_import_or_docstring(node: ast.stmt) -> bool:
    """Recognize declarations that may precede module constants."""
    if isinstance(node, (ast.Import, ast.ImportFrom)):
        return True
    return (
        isinstance(node, ast.Expr)
        and isinstance(node.value, ast.Constant)
        and isinstance(node.value.value, str)
    )


def _constant_names(node: ast.stmt) -> tuple[str, ...]:
    """Return upper-case names assigned by one top-level statement."""
    targets: Iterable[ast.expr]
    if isinstance(node, ast.Assign):
        targets = node.targets
    elif isinstance(node, ast.AnnAssign):
        targets = (node.target,)
    else:
        return ()
    return tuple(
        target.id
        for target in targets
        if isinstance(target, ast.Name) and target.id.isupper()
    )


def _measured_module_lines(source: str, tree: ast.Module) -> int:
    """Count physical module code lines after profile exclusions."""
    excluded = _docstring_lines(tree)
    return _count_code_lines(source, 1, len(source.splitlines()), excluded)


def _measured_function_lines(
    source: str,
    node: ast.FunctionDef | ast.AsyncFunctionDef,
) -> int:
    """Count physical function body lines after profile exclusions."""
    if not node.body:
        return 0
    excluded: set[int] = set()
    docstring = _leading_docstring(node.body)
    if docstring is not None:
        excluded.update(_node_line_range(docstring))
    for nested in _nested_definitions(node.body):
        excluded.update(_node_line_range(nested))
        for decorator in nested.decorator_list:
            excluded.update(_node_line_range(decorator))
    start = node.body[0].lineno
    end = node.end_lineno or node.body[-1].end_lineno or node.body[-1].lineno
    return _count_code_lines(source, start, end, excluded)


def _leading_docstring(body: list[ast.stmt]) -> ast.Expr | None:
    """Return the leading string expression for a definition body."""
    if not body:
        return None
    first = body[0]
    if _is_import_or_docstring(first) and isinstance(first, ast.Expr):
        return first
    return None


def _docstring_lines(tree: ast.Module) -> set[int]:
    """Return every definition docstring line excluded from module size."""
    lines: set[int] = set()
    for node in ast.walk(tree):
        if isinstance(
            node, (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)
        ):
            docstring = _leading_docstring(node.body)
            if docstring is not None:
                lines.update(_node_line_range(docstring))
    return lines


def _nested_definitions(
    body: list[ast.stmt],
) -> tuple[ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef, ...]:
    """Return nested definitions whose bodies are measured independently."""
    nested: list[ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef] = []

    def visit(node: ast.AST) -> None:
        """Collect definitions without descending into their owned bodies."""
        for child in ast.iter_child_nodes(node):
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                nested.append(child)
                continue
            visit(child)

    for statement in body:
        if isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            nested.append(statement)
        else:
            visit(statement)
    return tuple(nested)


def _node_line_range(node: ast.AST) -> range:
    """Return the inclusive physical line range owned by an AST node."""
    start = getattr(node, "lineno", 1)
    end = getattr(node, "end_lineno", start) or start
    return range(start, end + 1)


def _count_code_lines(
    source: str,
    start: int,
    end: int,
    excluded: set[int],
) -> int:
    """Count nonblank, non-comment physical lines outside exclusions."""
    lines = source.splitlines()
    return sum(
        1
        for number in range(start, min(end, len(lines)) + 1)
        if number not in excluded
        and lines[number - 1].strip()
        and not lines[number - 1].lstrip().startswith("#")
    )


def _diagnostic(code: str, path: Path, message: str) -> Diagnostic:
    """Build a profile diagnostic for a whole source carrier."""
    return Diagnostic(code, path, message)


def _at(code: str, path: Path, node: ast.AST, message: str) -> Diagnostic:
    """Build a profile diagnostic anchored to one AST node line."""
    return _diagnostic(code, path, f"line {getattr(node, 'lineno', 1)}: {message}")

"""Provide DSET methodology sync behavior."""

from __future__ import annotations

import hashlib
import shutil
from dataclasses import dataclass
from pathlib import Path

from .layout import METHODOLOGY_ROOT, discover_layout

# SOURCE_TO_INSTALLED defines source to installed; this module owns the default.
SOURCE_TO_INSTALLED = (
    ("10_project", "00_project"),
    ("11_layer_meta", "01_meta"),
    ("12_layer_gov", "02_gov"),
    ("13_layer_tool", "03_tool"),
    ("14_layer_skill", "04_skill"),
    ("15_layer_implementation", "05_implementation"),
    ("16_layer_ops", "06_ops"),
)
# EXECUTABLE_SOURCE_TO_INSTALLED defines executable source to installed; this module owns the default.
EXECUTABLE_SOURCE_TO_INSTALLED = (
    ("dset_toolchain", "05_implementation/100_python/dset_toolchain"),
    ("tests", "05_implementation/110_tests/tests"),
)
# ALL_SOURCE_TO_INSTALLED defines all source to installed; this module owns the default.
ALL_SOURCE_TO_INSTALLED = SOURCE_TO_INSTALLED + EXECUTABLE_SOURCE_TO_INSTALLED
# IMPLEMENTATION_EXECUTABLE_SUBTREES defines implementation executable subtrees; this module owns the default.
IMPLEMENTATION_EXECUTABLE_SUBTREES = (
    Path("100_python/dset_toolchain"),
    Path("110_tests/tests"),
)
# SOURCE_ONLY_CARRIERS defines source only carriers; this module owns the default.
SOURCE_ONLY_CARRIERS = frozenset({"000_dset-project-hub.md"})


@dataclass(frozen=True)
class MethodologyDrift:
    """Represent methodology drift behavior and state."""

    carrier: str
    status: str


def methodology_drift(root: Path) -> tuple[MethodologyDrift, ...]:
    """Compare reusable source with the installed project-local methodology."""

    root = root.resolve()
    target = _installed_root(root)
    drift: list[MethodologyDrift] = []
    expected_roots = {name.split("/", 1)[0] for _, name in ALL_SOURCE_TO_INSTALLED}
    if target.is_dir():
        for child in sorted(target.iterdir()):
            if child.is_dir() and child.name not in expected_roots:
                drift.append(MethodologyDrift(child.name, "unexpected"))
    for source_name, installed_name in ALL_SOURCE_TO_INSTALLED:
        source_root = root / source_name
        installed_root = target / installed_name
        _require_directory(source_root, source_name)
        source_files = _files(source_root)
        installed_files = (
            _files(
                installed_root,
                excluded=IMPLEMENTATION_EXECUTABLE_SUBTREES
                if source_name == "15_layer_implementation"
                else (),
            )
            if installed_root.is_dir()
            else {}
        )
        for relative, source in source_files.items():
            if source.name in SOURCE_ONLY_CARRIERS:
                continue
            destination = installed_root / relative
            if not destination.is_file():
                drift.append(MethodologyDrift(source.name, "missing"))
            elif _sha256(source) != _sha256(destination):
                drift.append(MethodologyDrift(source.name, "changed"))
        for relative, installed in installed_files.items():
            if installed.name in SOURCE_ONLY_CARRIERS:
                continue
            if relative not in source_files:
                drift.append(MethodologyDrift(installed.name, "unexpected"))
    return tuple(sorted(drift, key=lambda item: (item.carrier, item.status)))


def sync_methodology(root: Path, *, execute: bool = False) -> tuple[str, ...]:
    """Preview or materialize source carriers into the installed methodology."""

    root = root.resolve()
    drift = methodology_drift(root)
    changed = tuple(item.carrier for item in drift)
    if not execute:
        return changed
    target = _installed_root(root)
    _remove_source_less_carriers(root, target)
    for source_name, installed_name in ALL_SOURCE_TO_INSTALLED:
        source_root = root / source_name
        installed_root = target / installed_name
        installed_root.mkdir(parents=True, exist_ok=True)
        for relative, source in _files(source_root).items():
            if source.name in SOURCE_ONLY_CARRIERS:
                continue
            destination = installed_root / relative
            if destination.is_file() and _sha256(source) == _sha256(destination):
                continue
            destination.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(source, destination)
    if methodology_drift(root):
        raise ValueError("installed methodology remains out of sync")
    return changed


def _remove_source_less_carriers(root: Path, target: Path) -> None:
    """Handle source less carriers using the declared repository contract."""
    expected_roots = {name.split("/", 1)[0] for _, name in ALL_SOURCE_TO_INSTALLED}
    for child in sorted(target.iterdir()):
        if child.is_dir() and child.name not in expected_roots:
            shutil.rmtree(child)
    for source_name, installed_name in ALL_SOURCE_TO_INSTALLED:
        source_root = root / source_name
        installed_root = target / installed_name
        if not installed_root.is_dir():
            continue
        excluded = (
            IMPLEMENTATION_EXECUTABLE_SUBTREES
            if source_name == "15_layer_implementation"
            else ()
        )
        source_files = _files(source_root)
        installed_files = _files(installed_root, excluded=excluded)
        for relative, installed in installed_files.items():
            if relative not in source_files:
                installed.unlink()
        for directory in sorted(installed_root.rglob("*"), reverse=True):
            if directory.is_dir() and not any(directory.iterdir()):
                directory.rmdir()


def _installed_root(root: Path) -> Path:
    layout = discover_layout(root)
    if not layout.separated:
        raise ValueError("methodology synchronization requires a separated layout")
    return layout.carmadio_root / METHODOLOGY_ROOT


def _files(
    root: Path,
    *,
    excluded: tuple[Path, ...] = (),
) -> dict[Path, Path]:
    """Handle files using the declared repository contract."""
    files: dict[Path, Path] = {}
    for path in sorted(root.rglob("*")):
        if not path.is_file():
            continue
        relative = path.relative_to(root)
        if (
            path.name.startswith(".")
            or path.suffix == ".pyc"
            or "__pycache__" in relative.parts
            or "_obsolete" in relative.parts
            or any(relative.is_relative_to(prefix) for prefix in excluded)
        ):
            continue
        files[relative] = path
    return files


def _require_directory(path: Path, identity: str) -> None:
    if not path.is_dir():
        raise FileNotFoundError(f"methodology area is missing: {identity}")


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

"""Provide DSET release behavior."""

from __future__ import annotations

import json
import os
import re
import tempfile
from collections.abc import Mapping
from contextlib import suppress
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .frontmatter import FrontmatterError
from .frontmatter import parse as parse_frontmatter
from .layout import RepositoryLayout, discover_layout
from .project_data import project_section, write_project_section
from .structured_data import dump, load

# _SEMVER validates semver; this module owns the accepted syntax.
_SEMVER = re.compile(
    r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-rc\.(0|[1-9][0-9]*))?$"
)
# RELEASE_CLASSES defines release classes; this module owns the default.
RELEASE_CLASSES = {"bootstrap", "small", "normal", "rc", "final", "breaking"}
# _FULL_SHA validates full sha; this module owns the accepted syntax.
_FULL_SHA = re.compile(r"^[0-9a-f]{40}$")
# _PROJECT_VERSION validates project version; this module owns the accepted syntax.
_PROJECT_VERSION = re.compile(
    r'(?ms)(^\[project\]\s*$.*?^version\s*=\s*")([^"]+)("\s*$)'
)
# _MODULE_VERSION validates module version; this module owns the accepted syntax.
_MODULE_VERSION = re.compile(r'(?m)^__version__\s*=\s*"([^"]+)"\s*$')


class ReleaseError(ValueError):
    """A release transaction is incomplete, inconsistent, or unsafe."""


@dataclass(frozen=True, order=True)
class ProductVersion:
    """Represent product version behavior and state."""

    major: int
    minor: int
    patch: int
    rc: int | None = None

    @classmethod
    def parse(cls, raw: str) -> ProductVersion:
        """Parse parse using the declared repository contract."""
        match = _SEMVER.fullmatch(raw)
        if match is None:
            raise ValueError(f"invalid DSET product version: {raw}")
        major, minor, patch, rc = match.groups()
        return cls(int(major), int(minor), int(patch), int(rc) if rc else None)

    @property
    def semver(self) -> str:
        """Handle semver using the declared repository contract."""
        base = f"{self.major}.{self.minor}.{self.patch}"
        return f"{base}-rc.{self.rc}" if self.rc is not None else base

    @property
    def python(self) -> str:
        """Handle python using the declared repository contract."""
        base = f"{self.major}.{self.minor}.{self.patch}"
        return f"{base}rc{self.rc}" if self.rc is not None else base


def expected_target(
    base: str | None,
    release_class: str,
    *,
    bootstrap_target: str | None = None,
    readiness_passed: bool = False,
) -> ProductVersion:
    """Handle target using the declared repository contract."""
    if release_class not in RELEASE_CLASSES:
        raise ValueError(f"unknown release class: {release_class}")
    if release_class == "bootstrap":
        if base not in {None, "unversioned"}:
            raise ValueError("bootstrap requires an unversioned base")
        if bootstrap_target is None:
            raise ValueError("bootstrap requires an explicit target")
        target = ProductVersion.parse(bootstrap_target)
        if target.major != 0 or target.rc is not None:
            raise ValueError("bootstrap target must be a stable pre-1.0 version")
        return target
    if base in {None, "unversioned"}:
        raise ValueError(f"{release_class} requires a versioned base")

    current = ProductVersion.parse(base)
    if release_class == "rc":
        if current.rc is not None:
            return ProductVersion(1, 0, 0, current.rc + 1)
        if current.major != 0 or not readiness_passed:
            raise ValueError("the first 1.0 RC requires a passing pre-1.0 base")
        return ProductVersion(1, 0, 0, 1)
    if release_class == "final":
        if current != ProductVersion(1, 0, 0, current.rc) or current.rc is None:
            raise ValueError("final requires a 1.0.0 RC base")
        if not readiness_passed:
            raise ValueError("final requires passing readiness")
        return ProductVersion(1, 0, 0)
    if current.rc is not None:
        raise ValueError("published RCs advance only to a higher RC or final")
    if release_class == "small":
        return ProductVersion(current.major, current.minor, current.patch + 1)
    if release_class == "normal":
        return ProductVersion(current.major, current.minor + 1, 0)
    if release_class == "breaking" and current.major >= 1:
        return ProductVersion(current.major + 1, 0, 0)
    raise ValueError("breaking releases require a stable post-1.0 base")


def validate_coordinated_identity(product: str, python_package: str) -> None:
    """Validate coordinated identity using the declared repository contract."""
    version = ProductVersion.parse(product)
    if python_package != version.python:
        raise ValueError(
            "Python package version must be the exact PEP 440 serialization "
            f"of {version.semver}: {version.python}"
        )


@dataclass(frozen=True)
class ReleasePlan:
    """Represent release plan behavior and state."""

    owner_change: str
    owner_manifest: str
    release_class: str
    base_ref: str
    base_commit: str
    base_version: str
    candidate_commit: str
    target: str
    python_target: str
    tag: str
    publisher: str
    integration_branch: str
    protected_branch: str
    readiness: str
    surfaces: dict[str, str]
    changes: tuple[str, ...]

    def to_dict(self) -> dict[str, Any]:
        """Handle dict using the declared repository contract."""
        return {
            "owner_change": self.owner_change,
            "owner_manifest": self.owner_manifest,
            "release_class": self.release_class,
            "base": {
                "ref": self.base_ref,
                "commit": self.base_commit,
                "version": self.base_version,
            },
            "candidate_commit": self.candidate_commit,
            "target": self.target,
            "python_target": self.python_target,
            "tag": self.tag,
            "publisher": self.publisher,
            "integration_branch": self.integration_branch,
            "protected_branch": self.protected_branch,
            "readiness": self.readiness,
            "surfaces": dict(self.surfaces),
            "changes": list(self.changes),
            "prepared": not self.changes,
        }


@dataclass(frozen=True)
class ReleasePreparation:
    """Represent release preparation behavior and state."""

    plan: ReleasePlan
    executed: bool
    changed: tuple[str, ...]

    def to_dict(self) -> dict[str, Any]:
        """Handle dict using the declared repository contract."""
        data = self.plan.to_dict()
        data.update({"executed": self.executed, "changed": list(self.changed)})
        return data


def plan_release(root: Path) -> ReleasePlan:
    """Build one deterministic, read-only plan from the committed declaration."""

    root = root.resolve()
    layout = discover_layout(root)
    manifest = _mapping(load(layout.manifest_path), "project manifest")
    project_release = _mapping(manifest.get("release"), "project release config")
    if project_release.get("status") != "applicable":
        raise ReleaseError("release is not applicable to this project")
    integration = _required_string(project_release, "integration_branch")
    protected = _required_string(project_release, "protected_branch")
    publisher = _required_string(project_release, "publisher")
    tag_pattern = _required_string(project_release, "tag_pattern")
    if publisher != "github":
        raise ReleaseError(f"unsupported release publisher: {publisher}")
    if tag_pattern.count("{product_version}") != 1:
        raise ReleaseError(
            "release tag pattern must contain exactly one {product_version} placeholder"
        )

    prepared_version = _current_product_version(root)
    owner_path, owner, references = _release_owner(
        layout.active_change_roots,
        layout.archive_change_roots,
        prepared_version,
    )
    owner_id = _required_string(owner, "id")
    declaration = _mapping(owner.get("release"), "release declaration")
    release_class = _required_string(declaration, "class")
    if release_class not in RELEASE_CLASSES:
        raise ReleaseError(f"unknown release class: {release_class}")
    for reference_id, target in references:
        if target != owner_id:
            raise ReleaseError(
                "release owner reference must target "
                f"{owner_id}: {reference_id}/{target}"
            )

    base = _mapping(declaration.get("base"), "release base")
    base_ref = _required_string(base, "ref")
    base_commit = _required_string(base, "commit")
    base_version = _required_string(base, "version")
    candidate_commit = _required_string(declaration, "candidate_commit")
    target = _required_string(declaration, "target")
    readiness_relative = _required_string(declaration, "readiness")
    if base_ref != protected:
        raise ReleaseError(
            f"release base ref must be the protected branch {protected}: {base_ref}"
        )
    if _FULL_SHA.fullmatch(base_commit) is None:
        raise ReleaseError("release base commit must be a full SHA")
    if _FULL_SHA.fullmatch(candidate_commit) is None:
        raise ReleaseError("release candidate commit must be a full SHA")
    readiness = _contained_file(owner_path, readiness_relative, "readiness")
    readiness_passed = _readiness_passed(readiness, candidate_commit)

    try:
        computed = expected_target(
            base_version,
            release_class,
            bootstrap_target=target if release_class == "bootstrap" else None,
            readiness_passed=readiness_passed,
        )
    except ValueError as error:
        raise ReleaseError(str(error)) from error
    if computed.semver != target:
        raise ReleaseError(
            f"declared target does not match {release_class} transition: "
            f"{target} != {computed.semver}"
        )
    tag = tag_pattern.replace("{product_version}", computed.semver)
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]*", tag) is None:
        raise ReleaseError(f"rendered release tag is not supported safely: {tag}")

    surfaces = _read_version_surfaces(root)
    changes = tuple(
        sorted(
            {
                _surface_path(root, name)
                for name, value in surfaces.items()
                if value != _surface_target(name, computed)
            }
        )
    )
    return ReleasePlan(
        owner_change=owner_id,
        owner_manifest=RepositoryLayout.structured_file(owner_path, "change.toml")
        .relative_to(root)
        .as_posix(),
        release_class=release_class,
        base_ref=base_ref,
        base_commit=base_commit,
        base_version=base_version,
        candidate_commit=candidate_commit,
        target=computed.semver,
        python_target=computed.python,
        tag=tag,
        publisher=publisher,
        integration_branch=integration,
        protected_branch=protected,
        readiness=readiness.relative_to(root).as_posix(),
        surfaces=surfaces,
        changes=changes,
    )


def check_release(root: Path) -> ReleasePlan:
    """Require every committed release mirror to match its declaration."""

    plan = plan_release(root)
    if plan.changes:
        raise ReleaseError(
            "release is not prepared; mismatched version surfaces: "
            + ", ".join(plan.changes)
        )
    validate_coordinated_identity(plan.target, plan.python_target)
    return plan


def prepare_release(root: Path, *, execute: bool = False) -> ReleasePreparation:
    """Preview or atomically synchronize the declared version surfaces.

    The default is read-only. ``execute=True`` is the explicit repository-write
    boundary. Every file replacement is atomic and a repeated preparation is a
    no-op. Publication is intentionally outside this function.
    """

    root = root.resolve()
    plan = plan_release(root)
    if not execute or not plan.changes:
        return ReleasePreparation(plan, execute, ())
    _require_safe_prepare_inputs(plan)
    layout = discover_layout(root)
    changed: list[str] = []
    version_path = layout.version_path
    if version_path.relative_to(root).as_posix() in plan.changes:
        version_data = _mapping(
            project_section(root, "version_registry"), "version contract"
        )
        framework = _mapping(version_data.get("framework"), "framework version")
        package = _mapping(version_data.get("python_package"), "package version")
        framework["version"] = plan.target
        package["version"] = plan.python_target
        if layout.recursive or layout.separated:
            write_project_section(root, "version_registry", version_data)
        else:
            _atomic_replace_text(version_path, dump(version_data, version_path))
        changed.append(version_path.relative_to(root).as_posix())
    pyproject = root / "pyproject.toml"
    if pyproject.relative_to(root).as_posix() in plan.changes:
        text = pyproject.read_text(encoding="utf-8")
        updated, count = _PROJECT_VERSION.subn(
            lambda match: f"{match.group(1)}{plan.python_target}{match.group(3)}",
            text,
            count=1,
        )
        if count != 1:
            raise ReleaseError("pyproject project version is not uniquely writable")
        _atomic_replace_text(pyproject, updated)
        changed.append(pyproject.relative_to(root).as_posix())
    module = root / "dset_toolchain" / "__init__.py"
    if module.relative_to(root).as_posix() in plan.changes:
        text = module.read_text(encoding="utf-8")
        updated, count = _MODULE_VERSION.subn(
            f'__version__ = "{plan.python_target}"', text, count=1
        )
        if count != 1:
            raise ReleaseError("Python module version is not uniquely writable")
        _atomic_replace_text(module, updated)
        changed.append(module.relative_to(root).as_posix())
    prepared = check_release(root)
    return ReleasePreparation(prepared, True, tuple(changed))


def _release_owner(
    active_roots: tuple[Path, ...],
    archive_roots: tuple[Path, ...],
    prepared_version: str,
) -> tuple[Path, dict[str, Any], list[tuple[str, str]]]:
    """Handle owner using the declared repository contract."""
    declarations: list[tuple[Path, dict[str, Any]]] = []
    references: list[tuple[str, str]] = []
    for root in active_roots:
        if not root.is_dir():
            continue
        for path in sorted(root.iterdir()):
            manifest_path = RepositoryLayout.structured_file(path, "change.toml")
            if path.name == "archive" or not manifest_path.is_file():
                continue
            data = _mapping(load(manifest_path), f"Change manifest {manifest_path}")
            release = data.get("release")
            if not isinstance(release, dict):
                continue
            if "class" in release:
                declarations.append((path, data))
            elif isinstance(release.get("owner_change"), str):
                references.append(
                    (str(data.get("id", path.name)), release["owner_change"])
                )
    if not declarations:
        for root in archive_roots:
            if not root.is_dir():
                continue
            for path in sorted(root.iterdir()):
                manifest_path = RepositoryLayout.structured_file(path, "change.toml")
                if not manifest_path.is_file():
                    continue
                data = _mapping(load(manifest_path), f"Change manifest {manifest_path}")
                release = data.get("release")
                if (
                    isinstance(release, dict)
                    and release.get("target") == prepared_version
                    and "class" in release
                ):
                    declarations.append((path, data))
    if len(declarations) != 1:
        raise ReleaseError(
            f"release preparation requires exactly one owner declaration; "
            f"found {len(declarations)}"
        )
    owner_path, owner = declarations[0]
    return owner_path, owner, references


def _current_product_version(root: Path) -> str:
    version_data = _mapping(
        project_section(root, "version_registry"), "version contract"
    )
    framework = _mapping(version_data.get("framework"), "framework version")
    return _required_string(framework, "version")


def _readiness_passed(path: Path, candidate_commit: str) -> bool:
    """Handle passed using the declared repository contract."""
    try:
        parsed = parse_frontmatter(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError) as error:
        raise ReleaseError(f"cannot read Readiness Record: {path}") from error
    except FrontmatterError as error:
        raise ReleaseError("Readiness Record frontmatter is invalid") from error
    if parsed is None:
        raise ReleaseError("Readiness Record requires TOML or YAML frontmatter")
    data, _body, _format = parsed
    if (
        not isinstance(data, dict)
        or data.get("artifact_type") != "version"
        or data.get("artifact_subtype") != "readiness_record"
    ):
        raise ReleaseError("release readiness must use a Readiness Record")
    if data.get("candidate_sha") != candidate_commit:
        raise ReleaseError(
            "Readiness Record candidate does not match release candidate"
        )
    for field in ("artifact_id", "version_scope_ref", "release_plan_ref"):
        value = data.get(field)
        if not isinstance(value, str) or not value or value == "pending":
            raise ReleaseError(f"Readiness Record field is incomplete: {field}")
    disposition = data.get("disposition")
    if disposition not in {"ready", "blocked"}:
        raise ReleaseError("Readiness Record disposition must be ready or blocked")
    if disposition != "ready":
        raise ReleaseError("Readiness Record blocks this release candidate")
    return True


def _read_version_surfaces(root: Path) -> dict[str, str]:
    """Read version surfaces using the declared repository contract."""
    version_data = _mapping(
        project_section(root, "version_registry"), "version contract"
    )
    framework = _mapping(version_data.get("framework"), "framework version")
    package = _mapping(version_data.get("python_package"), "package version")
    pyproject = (root / "pyproject.toml").read_text(encoding="utf-8")
    project_matches = list(_PROJECT_VERSION.finditer(pyproject))
    if len(project_matches) != 1:
        raise ReleaseError("pyproject must contain one [project] version")
    module_text = (root / "dset_toolchain" / "__init__.py").read_text(encoding="utf-8")
    module_matches = _MODULE_VERSION.findall(module_text)
    if len(module_matches) != 1:
        raise ReleaseError("Python module must contain one __version__")
    return {
        "framework": _required_string(framework, "version"),
        "python_package": _required_string(package, "version"),
        "pyproject": project_matches[0].group(2),
        "module": module_matches[0],
    }


def _surface_target(name: str, target: ProductVersion) -> str:
    return target.semver if name == "framework" else target.python


def _surface_path(root: Path, name: str) -> str:
    """Handle path using the declared repository contract."""
    if name in {"framework", "python_package"}:
        return discover_layout(root).version_path.relative_to(root).as_posix()
    if name == "pyproject":
        return "pyproject.toml"
    if name == "module":
        return "dset_toolchain/__init__.py"
    raise ReleaseError(f"unknown version surface: {name}")


def _require_safe_prepare_inputs(plan: ReleasePlan) -> None:
    """Handle safe prepare inputs using the declared repository contract."""
    target = ProductVersion.parse(plan.target)
    if plan.base_version == "unversioned":
        allowed_products = {target.semver}
        allowed_python = {target.python}
    else:
        base = ProductVersion.parse(plan.base_version)
        allowed_products = {base.semver, target.semver}
        allowed_python = {base.python, target.python}
    for name, current in plan.surfaces.items():
        allowed = allowed_products if name == "framework" else allowed_python
        if current not in allowed:
            raise ReleaseError(
                f"refusing to overwrite unexpected {name} version: {current}"
            )


def _contained_file(root: Path, raw: str, kind: str) -> Path:
    """Handle file using the declared repository contract."""
    path = (root / raw).resolve()
    try:
        path.relative_to(root.resolve())
    except ValueError as error:
        raise ReleaseError(f"{kind} path escapes the release owner") from error
    if not path.is_file():
        raise ReleaseError(f"{kind} artifact is missing: {raw}")
    return path


def _mapping(raw: Any, name: str) -> dict[str, Any]:
    if not isinstance(raw, dict):
        raise ReleaseError(f"{name} must be a mapping")
    return raw


def _required_string(data: Mapping[str, Any], key: str) -> str:
    value = data.get(key)
    if not isinstance(value, str) or not value:
        raise ReleaseError(f"{key} must be a non-empty string")
    return value


def _atomic_replace_text(path: Path, text: str) -> None:
    """Handle replace text using the declared repository contract."""
    descriptor, raw = tempfile.mkstemp(
        prefix=f".{path.name}.", suffix=".tmp", dir=path.parent
    )
    temporary = Path(raw)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8", newline="") as stream:
            stream.write(text)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, path.stat().st_mode)
        os.replace(temporary, path)
    except Exception:
        with suppress(FileNotFoundError):
            temporary.unlink()
        raise


def rendered_plan(plan: ReleasePlan) -> str:
    """Handle plan using the declared repository contract."""
    return json.dumps(plan.to_dict(), indent=2, sort_keys=True)

"""Provide DSET scaffold behavior."""

from __future__ import annotations

import re
from collections.abc import Sequence
from pathlib import Path

from .layout import (
    LAYER_ID_TOKENS,
    RepositoryLayout,
    discover_layout,
    normalize_layer_id_token,
)
from .profiles import VALID_PROFILES, required_artifacts
from .settings import load_project_settings
from .structured_data import dump, load

# TRACE_LAYERS defines trace layers; this module owns the default.
TRACE_LAYERS = tuple(LAYER_ID_TOKENS.values())


def create_change(
    root: Path,
    change_id: str,
    package_id: str,
    profile: str,
    title: str | None = None,
    layer: str | None = None,
    stable_id: str | None = None,
    work_areas: Sequence[str] | None = None,
    workspace_mode: str | None = None,
) -> Path:
    """Create a Change workspace from the selected repository profile."""
    layout = discover_layout(root)
    _validate_change_request(change_id, profile, layout.layered, layer)
    canonical_id = _canonical_change_id(root, change_id, layer, stable_id)
    destination = layout.active_change_root(layer) / change_id
    if destination.exists():
        raise FileExistsError(f"change already exists: {destination}")
    files, directories = required_artifacts(root, profile)
    replacements = _change_replacements(
        root, canonical_id, change_id, package_id, profile, title, layer
    )
    _materialize_change(
        root,
        destination,
        files,
        directories,
        replacements,
        package_id,
        canonical_id,
        change_id,
        layer,
        _change_target(root, work_areas),
        workspace_mode,
    )
    return destination


def _validate_change_request(
    change_id: str, profile: str, layered: bool, layer: str | None
) -> None:
    """Validate the user-controlled Change identity inputs."""
    if not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", change_id):
        raise ValueError("change ID must be lowercase kebab-case")
    if profile not in VALID_PROFILES:
        raise ValueError(f"unknown profile: {profile}")
    if layered and layer is None:
        raise ValueError("schema 1.2 changes require an owning DSET layer")


def _canonical_change_id(
    root: Path, change_id: str, layer: str | None, stable_id: str | None
) -> str:
    """Return the stable Change ID appropriate to the repository layout."""
    if not discover_layout(root).layered:
        return change_id
    canonical_id = stable_id or _next_change_id(root, str(layer))
    expected = (
        rf"{re.escape(_project_key(root))}-CHANGE-{str(layer).upper()}-[0-9]{{3,}}"
    )
    if re.fullmatch(expected, canonical_id) is None:
        raise ValueError("stable Change ID must match its project and owning layer")
    return canonical_id


def _change_replacements(
    root: Path,
    canonical_id: str,
    change_id: str,
    package_id: str,
    profile: str,
    title: str | None,
    layer: str | None,
) -> dict[str, str]:
    """Build the complete placeholder map for Change templates."""
    return {
        "{{change_id}}": canonical_id,
        "{{change_slug}}": change_id,
        "{{package_id}}": package_id,
        "{{profile}}": profile,
        "{{title}}": title or change_id.replace("-", " ").title(),
        "{{project_key}}": _project_key(root),
        "{{id_layer}}": _id_layer(root, layer),
        "{{layer}}": str(layer).lower() if layer is not None else "",
        "{{repository}}": _repository(root),
    }


def _materialize_change(
    root: Path,
    destination: Path,
    files: set[str],
    directories: set[str],
    replacements: dict[str, str],
    package_id: str,
    canonical_id: str,
    change_id: str,
    layer: str | None,
    change_target: dict[str, object] | None,
    workspace_mode: str | None,
) -> None:
    """Copy selected templates and finish the layered manifest transaction."""
    layout = discover_layout(root)
    destination.mkdir(parents=True)
    try:
        _copy_change_templates(layout, destination, files, directories, replacements)
        _copy_optional_change_hubs(
            layout, destination, directories, package_id, replacements
        )
        if layout.layered:
            _materialize_layered_manifest(
                root,
                destination,
                canonical_id,
                change_id,
                str(layer),
                change_target,
                workspace_mode,
            )
    except Exception:
        _remove_tree(destination)
        raise


def _copy_change_templates(
    layout: RepositoryLayout,
    destination: Path,
    files: set[str],
    directories: set[str],
    replacements: dict[str, str],
) -> None:
    """Copy profile-selected directories and file templates."""
    for directory in sorted(directories):
        (destination / directory).mkdir(parents=True, exist_ok=True)
    for relative in sorted(files):
        template = Path("change") / relative
        relative_path = Path(relative)
        if relative_path.stem == "change" and relative_path.suffix in {
            ".toml",
            ".yaml",
            ".yml",
        }:
            family = "layered" if layout.layered else "legacy"
            template = Path("change") / family / relative_path
        _copy_template(
            layout.find_template(template),
            destination / relative,
            replacements,
        )


def _copy_optional_change_hubs(
    layout: RepositoryLayout,
    destination: Path,
    directories: set[str],
    package_id: str,
    replacements: dict[str, str],
) -> None:
    """Copy package and proof hubs selected by the profile."""
    selected = {
        "specs": ("change/specs/package.md", f"specs/{package_id}.md"),
        "proofs": ("change/proofs/README.md", "proofs/README.md"),
        "proofs/candidate-fit": (
            "change/proofs/candidate-fit/README.md",
            "proofs/candidate-fit/README.md",
        ),
    }
    for directory, (source, target) in selected.items():
        if directory in directories:
            _copy_template(
                layout.find_template(source),
                destination / target,
                replacements,
            )


def _copy_template(source: Path, target: Path, replacements: dict[str, str]) -> None:
    """Handle template using the declared repository contract."""
    if not source.is_file():
        raise FileNotFoundError(f"template is missing: {source}")
    structured = {".toml", ".yaml", ".yml"}
    if target.suffix in structured and source.suffix in structured:
        data = _replace_values(load(source), replacements)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(dump(data, target), encoding="utf-8")
        return
    text = source.read_text(encoding="utf-8")
    for old, new in replacements.items():
        text = text.replace(old, new)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text, encoding="utf-8")


def _replace_values(value: object, replacements: dict[str, str]) -> object:
    """Handle values using the declared repository contract."""
    if isinstance(value, dict):
        return {key: _replace_values(item, replacements) for key, item in value.items()}
    if isinstance(value, list):
        return [_replace_values(item, replacements) for item in value]
    if isinstance(value, str):
        for old, new in replacements.items():
            value = value.replace(old, new)
    return value


def _project_key(root: Path) -> str:
    """Handle key using the declared repository contract."""
    data = load(discover_layout(root).manifest_path)
    project = data.get("project", {}) if isinstance(data, dict) else {}
    key = project.get("key") if isinstance(project, dict) else None
    if not isinstance(key, str) or not re.fullmatch(r"[A-Z][A-Z0-9]*", key):
        raise ValueError("project.key must be an uppercase ID segment")
    return key


def _id_layer(root: Path, layer: str | None) -> str:
    """Handle layer using the declared repository contract."""
    if layer is None:
        return ""
    normalized = normalize_layer_id_token(layer)
    layout = discover_layout(root)
    if layout.layered:
        return f"-{normalized}"
    data = load(layout.intake_path)
    raw_scopes = data.get("scopes", []) if isinstance(data, dict) else []
    registered = {
        item.get("id_segment")
        for item in raw_scopes
        if isinstance(item, dict) and item.get("kind") == "layer"
    }
    if normalized not in registered:
        raise ValueError(f"unregistered ID layer: {normalized}")
    return f"-{normalized}"


def _repository(root: Path) -> str:
    history = load(discover_layout(root).history_path)
    return str(history["repository"])


def _change_target(
    root: Path, work_areas: Sequence[str] | None
) -> dict[str, object] | None:
    """Handle target using the declared repository contract."""
    layout = discover_layout(root)
    requested = list(work_areas or ())
    if not layout.layered:
        if requested:
            raise ValueError("work-area targets require schema 1.2")
        return None
    if any(
        not isinstance(identifier, str)
        or re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", identifier) is None
        for identifier in requested
    ):
        raise ValueError("work-area targets must be kebab-case IDs")
    if len(requested) != len(set(requested)):
        raise ValueError("work-area targets must be unique")
    manifest = load(layout.manifest_path)
    if not isinstance(manifest, dict):
        raise ValueError("project manifest must be a mapping")
    raw_declared = manifest.get("work_areas", [])
    declared = {
        item.get("id")
        for item in (raw_declared if isinstance(raw_declared, list) else [])
        if isinstance(item, dict) and isinstance(item.get("id"), str)
    }
    unknown = sorted(set(requested) - declared)
    if unknown:
        raise ValueError(f"undeclared work-area target: {', '.join(unknown)}")
    selected = sorted(requested)
    return {"repository": not selected, "work_areas": selected}


def _next_change_id(root: Path, layer: str) -> str:
    """Handle change id using the declared repository contract."""
    layout = discover_layout(root)
    normalized = normalize_layer_id_token(layer)
    prefix = f"{_project_key(root)}-CHANGE-{normalized}-"
    highest = 0
    for change_root in (*layout.active_change_roots, *layout.archive_change_roots):
        if not change_root.is_dir():
            continue
        for directory in change_root.iterdir():
            manifest = layout.structured_file(directory, "change.toml")
            if not directory.is_dir() or not manifest.is_file():
                continue
            data = load(manifest)
            identifier = data.get("id") if isinstance(data, dict) else None
            if isinstance(identifier, str) and identifier.startswith(prefix):
                suffix = identifier.removeprefix(prefix)
                if suffix.isdigit():
                    highest = max(highest, int(suffix))
    return f"{prefix}{highest + 1:03d}"


def _materialize_layered_manifest(
    root: Path,
    destination: Path,
    stable_id: str,
    slug: str,
    layer: str,
    target: dict[str, object] | None,
    workspace_mode: str | None,
) -> None:
    """Handle layered manifest using the declared repository contract."""
    path = discover_layout(root).structured_file(destination, "change.toml")
    data = load(path)
    if not isinstance(data, dict):
        raise ValueError("change template root must be a mapping")
    normalized = layer.lower()
    workspace = _workspace_for_change(root, slug, workspace_mode)
    data.update(
        {
            "schema_version": "1.2",
            "id": stable_id,
            "slug": slug,
            "primary_layer": normalized,
            "affected_layers": [normalized],
            "target": target,
            "workspace": workspace,
            "dependencies": [],
        }
    )
    release = data.get("release")
    if isinstance(release, dict):
        if "policy" in release:
            release["policy"] = (
                ".carmadio/000_CARMADIO_METHODOLOGY/06_ops/procedure-release.md"
            )
        if "owner_change" in release:
            release["owner_change"] = stable_id
    path.write_text(dump(data, path), encoding="utf-8")


def _workspace_for_change(
    root: Path, slug: str, requested_mode: str | None
) -> dict[str, str]:
    """Handle for change using the declared repository contract."""
    manifest = load(discover_layout(root).manifest_path)
    if not isinstance(manifest, dict):
        raise ValueError("project manifest must be a mapping")
    settings, settings_issues = load_project_settings(root)
    if settings_issues:
        raise ValueError("; ".join(settings_issues))
    mode = requested_mode or settings.change_workspace_mode
    if mode not in {"integration-branch", "branch-worktree"}:
        raise ValueError("workspace mode must be integration-branch or branch-worktree")
    release = manifest.get("release", {})
    integration = (
        release.get("integration_branch") if isinstance(release, dict) else None
    )
    protected = release.get("protected_branch") if isinstance(release, dict) else None
    if not isinstance(integration, str) or not integration:
        integration = "pending"
    if not isinstance(protected, str) or not protected:
        protected = "pending"
    branch = integration if mode == "integration-branch" else f"dset/{slug}"
    base_ref = protected if mode == "integration-branch" else integration
    return {
        "isolation": mode,
        "branch": branch,
        "base_ref": base_ref,
        "base_commit": "pending",
        "head_commit": "pending",
    }


def _remove_tree(path: Path) -> None:
    import shutil

    if path.exists():
        shutil.rmtree(path)

"""Provide DSET semantic atoms behavior."""

from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .diagnostics import Diagnostic
from .frontmatter import FrontmatterError
from .frontmatter import metadata as frontmatter_metadata
from .identity import has_logical_part, iter_control_files
from .layout import discover_layout
from .legacy_authority import validate_legacy_authority_ledger
from .lineage import ArtifactRelation, parse_authored_relations
from .semantic_types import (
    SEMANTIC_ID_KINDS,
    SEMANTIC_SUBTYPES,
    normalize_semantic_classification,
    semantic_id_kind,
    semantic_id_matches_classification,
    semantic_naming_axis,
)
from .settings import load_project_settings
from .structured_data import StructuredDataError, dump, load

# ID_PATTERN validates id pattern; this module owns the accepted syntax.
ID_PATTERN = re.compile(r"^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)+$")
# SESSION_PATTERN validates session pattern; this module owns the accepted syntax.
SESSION_PATTERN = re.compile(r"^[a-z][a-z0-9_-]*:[A-Za-z0-9._:-]+$")


@dataclass(frozen=True)
class SemanticAtom:
    """Represent semantic atom behavior and state."""

    semantic_id: str
    carrier_id: str
    path: str
    semantic_type: str
    subtype: str | None
    emission_status: str
    priority: str
    llm_session_ids: tuple[str, ...]
    relations: tuple[ArtifactRelation, ...]
    sha256: str

    @property
    def child_of(self) -> tuple[str, ...]:
        """Expose sealed legacy lineage to compatibility callers."""
        return tuple(
            relation.target
            for relation in self.relations
            if relation.type == "child_of" and relation.target is not None
        )


def collect_semantic_atoms(
    root: Path,
) -> tuple[dict[str, SemanticAtom], list[Diagnostic]]:
    """Collect semantic atoms using the declared repository contract."""
    root = root.resolve()
    atoms: dict[str, SemanticAtom] = {}
    diagnostics: list[Diagnostic] = []
    settings, _ = load_project_settings(root)
    allowed_priorities = {*settings.priority_scale, "unknown"}
    layout = discover_layout(root)
    paths = (
        iter_control_files(root, "*.md")
        if layout.separated
        else sorted(root.rglob("*.md"))
    )
    for path in paths:
        relative = path.relative_to(root)
        if _ignored(relative) or has_logical_part(relative, {"templates"}):
            continue
        metadata = _frontmatter(path)
        if metadata is None or metadata.get("artifact_type") != "atomic_record":
            continue
        atom, issues = _parse_atom(root, path, metadata, allowed_priorities)
        diagnostics.extend(issues)
        if atom is None:
            continue
        previous = atoms.get(atom.semantic_id)
        if previous is not None:
            diagnostics.append(
                Diagnostic(
                    "CARMADIO-E159",
                    path,
                    f"duplicate semantic atom ID: {atom.semantic_id}",
                )
            )
            continue
        atoms[atom.semantic_id] = atom
    return atoms, diagnostics


def validate_semantic_atoms(root: Path) -> list[Diagnostic]:
    """Validate semantic atoms using the declared repository contract."""
    atoms, diagnostics = collect_semantic_atoms(root)
    layout = discover_layout(root)
    if not (layout.recursive or layout.separated):
        diagnostics.extend(_validate_ledger(root, atoms))
        diagnostics.extend(validate_legacy_authority_ledger(root))
    return sorted(set(diagnostics))


def seal_atom(root: Path, path: Path) -> Path:
    """Seal atom using the declared repository contract."""
    root = root.resolve()
    path = path.resolve()
    try:
        path.relative_to(root)
    except ValueError as error:
        raise ValueError("atom carrier must be inside the repository") from error
    metadata = _frontmatter(path)
    settings, issues = load_project_settings(root)
    if issues:
        raise ValueError("project settings must pass before sealing an atom")
    if metadata is None:
        raise ValueError("atom carrier requires TOML or YAML frontmatter")
    if "child_of" in metadata:
        raise ValueError(
            "new atoms must use relations; child_of is sealed compatibility input only"
        )
    atom, diagnostics = _parse_atom(
        root, path, metadata, {*settings.priority_scale, "unknown"}
    )
    if diagnostics or atom is None:
        message = diagnostics[0].message if diagnostics else "invalid atom"
        raise ValueError(message)
    expected_kind = semantic_naming_axis(
        atom.semantic_type,
        atom.subtype,
        include_subtype=settings.artifact_subtype_in_names,
    )
    if expected_kind != semantic_id_kind(atom.semantic_id):
        mode = "subtype" if settings.artifact_subtype_in_names else "type"
        raise ValueError(
            f"new atom must use the configured {mode} naming kind: {expected_kind}"
        )
    from .artifact_emission import assess_artifact_candidate

    candidate = {
        "authority": metadata.get("authority"),
        "claim": metadata.get("claim"),
        "type": metadata.get("type"),
        "subtype": metadata.get("subtype"),
        "scope": metadata.get("scope"),
        "llm_session_ids": metadata.get("llm_session_ids"),
        "material_links": _material_relation_links(metadata, path),
        "priority": metadata.get("priority"),
        "acceptance": metadata.get("status"),
        "promotion": metadata.get("promotion"),
    }
    for field in (
        "boundary",
        "lineage",
        "conflict_state",
        "verification_obligation",
        "unknowns",
    ):
        if field in metadata:
            candidate[field] = metadata[field]
    assessment = assess_artifact_candidate(root, candidate)
    if assessment["emission_allowed"] is not True:
        first = assessment["diagnostics"][0]
        raise ValueError(f"artifact emission is blocked: {first['message']}")
    layout = discover_layout(root)
    if layout.recursive or layout.separated:
        return path
    ledger_path = _ledger_path(root)
    data = _load_or_empty(ledger_path, "records")
    records = data["records"]
    assert isinstance(records, list)
    if any(
        isinstance(item, dict) and item.get("semantic_id") == atom.semantic_id
        for item in records
    ):
        raise FileExistsError(f"atom is already sealed: {atom.semantic_id}")
    records.append(_ledger_record(atom))
    records.sort(key=lambda item: str(item.get("semantic_id", "")))
    _atomic_dump(ledger_path, data)
    return ledger_path


def effective_priority(root: Path, atom: SemanticAtom) -> tuple[str, str]:
    """Handle priority using the declared repository contract."""
    if atom.priority == "unknown":
        return "unknown", f"atom:{atom.semantic_id}"
    return atom.priority, f"atom:{atom.semantic_id}"


def build_semantic_atom_index(root: Path) -> list[dict[str, Any]]:
    """Build current atom, priority, relation, and archive lookup."""
    atoms, diagnostics = collect_semantic_atoms(root)
    if diagnostics:
        raise ValueError(diagnostics[0].message)
    replaced_by: dict[str, list[str]] = {}
    for candidate in atoms.values():
        for relation in candidate.relations:
            if relation.type == "replacement_of" and relation.target is not None:
                replaced_by.setdefault(relation.target, []).append(
                    candidate.semantic_id
                )
    rows: list[dict[str, Any]] = []
    for atom in atoms.values():
        priority, priority_source = effective_priority(root, atom)
        archived = "archive" in Path(atom.path).parts
        rows.append(
            {
                "id": atom.semantic_id,
                "carrier_id": atom.carrier_id,
                "carrier": Path(atom.path).name,
                "sha256": atom.sha256,
                "type": atom.semantic_type,
                "subtype": atom.subtype or "none",
                "emission_status": atom.emission_status,
                "current_status": "archived" if archived else atom.emission_status,
                "priority": priority,
                "priority_source": priority_source,
                "relations": [relation.as_dict() for relation in atom.relations],
                "replaced_by": sorted(replaced_by.get(atom.semantic_id, [])),
                "archived": archived,
            }
        )
    return sorted(rows, key=lambda item: str(item["id"]))


def archive_atom(root: Path, semantic_id: str) -> Path:
    """Move an inactive atom byte-for-byte into its Type-local archive."""
    root = root.resolve()
    atoms, diagnostics = collect_semantic_atoms(root)
    if diagnostics:
        raise ValueError(diagnostics[0].message)
    atom = atoms.get(semantic_id)
    if atom is None:
        raise ValueError(f"unknown semantic atom: {semantic_id}")
    source = root / atom.path
    if "archive" in source.relative_to(root).parts:
        raise ValueError(f"semantic atom is already archived: {semantic_id}")
    active_dependants = [
        candidate.semantic_id
        for candidate in atoms.values()
        if any(
            relation.target == semantic_id
            and relation.type in {"child_of", "override_of"}
            for relation in candidate.relations
        )
        and "archive" not in Path(candidate.path).parts
    ]
    if active_dependants:
        raise ValueError(
            "semantic atom has active child reliance: "
            + ", ".join(sorted(active_dependants))
        )
    destination = source.parent / "archive" / source.name
    if destination.exists():
        raise FileExistsError(f"archive destination already exists: {source.name}")
    destination.parent.mkdir(parents=True, exist_ok=True)
    source.replace(destination)
    layout = discover_layout(root)
    if not (layout.recursive or layout.separated):
        ledger_path = _ledger_path(root)
        data = _load_or_empty(ledger_path, "records")
        records = data["records"]
        assert isinstance(records, list)
        for record in records:
            if isinstance(record, dict) and record.get("semantic_id") == semantic_id:
                record["path"] = destination.relative_to(root).as_posix()
                break
        else:
            destination.replace(source)
            raise ValueError(f"semantic atom is not sealed: {semantic_id}")
        _atomic_dump(ledger_path, data)
    return destination


def _parse_atom(
    root: Path,
    path: Path,
    data: dict[str, Any],
    allowed_priorities: set[str],
) -> tuple[SemanticAtom | None, list[Diagnostic]]:
    """Parse atom using the declared repository contract."""
    diagnostics: list[Diagnostic] = []
    raw_semantic_type = data.get("type")
    raw_subtype = data.get("subtype")
    subtype = None if raw_subtype is None or raw_subtype == "none" else raw_subtype
    semantic_type = raw_semantic_type
    if isinstance(raw_semantic_type, str):
        semantic_type, subtype = normalize_semantic_classification(
            raw_semantic_type,
            str(subtype) if subtype is not None else None,
        )
    semantic_id = data.get("semantic_id")
    carrier_id = data.get("artifact_id")
    status = data.get("status")
    priority = data.get("priority")
    sessions = data.get("llm_session_ids")
    if semantic_type not in SEMANTIC_SUBTYPES:
        diagnostics.append(_atom_diag(path, "atom requires one of the four Types"))
    elif subtype is not None and subtype not in SEMANTIC_SUBTYPES[semantic_type]:
        diagnostics.append(_atom_diag(path, "atom has an invalid direct subtype"))
    elif semantic_type == "qa" and subtype not in {
        "test_case",
        "evaluation_case",
    }:
        diagnostics.append(
            _atom_diag(path, "QA atom requires test_case or evaluation_case")
        )
    if not isinstance(semantic_id, str) or not ID_PATTERN.fullmatch(semantic_id):
        diagnostics.append(_atom_diag(path, "atom requires a canonical semantic_id"))
    elif semantic_type in SEMANTIC_SUBTYPES:
        expected = SEMANTIC_ID_KINDS.get((semantic_type, subtype))
        if expected is None or not semantic_id_matches_classification(
            semantic_id, semantic_type, subtype
        ):
            diagnostics.append(
                _atom_diag(path, f"semantic_id must use the {expected} kind")
            )
    if not isinstance(carrier_id, str) or not ID_PATTERN.fullmatch(carrier_id):
        diagnostics.append(_atom_diag(path, "atom requires a canonical artifact_id"))
    if status not in {"proposed", "accepted"}:
        diagnostics.append(
            _atom_diag(path, "emission status must be proposed or accepted")
        )
    if priority not in allowed_priorities:
        diagnostics.append(_atom_diag(path, "atom priority is not in project scale"))
    if not _valid_sessions(sessions):
        diagnostics.append(
            _atom_diag(path, "atom requires unique host-prefixed llm_session_ids")
        )
    relations = parse_authored_relations(path, data, diagnostics)
    if diagnostics:
        return None, diagnostics
    assert isinstance(semantic_id, str)
    assert isinstance(carrier_id, str)
    assert isinstance(semantic_type, str)
    assert isinstance(status, str)
    assert isinstance(priority, str)
    assert isinstance(sessions, list)
    return (
        SemanticAtom(
            semantic_id=semantic_id,
            carrier_id=carrier_id,
            path=path.relative_to(root).as_posix(),
            semantic_type=semantic_type,
            subtype=str(subtype) if subtype is not None else None,
            emission_status=status,
            priority=priority,
            llm_session_ids=tuple(str(item) for item in sessions),
            relations=relations,
            sha256=_digest(path),
        ),
        diagnostics,
    )


def _material_relation_links(data: dict[str, Any], path: Path) -> list[str]:
    """Handle relation links using the declared repository contract."""
    diagnostics: list[Diagnostic] = []
    relations = parse_authored_relations(path, data, diagnostics)
    if diagnostics:
        raise ValueError(diagnostics[0].message)
    links: list[str] = []
    for relation in relations:
        if relation.target is not None:
            links.append(relation.target)
        elif relation.range is not None:
            links.append(relation.range.through)
    return links


def _validate_ledger(root: Path, atoms: dict[str, SemanticAtom]) -> list[Diagnostic]:
    """Validate ledger using the declared repository contract."""
    path = _ledger_path(root)
    if not path.is_file():
        if atoms:
            return [Diagnostic("CARMADIO-E161", path, "semantic atom ledger is missing")]
        return []
    try:
        data = load(path)
    except (OSError, UnicodeError, StructuredDataError) as error:
        return [Diagnostic("CARMADIO-E161", path, f"invalid atom ledger: {error}")]
    records = data.get("records") if isinstance(data, dict) else None
    if not isinstance(data, dict) or str(data.get("schema_version")) != "1.0":
        return [Diagnostic("CARMADIO-E161", path, "atom ledger schema_version must be 1.0")]
    if not isinstance(records, list):
        return [Diagnostic("CARMADIO-E161", path, "atom ledger records must be a list")]
    diagnostics: list[Diagnostic] = []
    indexed: dict[str, dict[str, Any]] = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(
            record.get("semantic_id"), str
        ):
            diagnostics.append(Diagnostic("CARMADIO-E161", path, "invalid ledger record"))
            continue
        identifier = str(record["semantic_id"])
        if identifier in indexed:
            diagnostics.append(
                Diagnostic("CARMADIO-E161", path, f"duplicate ledger atom: {identifier}")
            )
        indexed[identifier] = record
    for identifier, atom in atoms.items():
        record = indexed.get(identifier)
        if record is None:
            diagnostics.append(
                Diagnostic("CARMADIO-E161", root / atom.path, "emitted atom is not sealed")
            )
            continue
        expected = _ledger_record(atom)
        comparisons = {
            "carrier_id": "carrier_id",
            "type": "type",
            "subtype": "subtype",
            "current_path" if "current_path" in record else "path": "path",
            "current_sha256" if "current_sha256" in record else "sha256": "sha256",
        }
        for recorded_field, expected_field in comparisons.items():
            if record.get(recorded_field) != expected.get(expected_field):
                diagnostics.append(
                    Diagnostic(
                        "CARMADIO-E161",
                        root / atom.path,
                        f"sealed atom {recorded_field} changed: {identifier}",
                    )
                )
    for identifier in sorted(set(indexed) - set(atoms)):
        record_path = indexed[identifier].get(
            "current_path", indexed[identifier].get("path")
        )
        if not isinstance(record_path, str) or not (root / record_path).is_file():
            diagnostics.append(
                Diagnostic("CARMADIO-E161", path, f"sealed atom is missing: {identifier}")
            )
    return diagnostics


def _ledger_record(atom: SemanticAtom) -> dict[str, Any]:
    """Handle record using the declared repository contract."""
    return {
        "semantic_id": atom.semantic_id,
        "carrier_id": atom.carrier_id,
        "path": atom.path,
        "sha256": atom.sha256,
        "type": atom.semantic_type,
        "subtype": atom.subtype if atom.subtype is not None else "none",
    }


def _load_or_empty(path: Path, field: str) -> dict[str, Any]:
    """Load or empty using the declared repository contract."""
    if not path.is_file():
        return {"schema_version": "1.0", field: []}
    data = load(path)
    if not isinstance(data, dict) or str(data.get("schema_version")) != "1.0":
        raise ValueError(f"invalid registry: {path}")
    values = data.get(field)
    if not isinstance(values, list):
        raise ValueError(f"registry field must be a list: {field}")
    return data


def _atomic_dump(path: Path, data: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(dump(data, path), encoding="utf-8")
    temporary.replace(path)


def _frontmatter(path: Path) -> dict[str, Any] | None:
    try:
        data = frontmatter_metadata(path)
    except (OSError, UnicodeError, FrontmatterError):
        return None
    return data if isinstance(data, dict) else None


def _valid_sessions(value: object) -> bool:
    """Handle sessions using the declared repository contract."""
    return (
        isinstance(value, list)
        and len(value) == len(set(str(item) for item in value))
        and all(
            isinstance(item, str) and SESSION_PATTERN.fullmatch(item) for item in value
        )
    )


def _ignored(relative: Path) -> bool:
    """Handle ignored using the declared repository contract."""
    if relative.parts[:1] == (".carmadio_runtime",) or relative.parts[:2] == (
        ".carmadio",
        "runtime",
    ):
        return True
    ignored = {".git", ".cache", ".venv", "__pycache__", "dist"}
    return any(
        part in ignored or (part.startswith(".") and part not in {".github", ".carmadio"})
        for part in relative.parts
    )


def _digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _ledger_path(root: Path) -> Path:
    layout = discover_layout(root)
    return layout.structured_file(layout.project_state_root, "atoms.toml")


def _atom_diag(path: Path, message: str) -> Diagnostic:
    return Diagnostic("CARMADIO-E159", path, message)

"""Validate reusable Agent Skills against the selected DSET profile.

Parameters: skill roots and optional TOML trigger-case catalogs.
Effects: read-only validation; no files, installs, or hosted state are changed.
Errors: aggregated profile diagnostics identify the skill and failed rule.
"""

from __future__ import annotations

import ast
import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .toml_codec import TomlCodecError
from .toml_codec import loads as load_toml

# PROFILE_ID identifies the implementation profile enforced by this module.
PROFILE_ID = "agent-skills-v1"
# NAME_PATTERN defines portable skill directory and frontmatter names.
NAME_PATTERN = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
# MAX_NAME_CHARACTERS follows the open Agent Skills metadata contract.
MAX_NAME_CHARACTERS = 64
# MAX_DESCRIPTION_CHARACTERS follows the open Agent Skills metadata contract.
MAX_DESCRIPTION_CHARACTERS = 1024
# MAX_BODY_LINES bounds eagerly loaded skill instructions.
MAX_BODY_LINES = 500
# REQUIRED_CASE_KINDS defines the minimum routing Evaluation matrix.
REQUIRED_CASE_KINDS = (
    "should_trigger",
    "should_not_trigger",
    "ambiguous_routing",
)
# ALLOWED_ENTRIES bounds the reusable package surface.
ALLOWED_ENTRIES = {"SKILL.md", "agents", "assets", "references", "scripts"}
# FORBIDDEN_PORTABLE_FRAGMENTS catches machine-specific runtime assumptions.
FORBIDDEN_PORTABLE_FRAGMENTS = (
    "/Users/",
    "/home/",
    "/tmp/",
    "~/",
    "C:\\",
    "CODEX_HOME/skills",
    "CLAUDE_CONFIG_DIR/skills",
)


class SkillProfileError(ValueError):
    """Report one or more Agent Skills profile violations."""


@dataclass(frozen=True)
class SkillAuditSummary:
    """Summarize a successful read-only Agent Skills profile audit."""

    profile_id: str
    skill_count: int
    case_count: int
    status: str = "passed"


def audit_skill_catalog(
    skills_root: Path,
    *,
    expected_skills: set[str] | None = None,
    case_catalog: Path | None = None,
) -> SkillAuditSummary:
    """Validate one complete skill catalog and optional trigger-case matrix."""
    issues: list[str] = []
    skills = _skill_directories(skills_root, issues)
    actual = {skill.name for skill in skills}
    if expected_skills is not None and actual != expected_skills:
        issues.append(
            "public catalog mismatch: "
            f"expected={sorted(expected_skills)}, actual={sorted(actual)}"
        )
    for skill in skills:
        issues.extend(audit_skill_package(skill))
    case_count = 0
    if case_catalog is not None:
        case_count, case_issues = _audit_case_catalog(case_catalog, actual)
        issues.extend(case_issues)
    _raise_issues(issues)
    return SkillAuditSummary(PROFILE_ID, len(skills), case_count)


def audit_skill_package(skill: Path) -> list[str]:
    """Return deterministic profile issues for one reusable skill package."""
    issues = _filesystem_issues(skill)
    skill_file = skill / "SKILL.md"
    if not skill_file.is_file():
        return [*issues, f"{skill.name}: SKILL.md is missing"]
    try:
        text = skill_file.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as error:
        return [*issues, f"{skill.name}: SKILL.md is unreadable: {error}"]
    metadata, body, frontmatter_issues = _parse_frontmatter(skill, text)
    issues.extend(frontmatter_issues)
    issues.extend(_metadata_issues(skill, metadata))
    issues.extend(_instruction_issues(skill, body))
    issues.extend(_script_issues(skill))
    return issues


def _skill_directories(skills_root: Path, issues: list[str]) -> list[Path]:
    """Collect real skill directories in deterministic name order."""
    if skills_root.is_symlink() or not skills_root.is_dir():
        issues.append(f"skills root is missing or is a symlink: {skills_root}")
        return []
    return sorted(
        (
            path
            for path in skills_root.iterdir()
            if path.is_dir() and (path / "SKILL.md").is_file()
        ),
        key=lambda path: path.name,
    )


def _filesystem_issues(skill: Path) -> list[str]:
    """Return package-shape and symlink portability issues."""
    issues: list[str] = []
    if skill.is_symlink() or not skill.is_dir():
        return [f"{skill.name}: package must be a copied directory"]
    unexpected = sorted(
        path.name for path in skill.iterdir() if path.name not in ALLOWED_ENTRIES
    )
    if unexpected:
        issues.append(f"{skill.name}: unexpected package entries: {unexpected}")
    for path in skill.rglob("*"):
        if path.is_symlink():
            issues.append(f"{skill.name}: symlink is not portable: {path.name}")
    return issues


def _parse_frontmatter(skill: Path, text: str) -> tuple[dict[str, str], str, list[str]]:
    """Parse the required dependency-free YAML scalar subset."""
    lines = text.splitlines()
    if not lines or lines[0] != "---":
        return {}, text, [f"{skill.name}: YAML frontmatter is missing"]
    try:
        closing = lines.index("---", 1)
    except ValueError:
        return {}, text, [f"{skill.name}: YAML frontmatter is not closed"]
    metadata: dict[str, str] = {}
    issues: list[str] = []
    for line in lines[1:closing]:
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        if ":" not in line or line[:1].isspace():
            issues.append(f"{skill.name}: required metadata must use one-line scalars")
            continue
        key, raw_value = line.split(":", 1)
        metadata[key.strip()] = _unquote(raw_value.strip())
    return metadata, "\n".join(lines[closing + 1 :]), issues


def _unquote(value: str) -> str:
    if len(value) >= 2 and value[0] == value[-1] and value[0] in {'"', "'"}:
        return value[1:-1]
    return value


def _metadata_issues(skill: Path, metadata: dict[str, str]) -> list[str]:
    """Validate discovery name and what-and-when description fields."""
    issues: list[str] = []
    name = metadata.get("name", "")
    description = metadata.get("description", "")
    if name != skill.name or NAME_PATTERN.fullmatch(name) is None:
        issues.append(f"{skill.name}: name must match its kebab-case directory")
    if len(name) > MAX_NAME_CHARACTERS:
        issues.append(f"{skill.name}: name exceeds {MAX_NAME_CHARACTERS} characters")
    if not description or len(description) > MAX_DESCRIPTION_CHARACTERS:
        issues.append(f"{skill.name}: description is missing or too long")
    lowered = description.lower()
    if re.search(r"\buse (?:when|for|before|after|if|to)\b", lowered) is None:
        issues.append(f"{skill.name}: description must state when to use the skill")
    return issues


def _instruction_issues(skill: Path, body: str) -> list[str]:
    """Validate progressive disclosure and portable instruction text."""
    issues: list[str] = []
    if len(body.splitlines()) > MAX_BODY_LINES:
        issues.append(f"{skill.name}: SKILL.md body exceeds {MAX_BODY_LINES} lines")
    for fragment in FORBIDDEN_PORTABLE_FRAGMENTS:
        if fragment in body:
            issues.append(
                f"{skill.name}: machine-specific path is prohibited: {fragment}"
            )
    deep_reference = re.compile(r"(?:references|assets)/[^\s)`]+/[^\s)`]+")
    if deep_reference.search(body):
        issues.append(f"{skill.name}: reference chains must stay one level deep")
    return issues


def _script_issues(skill: Path) -> list[str]:
    """Validate every bundled portable Python helper."""
    scripts = skill / "scripts"
    if not scripts.exists():
        return []
    if scripts.is_symlink() or not scripts.is_dir():
        return [f"{skill.name}: scripts must be a real directory"]
    issues: list[str] = []
    for path in sorted(scripts.rglob("*.py")):
        issues.extend(_python_script_issues(skill.name, path))
    return issues


def _python_script_issues(skill_name: str, path: Path) -> list[str]:
    """Return syntax, documentation, and portability helper issues."""
    try:
        text = path.read_text(encoding="utf-8")
        tree = ast.parse(text, filename=str(path))
    except (OSError, UnicodeError, SyntaxError) as error:
        return [f"{skill_name}: invalid Python helper {path.name}: {error}"]
    issues: list[str] = []
    if ast.get_docstring(tree) is None:
        issues.append(
            f"{skill_name}: Python helper lacks a module docstring: {path.name}"
        )
    for fragment in FORBIDDEN_PORTABLE_FRAGMENTS:
        if fragment in text:
            issues.append(f"{skill_name}: helper contains nonportable path {fragment}")
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and _keyword_is_true(node, "shell"):
            issues.append(
                f"{skill_name}: helper uses subprocess shell=True: {path.name}"
            )
    return issues


def _keyword_is_true(call: ast.Call, name: str) -> bool:
    """Return whether a call passes one literal true keyword."""
    return any(
        keyword.arg == name
        and isinstance(keyword.value, ast.Constant)
        and keyword.value.value is True
        for keyword in call.keywords
    )


def _audit_case_catalog(path: Path, skills: set[str]) -> tuple[int, list[str]]:
    """Validate the complete provider-neutral trigger case catalog."""
    try:
        raw = load_toml(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, TomlCodecError) as error:
        return 0, [f"skill case catalog is unreadable: {path}: {error}"]
    if raw.get("profile_id") != PROFILE_ID:
        return 0, [f"skill case catalog must target {PROFILE_ID}"]
    raw_skills = raw.get("skills")
    if not isinstance(raw_skills, dict):
        return 0, ["skill case catalog requires a [skills] table"]
    issues: list[str] = []
    if set(raw_skills) != skills:
        issues.append(
            "skill case catalog mismatch: "
            f"expected={sorted(skills)}, actual={sorted(raw_skills)}"
        )
    count = 0
    for skill_name, value in sorted(raw_skills.items()):
        case_count, case_issues = _case_table_issues(str(skill_name), value)
        count += case_count
        issues.extend(case_issues)
    return count, issues


def _case_table_issues(skill_name: str, value: Any) -> tuple[int, list[str]]:
    """Validate the minimum three-way routing matrix for one skill."""
    if not isinstance(value, dict):
        return 0, [f"{skill_name}: case definition must be a TOML table"]
    issues: list[str] = []
    for kind in REQUIRED_CASE_KINDS:
        prompt = value.get(kind)
        if not isinstance(prompt, str) or not prompt.strip():
            issues.append(f"{skill_name}: missing non-empty {kind} case")
    expected = value.get("ambiguous_expected")
    if not isinstance(expected, str) or not expected.strip():
        issues.append(f"{skill_name}: ambiguous case requires an expected route")
    allowed = {*REQUIRED_CASE_KINDS, "ambiguous_expected"}
    unknown = sorted(set(value) - allowed)
    if unknown:
        issues.append(f"{skill_name}: unknown case fields: {unknown}")
    count = sum(isinstance(value.get(kind), str) for kind in REQUIRED_CASE_KINDS)
    return count, issues


def _raise_issues(issues: list[str]) -> None:
    if issues:
        raise SkillProfileError(
            f"{PROFILE_ID} failed with {len(issues)} issue(s):\n- "
            + "\n- ".join(issues)
        )

"""Read and write the repository's TOML-only structured-data carriers."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from .toml_codec import TomlCodecError, dumps, load as load_toml, loads as loads_toml

# STRUCTURED_SUFFIX is the only project-owned structured carrier suffix.
STRUCTURED_SUFFIX = ".toml"


class StructuredDataError(ValueError):
    """Report a non-TOML carrier or a value outside the portable TOML subset."""


def load(path: Path) -> dict[str, Any]:
    """Load one TOML carrier and reject compatibility-format suffixes."""
    _require_toml_path(path)
    try:
        return load_toml(path)
    except (OSError, UnicodeError, TomlCodecError) as error:
        raise StructuredDataError(str(error)) from error


def loads(text: str) -> dict[str, Any]:
    """Load TOML text through the same portable subset as file carriers."""
    try:
        return loads_toml(text)
    except TomlCodecError as error:
        raise StructuredDataError(str(error)) from error


def dump(data: Any, path: Path | None = None) -> str:
    """Render TOML and optionally verify the destination carrier suffix."""
    if path is not None:
        _require_toml_path(path)
    try:
        return dumps(data)
    except TomlCodecError as error:
        raise StructuredDataError(str(error)) from error


def write(path: Path, data: Any) -> None:
    """Write one TOML carrier after creating its parent directory."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(dump(data, path), encoding="utf-8")


def _require_toml_path(path: Path) -> None:
    """Reject every project-owned structured carrier suffix except TOML."""
    if path.suffix.lower() != STRUCTURED_SUFFIX:
        raise StructuredDataError(
            f"project-owned structured carrier must use TOML: {path.name}"
        )

"""Provide DSET temp paths behavior."""

from __future__ import annotations

import os
import tempfile
from pathlib import Path


def scratch_root(
    *,
    platform_name: str | None = None,
    allow_test_override: bool = True,
) -> Path:
    """Return the host scratch root without trusting a POSIX ambient TMPDIR."""

    if allow_test_override and os.environ.get("DSET_TESTING") == "1":
        test_root = os.environ.get("DSET_TEST_SCRATCH_ROOT")
        if test_root:
            root = Path(test_root).resolve()
            if not root.is_dir():
                raise FileNotFoundError(
                    f"configured DSET test scratch root is unavailable: {root}"
                )
            return root

    platform = os.name if platform_name is None else platform_name
    if platform == "posix":
        return Path("/tmp")
    if platform == "nt":
        return Path(tempfile.gettempdir()).resolve()
    raise OSError(f"unsupported temporary-directory platform: {platform}")


def temporary_directory(
    *,
    prefix: str = "dset-",
    suffix: str | None = None,
) -> tempfile.TemporaryDirectory[str]:
    """Create a fail-loud DSET scratch directory under the host temp root."""

    root = scratch_root()
    if not root.is_dir():
        raise FileNotFoundError(f"temporary root is unavailable: {root}")
    return tempfile.TemporaryDirectory(
        suffix=suffix,
        prefix=prefix,
        dir=root,
        ignore_cleanup_errors=False,
    )

"""Small, deterministic TOML codec for CARMADIO-owned artifacts.

The project supports Python 3.10 without a runtime dependency.  Python 3.11
and later use :mod:`tomllib`; the fallback deliberately implements the stable
subset emitted by :func:`dumps` (tables, array-of-tables, scalars, and arrays).
It is not a permissive compatibility shim: inputs outside that subset fail
with a useful error instead of being reinterpreted.
"""

from __future__ import annotations

import json
import math
import re
from collections.abc import Mapping, Sequence
from pathlib import Path
from typing import Any

# _BARE_KEY validates bare key; this module owns the accepted syntax.
_BARE_KEY = re.compile(r"^[A-Za-z0-9_-]+$")
# _INTEGER validates integer; this module owns the accepted syntax.
_INTEGER = re.compile(r"^[+-]?[0-9][0-9_]*$")
# _FLOAT validates float; this module owns the accepted syntax.
_FLOAT = re.compile(r"^[+-]?(?:[0-9][0-9_]*\.[0-9_]+|[0-9][0-9_]*[eE][+-]?[0-9_]+)$")

try:  # pragma: no cover - exercised on Python 3.11+ by the standard library.
    import tomllib as _tomllib  # type: ignore[import-not-found]
except ModuleNotFoundError:  # pragma: no cover - exercised on Python 3.10.
    _tomllib = None


class TomlCodecError(ValueError):
    """Raised when a value is outside DSET's portable TOML subset."""


def load(path: Path) -> dict[str, Any]:
    """Load load using the declared repository contract."""
    return loads(path.read_text(encoding="utf-8"))


def loads(text: str) -> dict[str, Any]:
    """Handle loads using the declared repository contract."""
    if _tomllib is not None:
        try:
            value = _tomllib.loads(text)
        except _tomllib.TOMLDecodeError as error:
            raise TomlCodecError(str(error)) from error
        if not isinstance(value, dict):
            raise TomlCodecError("TOML document root must be a table")
        return value
    return _loads_subset(text)


def dumps(value: Mapping[str, Any]) -> str:
    """Handle dumps using the declared repository contract."""
    if not isinstance(value, Mapping):
        raise TomlCodecError("TOML document root must be a mapping")
    lines: list[str] = []
    _emit_table(dict(value), (), lines, header=False)
    return "\n".join(lines).rstrip() + "\n"


def _emit_table(
    table: Mapping[str, Any],
    path: tuple[str, ...],
    lines: list[str],
    *,
    header: bool,
) -> None:
    """Emit table using the declared repository contract."""
    _require_string_keys(table, path)
    if header:
        if lines and lines[-1] != "":
            lines.append("")
        lines.append("[" + ".".join(_format_key(key) for key in path) + "]")

    child_tables: list[tuple[str, Mapping[str, Any]]] = []
    array_tables: list[tuple[str, Sequence[Any]]] = []
    for key, item in table.items():
        if isinstance(item, Mapping) and item:
            child_tables.append((key, item))
        elif _is_array_of_tables(item):
            array_tables.append((key, item))
        else:
            lines.append(f"{_format_key(key)} = {_format_value(item, path + (key,))}")

    for key, child in child_tables:
        _emit_table(child, path + (key,), lines, header=True)
    for key, records in array_tables:
        for record in records:
            if lines and lines[-1] != "":
                lines.append("")
            table_path = path + (key,)
            table_name = ".".join(_format_key(item) for item in table_path)
            lines.append(f"[[{table_name}]]")
            assert isinstance(record, Mapping)
            _emit_table_body(record, table_path, lines)


def _emit_table_body(
    table: Mapping[str, Any], path: tuple[str, ...], lines: list[str]
) -> None:
    """Emit table body using the declared repository contract."""
    _require_string_keys(table, path)
    child_tables: list[tuple[str, Mapping[str, Any]]] = []
    array_tables: list[tuple[str, Sequence[Any]]] = []
    for key, item in table.items():
        if isinstance(item, Mapping) and item:
            child_tables.append((key, item))
        elif _is_array_of_tables(item):
            array_tables.append((key, item))
        else:
            lines.append(f"{_format_key(key)} = {_format_value(item, path + (key,))}")
    for key, child in child_tables:
        _emit_table(child, path + (key,), lines, header=True)
    for key, records in array_tables:
        for record in records:
            if lines and lines[-1] != "":
                lines.append("")
            table_path = path + (key,)
            table_name = ".".join(_format_key(item) for item in table_path)
            lines.append(f"[[{table_name}]]")
            assert isinstance(record, Mapping)
            _emit_table_body(record, table_path, lines)


def _format_value(value: Any, path: tuple[str, ...]) -> str:
    """Format value using the declared repository contract."""
    if value is None:
        raise TomlCodecError(f"{_render_path(path)}: null is not representable in TOML")
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            raise TomlCodecError(
                f"{_render_path(path)}: non-finite floats are not supported"
            )
        return repr(value)
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, Mapping):
        if value:
            raise TomlCodecError(
                f"{_render_path(path)}: nested mappings must be emitted as tables"
            )
        return "{}"
    if isinstance(value, Sequence) and not isinstance(value, (bytes, bytearray)):
        if _is_array_of_tables(value):
            raise TomlCodecError(
                f"{_render_path(path)}: array-of-tables must be emitted as tables"
            )
        if any(isinstance(item, (Mapping, list, tuple)) for item in value):
            raise TomlCodecError(
                f"{_render_path(path)}: nested arrays and mixed mappings are "
                "unsupported"
            )
        _require_homogeneous_scalars(value, path)
        return "[" + ", ".join(_format_value(item, path) for item in value) + "]"
    raise TomlCodecError(
        f"{_render_path(path)}: {type(value).__name__} is not representable in TOML"
    )


def _is_array_of_tables(value: Any) -> bool:
    """Handle array of tables using the declared repository contract."""
    return (
        isinstance(value, Sequence)
        and not isinstance(value, (str, bytes, bytearray))
        and bool(value)
        and all(isinstance(item, Mapping) for item in value)
    )


def _require_homogeneous_scalars(value: Sequence[Any], path: tuple[str, ...]) -> None:
    kinds = {type(item) for item in value}
    if len(kinds) > 1:
        raise TomlCodecError(
            f"{_render_path(path)}: TOML array values must share one type"
        )


def _require_string_keys(value: Mapping[str, Any], path: tuple[str, ...]) -> None:
    for key in value:
        if not isinstance(key, str) or not key:
            raise TomlCodecError(
                f"{_render_path(path)}: TOML table keys must be non-empty strings"
            )


def _format_key(key: str) -> str:
    return key if _BARE_KEY.fullmatch(key) else json.dumps(key, ensure_ascii=False)


def _render_path(path: tuple[str, ...]) -> str:
    return ".".join(path) if path else "<root>"


def _loads_subset(text: str) -> dict[str, Any]:
    """Handle subset using the declared repository contract."""
    root: dict[str, Any] = {}
    current: dict[str, Any] = root
    for line_number, raw in enumerate(text.splitlines(), start=1):
        line = _strip_comment(raw).strip()
        if not line:
            continue
        if line.startswith("[") and line.endswith("]"):
            array = line.startswith("[[") and line.endswith("]]")
            raw_path = line[2:-2] if array else line[1:-1]
            keys = [
                _parse_key(piece.strip(), line_number) for piece in raw_path.split(".")
            ]
            current = _select_table(root, keys, array, line_number)
            continue
        key_raw, separator, raw_value = line.partition("=")
        if not separator:
            raise TomlCodecError(f"line {line_number}: expected key = value")
        key = _parse_key(key_raw.strip(), line_number)
        if key in current:
            raise TomlCodecError(f"line {line_number}: duplicate key {key}")
        current[key] = _parse_value(raw_value.strip(), line_number)
    return root


def _select_table(
    root: dict[str, Any], keys: list[str], array: bool, line_number: int
) -> dict[str, Any]:
    """Select table using the declared repository contract."""
    if not keys or any(not key for key in keys):
        raise TomlCodecError(f"line {line_number}: table name is empty")
    current = root
    for key in keys[:-1]:
        existing = current.get(key)
        if existing is None:
            nested: dict[str, Any] = {}
            current[key] = nested
            current = nested
        elif isinstance(existing, dict):
            current = existing
        else:
            raise TomlCodecError(f"line {line_number}: table path conflicts with {key}")
    final = keys[-1]
    if array:
        existing = current.setdefault(final, [])
        if not isinstance(existing, list):
            raise TomlCodecError(
                f"line {line_number}: array table conflicts with {final}"
            )
        record: dict[str, Any] = {}
        existing.append(record)
        return record
    existing = current.setdefault(final, {})
    if not isinstance(existing, dict):
        raise TomlCodecError(f"line {line_number}: table conflicts with {final}")
    return existing


def _parse_key(value: str, line_number: int) -> str:
    """Parse key using the declared repository contract."""
    if _BARE_KEY.fullmatch(value):
        return value
    if value.startswith('"') and value.endswith('"'):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError as error:
            raise TomlCodecError(f"line {line_number}: invalid quoted key") from error
        if isinstance(parsed, str) and parsed:
            return parsed
    raise TomlCodecError(f"line {line_number}: invalid key {value!r}")


def _parse_value(value: str, line_number: int) -> Any:
    """Parse value using the declared repository contract."""
    if value in {"true", "false"}:
        return value == "true"
    if value.startswith('"') and value.endswith('"'):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError as error:
            raise TomlCodecError(f"line {line_number}: invalid string") from error
        if isinstance(parsed, str):
            return parsed
    if _INTEGER.fullmatch(value):
        return int(value.replace("_", ""))
    if _FLOAT.fullmatch(value):
        return float(value.replace("_", ""))
    if value.startswith("[") and value.endswith("]"):
        inner = value[1:-1].strip()
        if not inner:
            return []
        return [_parse_value(item, line_number) for item in _split_array(inner)]
    if value == "{}":
        return {}
    raise TomlCodecError(f"line {line_number}: unsupported TOML value {value!r}")


def _split_array(value: str) -> list[str]:
    """Handle array using the declared repository contract."""
    parts: list[str] = []
    quote = False
    escaped = False
    start = 0
    for index, character in enumerate(value):
        if quote and character == "\\" and not escaped:
            escaped = True
            continue
        if character == '"' and not escaped:
            quote = not quote
        if character == "," and not quote:
            parts.append(value[start:index].strip())
            start = index + 1
        escaped = False
    parts.append(value[start:].strip())
    if not all(parts):
        raise TomlCodecError("invalid empty array item")
    return parts


def _strip_comment(value: str) -> str:
    """Handle comment using the declared repository contract."""
    quote = False
    escaped = False
    for index, character in enumerate(value):
        if quote and character == "\\" and not escaped:
            escaped = True
            continue
        if character == '"' and not escaped:
            quote = not quote
        if character == "#" and not quote:
            return value[:index]
        escaped = False
    return value

"""Provide DSET traceability behavior."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from .artifact_records import build_atomic_artifact_route_index
from .layout import discover_layout
from .lineage import build_relation_index
from .structured_data import dump, load


def build_traceability(root: Path) -> dict[str, Any]:
    """Build traceability using the declared repository contract."""
    root = root.resolve()
    layout = discover_layout(root)
    history = load(layout.history_path)
    changes = [_change_entry(layout, path) for path in _change_paths(layout)]
    changes = [item for item in changes if item is not None]
    changes.sort(key=lambda item: item["id"])
    return {
        "schema_version": "1.4" if layout.layered else 1.2,
        "repository": history["repository"],
        "changes": changes,
        "artifact_routes": build_atomic_artifact_route_index(root),
        "relations": build_relation_index(root),
    }


def _change_paths(layout: Any) -> list[Path]:
    """Enumerate active and archived Change directories once."""
    candidates: list[Path] = []
    for change_root in layout.active_change_roots:
        if change_root.is_dir():
            candidates.extend(
                path
                for path in change_root.iterdir()
                if path.is_dir() and path.name != "archive"
            )
    for archive in layout.archive_change_roots:
        if archive.is_dir():
            candidates.extend(path for path in archive.iterdir() if path.is_dir())
    return sorted(candidates, key=lambda item: item.name)


def _change_entry(layout: Any, path: Path) -> dict[str, Any] | None:
    """Render one Change manifest and its evidence inventory."""
    manifest = layout.structured_file(path, "change.yaml")
    if not manifest.is_file():
        return None
    data = load(manifest)
    pr = data.get("pull_request", {})
    entry = {
        "id": data["id"],
        "status": data["status"],
        "packages": sorted(data.get("packages", [])),
        "requirements": sorted(data.get("requirements", [])),
        "tests": sorted(data.get("tests", [])),
        "evals": sorted(data.get("evals", [])),
        "intake": sorted(data.get("intake", [])),
        "decisions": sorted(data.get("decisions", data.get("adrs", []))),
        "contracts": sorted(data.get("contracts", [])),
        "stories": sorted(data.get("stories", [])),
        "outcomes": sorted(data.get("outcomes", [])),
        "pull_request": pr.get("url", "pending"),
        "evidence": _evidence_names(path / "proofs"),
    }
    if layout.layered:
        entry.update(_layered_change_fields(data))
    return entry


def _evidence_names(root: Path) -> list[str]:
    """List non-hub proof carrier names under one Change."""
    if not root.is_dir():
        return []
    return [
        item.name
        for item in sorted(root.rglob("*"))
        if item.is_file() and item.name != "README.md"
    ]


def _layered_change_fields(data: dict[str, Any]) -> dict[str, Any]:
    """Render the fields present only in layered Change manifests."""
    target = data.get("target")
    rendered_target = _render_target(target) if isinstance(target, dict) else target
    dependencies = sorted(
        data.get("dependencies", []),
        key=lambda item: (
            str(item.get("change_id", "")) if isinstance(item, dict) else ""
        ),
    )
    return {
        "slug": data.get("slug"),
        "primary_layer": data.get("primary_layer"),
        "affected_layers": sorted(data.get("affected_layers", [])),
        "target": rendered_target,
        "workspace": data.get("workspace"),
        "dependencies": dependencies,
    }


def _render_target(target: dict[str, Any]) -> dict[str, Any]:
    """Normalize the work-area list of a layered Change target."""
    work_areas = target.get("work_areas")
    if isinstance(work_areas, list) and all(
        isinstance(item, str) for item in work_areas
    ):
        work_areas = sorted(work_areas)
    return {"repository": target.get("repository"), "work_areas": work_areas}


def rendered_traceability(root: Path) -> str:
    """Handle traceability using the declared repository contract."""
    path = discover_layout(root).traceability_path
    return dump(build_traceability(root), path)


def trace_is_fresh(root: Path) -> bool:
    """Handle is fresh using the declared repository contract."""
    path = discover_layout(root).traceability_path
    return path.is_file() and path.read_text(encoding="utf-8") == rendered_traceability(
        root
    )


def write_traceability(root: Path) -> Path:
    """Write traceability using the declared repository contract."""
    path = discover_layout(root).traceability_path
    content = rendered_traceability(root)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(content, encoding="utf-8")
    temporary.replace(path)
    return path

