#!/usr/bin/env python3
"""Historical preservation verifier for a META/GOV atomic migration replay.

Invocation: ``python dset_verify_meta_gov_migration.py [ROOT] [--expected-count N]``.
ROOT defaults to the repository containing this completed tool. It compares the
current atomic files in ``.carmadio/101_layer_meta`` and ``.carmadio/102_layer_gov``
with that root's ``HEAD`` versions, checking paths, IDs, protected relations,
original body prefixes, YAML carrier format, and frontmatter retention. The
default expected count is 319. It writes nothing, exits 0 on success and 1 on
any preservation failure. This bounded tool is outside active imports and CLI.
"""

from __future__ import annotations

import argparse
import re
import subprocess
import sys
from pathlib import Path
from typing import Any

sys.dont_write_bytecode = True

REPO = Path(__file__).resolve().parents[4]
sys.path.insert(0, str(REPO))

from dset_toolchain.frontmatter import parse  # noqa: E402

ROOT_PREFIXES = (
    ".carmadio/101_layer_meta/",
    ".carmadio/102_layer_gov/",
)
VOCAB = {
    "layer:meta": {
        "artifact-model",
        "assurance",
        "authority",
        "external-boundary",
        "governance-surface",
        "interaction",
        "lifecycle",
        "profile",
        "scope",
        "self-hosting",
        "topology",
    },
    "layer:gov": {
        "artifact-catalog",
        "assurance",
        "carrier-format",
        "external-boundary",
        "interaction",
        "layout",
        "lifecycle",
        "methodology",
        "priority",
        "provenance",
        "relation-model",
        "runtime",
        "settings",
        "subject-scope",
    },
}
RETAINED = {
    "artifact_type",
    "artifact_subtype",
    "artifact_id",
    "scope_path",
    "subject_scopes",
    "priority",
    "llm_session_ids",
    "relation_kind",
    "endpoints",
    "relations",
}


def run(*args: str) -> str:
    return subprocess.run(
        args,
        cwd=REPO,
        check=True,
        text=True,
        capture_output=True,
    ).stdout


def head_paths() -> list[str]:
    paths = run("git", "ls-tree", "-r", "--name-only", "HEAD").splitlines()
    return sorted(
        path
        for path in paths
        if path.endswith(".md") and path.startswith(ROOT_PREFIXES)
    )


def current_paths() -> list[str]:
    return sorted(
        str(path.relative_to(REPO))
        for prefix in ROOT_PREFIXES
        for path in (REPO / prefix).rglob("*.md")
    )


def head_text(path: str) -> str:
    return run("git", "show", f"HEAD:{path}")


def frontmatter_payload(text: str) -> str:
    return text.split("---", 2)[1]


def raw_blocks(raw: str) -> dict[str, str]:
    lines = raw.splitlines(keepends=True)
    starts = [
        index
        for index, line in enumerate(lines)
        if line and not line[0].isspace() and re.match(r"^[A-Za-z0-9_-]+:", line)
    ]
    result: dict[str, str] = {}
    for offset, start in enumerate(starts):
        end = starts[offset + 1] if offset + 1 < len(starts) else len(lines)
        key = lines[start].split(":", 1)[0].strip()
        result[key] = "".join(lines[start:end])
    return result


def relation_signature(metadata: dict[str, Any]) -> tuple[Any, Any, Any]:
    return (
        metadata.get("relation_kind"),
        metadata.get("endpoints"),
        metadata.get("relations"),
    )


def main() -> int:
    """Verify preservation invariants for the selected historical replay root."""
    global REPO
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", nargs="?", type=Path, default=REPO)
    parser.add_argument("--expected-count", type=int, default=319)
    arguments = parser.parse_args()
    REPO = arguments.root.resolve()
    before_paths = head_paths()
    after_paths = current_paths()
    issues = _path_issues(before_paths, after_paths, arguments.expected_count)
    before_ids, after_ids = _verify_paths(after_paths, issues)
    _verify_id_sets(before_ids, after_ids, issues)
    return _report(issues, len(after_paths))


def _path_issues(before: list[str], after: list[str], expected: int) -> list[str]:
    issues: list[str] = []
    if before != after:
        issues.append("atomic path set changed")
    if len(after) != expected:
        issues.append(f"expected {expected} atoms, found {len(after)}")
    return issues


def _verify_paths(paths: list[str], issues: list[str]) -> tuple[set[str], set[str]]:
    before_ids: set[str] = set()
    after_ids: set[str] = set()
    for path in paths:
        _verify_path(path, issues, before_ids, after_ids)
    return before_ids, after_ids


def _verify_path(
    path: str, issues: list[str], before_ids: set[str], after_ids: set[str]
) -> None:
    before_text = head_text(path)
    after_text = (REPO / path).read_text(encoding="utf-8")
    before = parse(before_text)
    after = parse(after_text)
    if before is None or after is None:
        issues.append(f"{path}: missing frontmatter")
        return
    before_meta, before_body, _ = before
    after_meta, after_body, after_format = after

    artifact_id = str(after_meta.get("artifact_id", ""))
    before_ids.add(str(before_meta.get("artifact_id", "")))
    after_ids.add(artifact_id)

    _verify_protected(
        path, before_meta, after_meta, before_body, after_body, after_format, issues
    )

    expected_scope = "layer:meta" if path.startswith(ROOT_PREFIXES[0]) else "layer:gov"
    if after_meta.get("scope_path") != expected_scope:
        issues.append(f"{path}: invalid scope_path")

    _verify_subjects(path, after_meta, expected_scope, issues)
    _verify_payload(path, before_text, after_text, after_body, issues)


def _verify_protected(
    path: str,
    before: dict[str, Any],
    after: dict[str, Any],
    before_body: str,
    after_body: str,
    fmt: str,
    issues: list[str],
) -> None:
    for key in (
        "artifact_type",
        "artifact_subtype",
        "artifact_id",
        "priority",
        "llm_session_ids",
    ):
        if before.get(key) != after.get(key):
            issues.append(f"{path}: protected property changed: {key}")
    if relation_signature(before) != relation_signature(after):
        issues.append(f"{path}: relations or endpoints changed")
    if not after_body.startswith(before_body):
        issues.append(f"{path}: original body is not an exact prefix")
    if fmt != "yaml":
        issues.append(f"{path}: frontmatter is not YAML")


def _verify_subjects(
    path: str, metadata: dict[str, Any], scope: str, issues: list[str]
) -> None:
    subjects, artifact_type = (
        metadata.get("subject_scopes"),
        str(metadata.get("artifact_type", "")),
    )
    if artifact_type == "evidence_record":
        if subjects not in (None, []):
            issues.append(f"{path}: Evidence Record subject scope must be omitted")
    elif not isinstance(subjects, list) or not subjects:
        issues.append(f"{path}: subject_scopes required")
    elif artifact_type != "analysis_report" and len(subjects) != 1:
        issues.append(f"{path}: exactly one subject scope required")
    elif len(subjects) != len(set(subjects)):
        issues.append(f"{path}: duplicate subject scope")
    elif any(subject not in VOCAB[scope] for subject in subjects):
        issues.append(f"{path}: unregistered subject scope")


def _verify_payload(
    path: str, before: str, after: str, body: str, issues: list[str]
) -> None:

    payload = frontmatter_payload(after)
    if '"' in payload or "'" in payload:
        issues.append(f"{path}: quoted frontmatter value")
    if re.search(r":\s*(?:\[\]|\{\}|\[|\{)", payload):
        issues.append(f"{path}: inline collection")
    removed = {
        key: value
        for key, value in raw_blocks(frontmatter_payload(before)).items()
        if key not in RETAINED
    }
    if (
        removed
        and "## Historical frontmatter metadata\n\n```yaml\n"
        + "".join(removed.values())
        + "```"
        not in body
    ):
        issues.append(f"{path}: removed metadata not retained exactly")


def _verify_id_sets(
    before_ids: set[str], after_ids: set[str], issues: list[str]
) -> None:
    if before_ids != after_ids or "" in before_ids or "" in after_ids:
        issues.append("artifact ID set changed or contains an empty ID")


def _report(issues: list[str], count: int) -> int:
    if issues:
        print("\n".join(issues))
        return 1
    print(f"migration-verification-ok: {count} atoms, IDs/relations/bodies preserved")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Operation and plan models shared by active migration recipes."""

from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from pathlib import Path


class MigrationError(RuntimeError):
    """A bounded migration cannot proceed without guessing or data loss."""


@dataclass(frozen=True)
class WriteOperation:
    """One exact file replacement or creation."""

    path: Path
    before_sha256: str | None
    content: bytes
    reason: str


@dataclass(frozen=True)
class DeleteOperation:
    """One exact deletion after its replacement has been staged."""

    path: Path
    before_sha256: str
    reason: str


@dataclass(frozen=True)
class MigrationPlan:
    """A complete fail-closed set of carrier operations."""

    root: Path
    writes: tuple[WriteOperation, ...]
    deletes: tuple[DeleteOperation, ...]

    def digest(self) -> str:
        """Bind one preview to the exact relative operations and bytes."""
        payload = {
            "writes": [_write_digest_record(self.root, item) for item in self.writes],
            "deletes": [
                _delete_digest_record(self.root, item) for item in self.deletes
            ],
        }
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode()
        return hashlib.sha256(encoded).hexdigest()

    def summary(self) -> str:
        """Render the stable human-readable dry-run summary."""
        lines = ["META/GOV carrier migration plan", f"root: {self.root}"]
        lines.extend((f"writes: {len(self.writes)}", f"deletes: {len(self.deletes)}"))
        lines.append(f"plan-digest: {self.digest()}")
        lines.extend(_write_summary(self.root, self.writes))
        lines.extend(_delete_summary(self.root, self.deletes))
        return "\n".join(lines)


def _write_digest_record(root: Path, item: WriteOperation) -> dict[str, str | None]:
    return {
        "path": item.path.relative_to(root).as_posix(),
        "before": item.before_sha256,
        "after": hashlib.sha256(item.content).hexdigest(),
        "reason": item.reason,
    }


def _delete_digest_record(root: Path, item: DeleteOperation) -> dict[str, str]:
    return {
        "path": item.path.relative_to(root).as_posix(),
        "before": item.before_sha256,
        "reason": item.reason,
    }


def _write_summary(root: Path, operations: tuple[WriteOperation, ...]) -> list[str]:
    return [
        f"{'CREATE' if item.before_sha256 is None else 'UPDATE'} "
        f"{item.path.relative_to(root).as_posix()} — {item.reason}"
        for item in operations
    ]


def _delete_summary(root: Path, operations: tuple[DeleteOperation, ...]) -> list[str]:
    return [
        f"DELETE {item.path.relative_to(root).as_posix()} — {item.reason}"
        for item in operations
    ]

"""Digest, regular-file, and exact-preimage safeguards for migrations."""

from __future__ import annotations

import hashlib
from pathlib import Path

from .models import MigrationError, MigrationPlan


def sha256(content: bytes) -> str:
    """Return the stable digest used for migration preimages."""
    return hashlib.sha256(content).hexdigest()


def read_regular_file(path: Path) -> bytes:
    """Read one non-symlink regular file or raise a safety error."""
    if path.is_symlink():
        raise MigrationError(f"symlink is outside the migration contract: {path}")
    if not path.is_file():
        raise MigrationError(f"expected a regular file: {path}")
    return path.read_bytes()


def assert_preimages(plan: MigrationPlan) -> None:
    """Refuse a plan whose source bytes changed after preflight."""
    validate_plan(plan)
    for operation in plan.writes:
        _assert_write_preimage(operation.path, operation.before_sha256)
    for operation in plan.deletes:
        _assert_delete_preimage(operation.path, operation.before_sha256)


def _assert_write_preimage(path: Path, digest: str | None) -> None:
    if digest is None:
        if path.exists():
            raise MigrationError(f"new target appeared after planning: {path}")
        return
    if sha256(read_regular_file(path)) != digest:
        raise MigrationError(f"file changed after planning: {path}")


def _assert_delete_preimage(path: Path, digest: str) -> None:
    if sha256(read_regular_file(path)) != digest:
        raise MigrationError(f"file changed after planning: {path}")


def validate_plan(plan: MigrationPlan) -> None:
    """Enforce containment and collision rules for every migration recipe."""
    root = plan.root.resolve()
    if not root.is_dir():
        raise MigrationError(f"migration root is not a directory: {root}")
    write_paths = [item.path for item in plan.writes]
    delete_paths = [item.path for item in plan.deletes]
    resolved_writes = _validated_paths(root, write_paths, "write")
    resolved_deletes = _validated_paths(root, delete_paths, "delete")
    overlap = set(resolved_writes) & set(resolved_deletes)
    if overlap:
        raise MigrationError(f"write/delete collision: {sorted(overlap)}")


def _validated_paths(root: Path, paths: list[Path], kind: str) -> list[Path]:
    resolved = [_contained_path(root, path) for path in paths]
    if len(resolved) != len(set(resolved)):
        raise MigrationError(f"duplicate {kind} target in migration plan")
    return resolved


def _contained_path(root: Path, path: Path) -> Path:
    if not path.is_absolute():
        raise MigrationError(f"migration target is not absolute: {path}")
    resolved = path.resolve(strict=False)
    try:
        relative = resolved.relative_to(root)
    except ValueError as error:
        raise MigrationError(f"migration target escapes root: {path}") from error
    if not relative.parts:
        raise MigrationError(f"migration target is the repository root: {path}")
    return resolved

"""Transactional staging, replacement, rollback, and cleanup for migrations."""

from __future__ import annotations

import os
from collections.abc import Callable
from contextlib import suppress
from pathlib import Path

from .models import MigrationError, MigrationPlan
from .safety import assert_preimages, sha256

StagedValidator = Callable[[MigrationPlan, dict[Path, Path]], None]


def apply_transaction(
    plan: MigrationPlan,
    validate_staged: StagedValidator,
    verify: Callable[[Path], None],
) -> None:
    """Stage, apply, verify, and roll back a complete plan on any failure."""
    assert_preimages(plan)
    originals = _capture_originals(plan)
    staging_root = _create_staging_root(plan.root)
    try:
        staged = _stage_writes(plan, staging_root)
        validate_staged(plan, staged)
        _replace_and_verify(plan, staged, verify)
    except Exception as error:
        raise _rollback_error(error, originals) from error
    finally:
        _cleanup_staging(staging_root)


def _capture_originals(plan: MigrationPlan) -> dict[Path, bytes | None]:
    originals = {
        item.path: item.path.read_bytes() if item.path.exists() else None
        for item in plan.writes
    }
    originals.update({item.path: item.path.read_bytes() for item in plan.deletes})
    return originals


def _create_staging_root(root: Path) -> Path:
    runtime_root = root / ".carmadio_runtime" / "migrations"
    runtime_root.mkdir(parents=True, exist_ok=True)
    staging_root = runtime_root / f"dset-meta-gov-carriers-{os.getpid()}"
    staging_root.mkdir()
    return staging_root


def _stage_writes(plan: MigrationPlan, root: Path) -> dict[Path, Path]:
    staged: dict[Path, Path] = {}
    for index, operation in enumerate(plan.writes):
        path = root / f"{index:04d}.stage"
        path.write_bytes(operation.content)
        _validate_staged(path, operation.path, operation.content)
        staged[operation.path] = path
    return staged


def _validate_staged(staged: Path, target: Path, content: bytes) -> None:
    if sha256(staged.read_bytes()) != sha256(content):
        raise MigrationError(f"staging digest mismatch: {target}")
    if os.stat(staged).st_dev != os.stat(target.parent).st_dev:
        raise MigrationError(
            f"migration staging and target are on different filesystems: {target}"
        )


def _replace_and_verify(
    plan: MigrationPlan, staged: dict[Path, Path], verify: Callable[[Path], None]
) -> None:
    for operation in plan.writes:
        operation.path.parent.mkdir(parents=True, exist_ok=True)
        os.replace(staged[operation.path], operation.path)
    for operation in plan.deletes:
        operation.path.unlink()
    verify(plan.root)


def _rollback_error(
    error: Exception, originals: dict[Path, bytes | None]
) -> MigrationError:
    failures = _restore_originals(originals)
    suffix = (
        f"; rollback failures: {'; '.join(failures)}"
        if failures
        else "; all touched files rolled back"
    )
    return MigrationError(f"migration failed: {error}{suffix}")


def _restore_originals(originals: dict[Path, bytes | None]) -> list[str]:
    failures: list[str] = []
    for path, content in reversed(tuple(originals.items())):
        try:
            if content is None:
                path.unlink(missing_ok=True)
            else:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes(content)
        except OSError as error:
            failures.append(f"{path}: {error}")
    return failures


def _cleanup_staging(root: Path) -> None:
    for path in root.glob("*"):
        path.unlink()
    root.rmdir()
    with suppress(OSError):
        root.parent.rmdir()

#!/usr/bin/env python3
"""Move CARMADIO carriers into the recursive eight-role directory layout.

Usage:
    python migrate_carmadio_role_layout.py
    python migrate_carmadio_role_layout.py --apply --expect-plan-digest SHA256
    python migrate_carmadio_role_layout.py --check

Preview is the default. Apply is bound to the exact preview digest, stages
byte-identical destinations under the script-owned runtime directory, rejects
unknown carriers and collisions, and restores every source if publication or
postcondition verification fails. The migration changes paths only; governed
carrier bytes and filenames are preserved.
