class RoleLayoutError(RuntimeError):
    """The role-layout migration cannot proceed safely."""


@dataclass(frozen=True)
class Move:
    """One byte-preserving carrier move."""

    source: Path
    target: Path
    sha256: str


@dataclass(frozen=True)
class Plan:
    """One complete deterministic migration plan."""

    moves: tuple[Move, ...]
    trash: tuple[tuple[Path, str], ...]
    rename_methodology: bool


def _digest(content: bytes) -> str:
    """Return one lowercase SHA-256 digest."""
    return hashlib.sha256(content).hexdigest()


def _regular_bytes(path: Path) -> bytes:
    """Read a regular non-symlink file or stop."""
    if path.is_symlink() or not path.is_file():
        raise RoleLayoutError(f"carrier is not a regular file: {path}")
    return path.read_bytes()


def _metadata(path: Path, content: bytes) -> dict[str, Any]:
    """Read supported Markdown or TOML metadata without changing bytes."""
    if path.suffix.lower() == ".md":
        try:
            parsed = parse_frontmatter(content.decode("utf-8"))
        except (UnicodeError, FrontmatterError) as error:
            message = f"invalid Markdown carrier: {path}: {error}"
            raise RoleLayoutError(message) from error
        return {} if parsed is None else parsed[0]
    if path.suffix.lower() == ".toml":
        try:
            return tomllib.loads(content.decode("utf-8"))
        except (UnicodeError, tomllib.TOMLDecodeError) as error:
            raise RoleLayoutError(f"invalid TOML carrier: {path}: {error}") from error
    return {}


def _role_for_version(subtype: str | None, path: Path) -> str:
    """Classify one legacy Version carrier by its direct subtype."""
    if subtype in DELIVERY_VERSION_SUBTYPES:
        return "06_DELIVERY"
    if subtype in ASSURANCE_VERSION_SUBTYPES:
        return "05_ASSURANCE"
    if subtype in OPS_VERSION_SUBTYPES:
        return "08_OPS"
    raise RoleLayoutError(f"unknown Version subtype in {path}: {subtype!r}")


def _role_for_plan(subtype: str | None, path: Path) -> str:
    """Classify one legacy Plan carrier without treating plan as a role."""
    if subtype in {"test_plan", "evaluation_plan", "verification_plan"}:
        return "05_ASSURANCE"
    if subtype in {"implementation_plan", "work_plan"}:
        return "04_METHOD"
    if subtype == "release_plan":
        return "06_DELIVERY"
    return _role_from_name(path)


def _role_for_projection(subtype: str | None, path: Path) -> str:
    """Derive a Projection's role from its mandatory direct subtype."""
    role = PROJECTION_ROLES.get(subtype or "")
    if role is None:
        raise RoleLayoutError(f"unknown Projection role subtype in {path}: {subtype!r}")
    return role


def _role_from_metadata(metadata: dict[str, Any], path: Path) -> str | None:
    """Return a role from an explicitly governed artifact Type."""
    artifact_type = metadata.get("artifact_type")
    subtype = metadata.get("artifact_subtype")
    if artifact_type is not None and not isinstance(artifact_type, str):
        raise RoleLayoutError(f"invalid artifact_type in {path}: {artifact_type!r}")
    if subtype is not None and not isinstance(subtype, str):
        raise RoleLayoutError(f"invalid artifact_subtype in {path}: {subtype!r}")
    if artifact_type == "version":
        return _role_for_version(subtype, path)
    if artifact_type == "plan":
        return _role_for_plan(subtype, path)
    if artifact_type in PROJECTION_TYPES:
        return _role_for_projection(subtype, path)
    return ROLE_BY_TYPE.get(artifact_type or "")


def _role_from_legacy_content(metadata: dict[str, Any], path: Path) -> str | None:
    """Route a pre-CARMADIO Type through its historical Content role."""
    content_role = metadata.get("content_role")
    if content_role is not None and not isinstance(content_role, str):
        raise RoleLayoutError(f"invalid content_role in {path}: {content_role!r}")
    return ROLE_BY_CONTENT_ROLE.get(content_role or "")


def _role_from_semantic_name(path: Path) -> str | None:
    """Return a role encoded by an explicit semantic Type token."""
    name = path.name.lower()
    concern_tokens = (
        "-question-",
        "-problem-",
        "-concern-",
        "-conflict-",
        "-defect-",
        "-gap-",
        "-debt-",
        "-opportunity-",
        "-risk-",
    )
    analysis_tokens = ("-analysis-report-", "-analysis-", "-anrp-")
    requirement_tokens = ("-requirement-", "-constraint-", "-contract-")
    method_tokens = ("-decision-", "-idec-", "-method-")
    assurance_tokens = (
        "-test-case-",
        "-evaluation-case-",
        "-qa-case-",
        "-assurance-",
    )
    ops_tokens = ("-evidence-record-", "-verification-record-", "-ops-")
    if any(token in name for token in concern_tokens):
        return "01_CONCERN"
    if any(token in name for token in requirement_tokens):
        return "03_REQUIREMENT"
    if any(token in name for token in analysis_tokens):
        return "02_ANALYSIS"
    if any(token in name for token in method_tokens):
        return "04_METHOD"
    if any(token in name for token in assurance_tokens):
        return "05_ASSURANCE"
    if any(token in name for token in ops_tokens):
        return "08_OPS"
    return None


def _role_from_name(path: Path) -> str:
    """Use narrow legacy filename fallbacks for carriers without a route."""
    semantic_role = _role_from_semantic_name(path)
    if semantic_role is not None:
        return semantic_role
    name = path.name.lower()
    if "external-review-packet" in name:
        return "02_ANALYSIS"
    if "plan-evaluation" in name or "plan-test" in name or "plan-verification" in name:
        return "05_ASSURANCE"
    if "plan-implementation" in name or "plan-work" in name:
        return "04_METHOD"
    if "specification" in name:
        return "03_REQUIREMENT"
    if "analysis" in name:
        return "02_ANALYSIS"
    if "evidence" in name or "verification" in name:
        return "08_OPS"
    if "version" in name or "roadmap" in name or "release" in name:
        return "06_DELIVERY"
    if "hub" in name:
        return "03_REQUIREMENT"
    if "ijrn" in name or "implementation-journal" in name:
        return "07_IMPLEMENTATION"
    raise RoleLayoutError(f"cannot infer Content role for carrier: {path}")


def _legacy_family(relative: Path) -> str | None:
    """Return the nearest recognized legacy family directory."""
    for part in relative.parts[:-1]:
        if part in ROLE_BY_FAMILY:
            return part
    return None


def _role_for(relative: Path, content: bytes, current_role: str | None) -> str:
    """Classify one carrier, preferring governed metadata over legacy paths."""
    metadata = _metadata(relative, content)
    role = _role_from_metadata(metadata, relative)
    if role is not None:
        return role
    role = _role_from_semantic_name(relative)
    if role is not None:
        return role
    if current_role is not None:
        return current_role
    try:
        return _role_from_name(relative)
    except RoleLayoutError:
        pass
    role = _role_from_legacy_content(metadata, relative)
    if role is not None:
        return role
    family = _legacy_family(relative)
    if family is not None:
        return ROLE_BY_FAMILY[family]
    raise RoleLayoutError(f"cannot infer Content role for carrier: {relative}")


def _lifecycle(relative: Path) -> str | None:
    """Preserve one existing active, draft, or archived placement."""
    found = [part for part in relative.parts[:-1] if part in LIFECYCLE_DIRECTORIES]
    if len(found) > 1:
        raise RoleLayoutError(f"multiple lifecycle directories in {relative}")
    if found:
        return found[0]
    if _legacy_family(relative) == "references":
        return "archive"
    return None


def _scope_and_relative(carmadio: Path, path: Path) -> tuple[Path, Path]:
    """Resolve the target structural scope and source-relative route."""
    relative = path.relative_to(carmadio)
    first = relative.parts[0]
    if first in {PROJECT_SOURCE, VERSIONS_SOURCE}:
        return carmadio, Path(*relative.parts[1:])
    if first in ROLE_DIRECTORIES:
        return carmadio, Path(*relative.parts[1:])
    if first[:3].isdigit() and "_layer_" in first:
        scope = carmadio / first
        scoped_relative = Path(*relative.parts[1:])
        if scoped_relative.parts and scoped_relative.parts[0] in ROLE_DIRECTORIES:
            scoped_relative = Path(*scoped_relative.parts[1:])
        return scope, scoped_relative
    raise RoleLayoutError(f"unknown structural scope for carrier: {relative}")


def _current_role(carmadio: Path, source: Path) -> str | None:
    """Return the role directory already containing one carrier, if any."""
    parts = source.relative_to(carmadio).parts
    if parts[0] in ROLE_DIRECTORIES:
        return parts[0]
    if len(parts) > 1 and parts[1] in ROLE_DIRECTORIES:
        return parts[1]
    return None


def _target_for(carmadio: Path, source: Path, content: bytes) -> Path:
    """Return one canonical target while preserving filename and lifecycle."""
    scope, relative = _scope_and_relative(carmadio, source)
    role = _role_for(relative, content, _current_role(carmadio, source))
    lifecycle = _lifecycle(relative)
    parent = scope / role
    if lifecycle is not None:
        parent /= lifecycle
    return parent / source.name


def _methodology_state(carmadio: Path) -> bool:
    """Validate and return whether the reserved methodology boundary needs rename."""
    matches = [
        path
        for path in carmadio.iterdir()
        if path.name.casefold() == METHODOLOGY_TARGET.casefold()
    ]
    if len(matches) != 1:
        raise RoleLayoutError("installed methodology boundary is missing or ambiguous")
    selected = matches[0]
    if selected.is_symlink() or not selected.is_dir():
        raise RoleLayoutError(f"installed methodology boundary is invalid: {selected}")
    if selected.name not in {METHODOLOGY_SOURCE, METHODOLOGY_TARGET}:
        raise RoleLayoutError(f"unknown methodology boundary spelling: {selected.name}")
    return selected.name == METHODOLOGY_SOURCE


def _inventory(carmadio: Path) -> tuple[tuple[Path, ...], tuple[Path, ...]]:
    """Return candidate carriers and disposable Finder metadata."""
    files: list[Path] = []
    trash: list[Path] = []
    excluded = {METHODOLOGY_SOURCE, METHODOLOGY_TARGET}
    for path in sorted(carmadio.rglob("*")):
        relative = path.relative_to(carmadio)
        if relative.parts[0] in excluded:
            continue
        if path.is_dir():
            continue
        if path.name == ".DS_Store":
            trash.append(path)
            continue
        if len(relative.parts) == 1 and path.name in ROOT_FILES:
            continue
        files.append(path)
    return tuple(files), tuple(trash)


def _validate_targets(moves: tuple[Move, ...]) -> None:
    """Reject duplicate or occupied target paths before publication."""
    owners: dict[Path, Path] = {}
    sources = {move.source for move in moves}
    for move in moves:
        owner = owners.setdefault(move.target, move.source)
        if owner != move.source:
            message = f"target collision: {owner} and {move.source} -> {move.target}"
            raise RoleLayoutError(message)
        if move.target.exists() and move.target not in sources:
            raise RoleLayoutError(f"target already exists: {move.target}")


def _build_plan(root: Path) -> Plan:
    """Build a complete byte-bound collision-free move plan."""
    carmadio = root / CARMADIO_ROOT
    if carmadio.is_symlink() or not carmadio.is_dir():
        raise RoleLayoutError(f"invalid CARMADIO root: {carmadio}")
    carriers, trash_paths = _inventory(carmadio)
    moves: list[Move] = []
    for source in carriers:
        content = _regular_bytes(source)
        target = _target_for(carmadio, source, content)
        if source != target:
            moves.append(Move(source, target, _digest(content)))
    ordered = tuple(sorted(moves, key=lambda item: item.source.as_posix()))
    _validate_targets(ordered)
    trash = tuple((path, _digest(_regular_bytes(path))) for path in trash_paths)
    return Plan(ordered, trash, _methodology_state(carmadio))


def _plan_payload(root: Path, plan: Plan) -> dict[str, Any]:
    """Render the stable repository-relative plan payload."""

    def relative(path: Path) -> str:
        return path.relative_to(root).as_posix()

    return {
        "moves": [
            {
                "source": relative(move.source),
                "target": relative(move.target),
                "sha256": move.sha256,
            }
            for move in plan.moves
        ],
        "trash": [
            {"path": relative(path), "sha256": digest} for path, digest in plan.trash
        ],
        "rename_methodology": plan.rename_methodology,
    }


def _plan_digest(root: Path, plan: Plan) -> str:
    """Bind every planned source, target, and preimage."""
    encoded = json.dumps(
        _plan_payload(root, plan), sort_keys=True, separators=(",", ":")
    )
    return _digest(encoded.encode("utf-8"))


def _print_plan(root: Path, plan: Plan) -> str:
    """Print the stable plan and return its digest."""
    payload = _plan_payload(root, plan)
    digest = _plan_digest(root, plan)
    print(json.dumps(payload, indent=2, sort_keys=True))
    print(f"moves: {len(plan.moves)}")
    print(f"trash: {len(plan.trash)}")
    print(f"plan-digest: {digest}")
    return digest


def _verify_preimages(plan: Plan) -> None:
    """Reject any source change since preview."""
    for move in plan.moves:
        if _digest(_regular_bytes(move.source)) != move.sha256:
            raise RoleLayoutError(f"source changed after preview: {move.source}")
    for path, digest in plan.trash:
        if _digest(_regular_bytes(path)) != digest:
            raise RoleLayoutError(f"trash preimage changed after preview: {path}")


def _stage_moves(
    runtime: Path, root: Path, plan: Plan
) -> tuple[tuple[Move, Path], ...]:
    """Stage and verify one byte-identical copy for every target."""
    staged: list[tuple[Move, Path]] = []
    for move in plan.moves:
        target = runtime / "staged" / move.target.relative_to(root)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(move.source, target)
        if _digest(_regular_bytes(target)) != move.sha256:
            raise RoleLayoutError(f"staged target digest mismatch: {move.target}")
        staged.append((move, target))
    return tuple(staged)


def _publish_staged(staged: tuple[tuple[Move, Path], ...]) -> list[Move]:
    """Publish all staged destinations without deleting sources."""
    published: list[Move] = []
    for move, stage in staged:
        move.target.parent.mkdir(parents=True, exist_ok=True)
        os.replace(stage, move.target)
        published.append(move)
    return published


def _retain_sources(runtime: Path, root: Path, plan: Plan) -> list[tuple[Path, Path]]:
    """Move every source and trash file into the rollback area."""
    retained: list[tuple[Path, Path]] = []
    sources = [move.source for move in plan.moves]
    sources.extend(item[0] for item in plan.trash)
    for source in sources:
        backup = runtime / "originals" / source.relative_to(root)
        backup.parent.mkdir(parents=True, exist_ok=True)
        os.replace(source, backup)
        retained.append((source, backup))
    return retained


def _rename_methodology(root: Path, plan: Plan) -> tuple[Path, Path] | None:
    """Rename the reserved installed-methodology boundary when required."""
    if not plan.rename_methodology:
        return None
    source = root / CARMADIO_ROOT / METHODOLOGY_SOURCE
    target = root / CARMADIO_ROOT / METHODOLOGY_TARGET
    temporary = root / CARMADIO_ROOT / ".methodology-case-migration"
    os.replace(source, temporary)
    os.replace(temporary, target)
    return source, target


def _rollback(
    published: list[Move],
    retained: list[tuple[Path, Path]],
    renamed: tuple[Path, Path] | None,
) -> None:
    """Restore every original path after a failed apply."""
    if renamed is not None and renamed[1].exists():
        temporary = renamed[0].parent / ".methodology-case-rollback"
        os.replace(renamed[1], temporary)
        os.replace(temporary, renamed[0])
    for source, backup in reversed(retained):
        source.parent.mkdir(parents=True, exist_ok=True)
        if backup.exists():
            os.replace(backup, source)
    for move in reversed(published):
        if move.target.exists():
            move.target.unlink()


def _remove_empty_directories(carmadio: Path) -> None:
    """Remove empty legacy containers after a verified migration."""
    directories = (item for item in carmadio.rglob("*") if item.is_dir())
    for path in sorted(directories, reverse=True):
        if METHODOLOGY_TARGET in path.relative_to(carmadio).parts:
            continue
        with suppress(OSError):
            path.rmdir()


def _apply(root: Path, plan: Plan) -> None:
    """Apply one exact plan transactionally and verify convergence."""
    runtime = root / RUNTIME_ROOT
    if runtime.exists():
        raise RoleLayoutError(f"runtime folder already exists: {runtime}")
    published: list[Move] = []
    retained: list[tuple[Path, Path]] = []
    renamed: tuple[Path, Path] | None = None
    try:
        _verify_preimages(plan)
        staged = _stage_moves(runtime, root, plan)
        published = _publish_staged(staged)
        retained = _retain_sources(runtime, root, plan)
        renamed = _rename_methodology(root, plan)
        remaining = _build_plan(root)
        if remaining.moves or remaining.trash or remaining.rename_methodology:
            raise RoleLayoutError("migration did not converge to an empty plan")
        _remove_empty_directories(root / CARMADIO_ROOT)
    except Exception:
        _rollback(published, retained, renamed)
        raise
    finally:
        shutil.rmtree(runtime, ignore_errors=True)


def _parser() -> argparse.ArgumentParser:
    """Build the documented command-line contract."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--repo-root", type=Path, default=REPOSITORY_ROOT)
    parser.add_argument("--apply", action="store_true")
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--expect-plan-digest")
    return parser


def main() -> int:
    """Preview, apply, or verify the recursive role-layout migration."""
    args = _parser().parse_args()
    if args.apply and args.check:
        print("--apply and --check are mutually exclusive", file=sys.stderr)
        return 2
    root = args.repo_root.resolve()
    try:
        plan = _build_plan(root)
        digest = _print_plan(root, plan)
        if args.check and (plan.moves or plan.trash or plan.rename_methodology):
            raise RoleLayoutError("role-layout migration is incomplete")
        if args.apply:
            if args.expect_plan_digest != digest:
                raise RoleLayoutError("--apply requires the exact preview plan digest")
            _apply(root, plan)
            print("migration applied and verified")
        elif args.check:
            print("role layout is current")
        return 0
    except (OSError, RoleLayoutError) as error:
        print(f"carmadio-role-layout: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Replace the retired project identity prefix in every tracked text carrier.

Invocation:
    python migrate_identity_prefix_to_carmadio.py [ROOT]
    python migrate_identity_prefix_to_carmadio.py [ROOT] --apply \
        --expect-plan-digest SHA256
    python migrate_identity_prefix_to_carmadio.py [ROOT] --check

Preview is the default. The migration inventory comes exclusively from Git's
tracked-file index, rejects non-regular or non-UTF-8 affected files, proves
destination uniqueness, binds the exact preimage and output bytes in a plan
digest, stages the complete result, applies it transactionally, verifies zero
residual source-prefix tokens in tracked paths and content, and rolls back on
failure. A second preview is a zero-operation result even before the caller
stages renamed paths in Git.
"""

from __future__ import annotations

import argparse
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path

from dset_migration_tools.models import (
    DeleteOperation,
    MigrationError,
    MigrationPlan,
    WriteOperation,
)
from dset_migration_tools.safety import read_regular_file, sha256, validate_plan
from dset_migration_tools.transaction import apply_transaction

sys.dont_write_bytecode = True

REPOSITORY_ROOT = Path(__file__).resolve().parents[3]
SOURCE_PREFIX = "DSET" + "-"
TARGET_PREFIX = "CARMADIO-"
SOURCE_BYTES = SOURCE_PREFIX.encode()
TARGET_BYTES = TARGET_PREFIX.encode()
REGULAR_FILE_MODE = "100644"


@dataclass(frozen=True)
class TrackedEntry:
    """One stage-zero regular file from the Git index."""

    indexed_relative: Path
    current_relative: Path
    mode: str


def git_index(root: Path) -> tuple[tuple[str, Path], ...]:
    """Return deterministic stage-zero tracked paths and their Git modes."""
    completed = subprocess.run(
        ["git", "ls-files", "--stage", "-z"],
        cwd=root,
        check=True,
        capture_output=True,
    )
    records: list[tuple[str, Path]] = []
    for raw_record in completed.stdout.split(b"\0"):
        if not raw_record:
            continue
        metadata, raw_path = raw_record.split(b"\t", 1)
        mode, _object_id, stage = metadata.decode("ascii").split()
        if stage != "0":
            raise MigrationError(f"unmerged Git index entry: {raw_path!r}")
        try:
            relative = Path(raw_path.decode("utf-8"))
        except UnicodeDecodeError as error:
            raise MigrationError(f"tracked path is not UTF-8: {raw_path!r}") from error
        records.append((mode, relative))
    return tuple(sorted(records, key=lambda item: item[1].as_posix()))


def replaced_path(relative: Path) -> Path:
    """Return the exact target path for one tracked identity carrier."""
    return Path(relative.as_posix().replace(SOURCE_PREFIX, TARGET_PREFIX))


def tracked_entries(root: Path) -> tuple[TrackedEntry, ...]:
    """Resolve indexed pre-cutover paths before or after filesystem apply."""
    entries: list[TrackedEntry] = []
    desired_owners: dict[Path, Path] = {}
    for mode, indexed_relative in git_index(root):
        desired_relative = replaced_path(indexed_relative)
        indexed_path = root / indexed_relative
        desired_path = root / desired_relative
        indexed_exists = indexed_path.exists()
        desired_exists = desired_path.exists()
        if indexed_relative == desired_relative:
            if not indexed_exists:
                raise MigrationError(f"tracked file is missing: {indexed_relative}")
            current_relative = indexed_relative
        elif indexed_exists and desired_exists:
            raise MigrationError(
                f"identity-prefix destination already exists: {desired_relative}"
            )
        elif indexed_exists:
            current_relative = indexed_relative
        elif desired_exists:
            current_relative = desired_relative
        else:
            raise MigrationError(
                f"tracked source and expected destination are missing: "
                f"{indexed_relative} -> {desired_relative}"
            )
        owner = desired_owners.setdefault(desired_relative, indexed_relative)
        if owner != indexed_relative:
            raise MigrationError(
                f"multiple tracked paths map to {desired_relative}: "
                f"{owner}, {indexed_relative}"
            )
        entries.append(TrackedEntry(indexed_relative, current_relative, mode))
    return tuple(entries)


def migrated_content(relative: Path, content: bytes) -> bytes:
    """Replace the exact identity prefix after validating the text boundary."""
    if SOURCE_BYTES not in content:
        return content
    if b"\0" in content:
        raise MigrationError(f"affected tracked file is binary: {relative}")
    try:
        content.decode("utf-8")
    except UnicodeDecodeError as error:
        raise MigrationError(f"affected tracked file is not UTF-8: {relative}") from error
    migrated = content.replace(SOURCE_BYTES, TARGET_BYTES)
    if SOURCE_BYTES in migrated:
        raise MigrationError(f"source prefix survived rewrite: {relative}")
    return migrated


def build_plan(root: Path) -> MigrationPlan:
    """Build a complete collision-free prefix migration plan without mutation."""
    root = root.resolve()
    writes: list[WriteOperation] = []
    deletes: list[DeleteOperation] = []
    for entry in tracked_entries(root):
        current_path = root / entry.current_relative
        desired_relative = replaced_path(entry.indexed_relative)
        desired_path = root / desired_relative
        content = read_regular_file(current_path)
        migrated = migrated_content(entry.current_relative, content)
        path_changes = entry.current_relative != desired_relative
        content_changes = migrated != content
        if not path_changes and not content_changes:
            continue
        if entry.mode != REGULAR_FILE_MODE:
            raise MigrationError(
                f"affected tracked file has unsupported mode {entry.mode}: "
                f"{entry.current_relative}"
            )
        writes.append(
            WriteOperation(
                path=desired_path,
                before_sha256=None if path_changes else sha256(content),
                content=migrated,
                reason="replace retired identity prefix in path and/or content",
            )
        )
        if path_changes:
            deletes.append(
                DeleteOperation(
                    path=current_path,
                    before_sha256=sha256(content),
                    reason="remove retired identity-prefix path after replacement",
                )
            )
    plan = MigrationPlan(root, tuple(writes), tuple(deletes))
    validate_plan(plan)
    return plan


def validate_staged(plan: MigrationPlan, staged: dict[Path, Path]) -> None:
    """Prove every staged output uses only the target prefix."""
    for operation in plan.writes:
        relative = operation.path.relative_to(plan.root)
        if SOURCE_PREFIX in relative.as_posix():
            raise MigrationError(f"source prefix remains in target path: {relative}")
        content = staged[operation.path].read_bytes()
        if SOURCE_BYTES in content:
            raise MigrationError(f"source prefix remains in staged file: {relative}")
        try:
            content.decode("utf-8")
        except UnicodeDecodeError as error:
            raise MigrationError(f"staged file is not UTF-8: {relative}") from error


def verify_complete(root: Path) -> None:
    """Require a zero-operation replay and no tracked source-prefix residue."""
    plan = build_plan(root)
    if plan.writes or plan.deletes:
        raise MigrationError(
            f"migration is incomplete: writes={len(plan.writes)}, "
            f"deletes={len(plan.deletes)}"
        )
    for entry in tracked_entries(root):
        current = root / entry.current_relative
        if SOURCE_PREFIX in entry.current_relative.as_posix():
            raise MigrationError(
                f"source prefix remains in tracked path: {entry.current_relative}"
            )
        if SOURCE_BYTES in read_regular_file(current):
            raise MigrationError(
                f"source prefix remains in tracked content: {entry.current_relative}"
            )


def render_summary(plan: MigrationPlan) -> str:
    """Render a stable reviewable preview for this bounded recipe."""
    lines = [
        "Identity-prefix migration plan",
        f"root: {plan.root}",
        f"writes: {len(plan.writes)}",
        f"deletes: {len(plan.deletes)}",
        f"plan-digest: {plan.digest()}",
    ]
    lines.extend(
        f"{'CREATE' if item.before_sha256 is None else 'UPDATE'} "
        f"{item.path.relative_to(plan.root).as_posix()}"
        for item in plan.writes
    )
    lines.extend(
        f"DELETE {item.path.relative_to(plan.root).as_posix()}"
        for item in plan.deletes
    )
    return "\n".join(lines)


def arguments() -> argparse.Namespace:
    """Parse the bounded preview/apply/check interface."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", nargs="?", type=Path, default=REPOSITORY_ROOT)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--apply", action="store_true")
    mode.add_argument("--check", action="store_true")
    parser.add_argument("--expect-plan-digest")
    return parser.parse_args()


def main() -> int:
    """Preview, apply, or verify the exact repository identity cutover."""
    args = arguments()
    root = args.root.resolve()
    try:
        if args.check:
            verify_complete(root)
            print("identity-prefix migration check: PASS")
            return 0
        plan = build_plan(root)
        if not args.apply:
            print(render_summary(plan))
            return 0
        if not args.expect_plan_digest:
            raise MigrationError("--apply requires --expect-plan-digest")
        if args.expect_plan_digest != plan.digest():
            raise MigrationError(
                "plan digest changed: "
                f"expected {args.expect_plan_digest}, actual {plan.digest()}"
            )
        apply_transaction(plan, validate_staged, verify_complete)
        print(
            "identity-prefix migration applied: "
            f"writes={len(plan.writes)}, deletes={len(plan.deletes)}"
        )
        return 0
    except (MigrationError, OSError, subprocess.CalledProcessError) as error:
        print(f"BLOCKED: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Rename public DSET skill IDs to CARMADIO's ``carmadio``/``ca-*`` scheme.

Invocation:
    python migrate_public_skill_ids_to_ca.py [ROOT]
    python migrate_public_skill_ids_to_ca.py [ROOT] --apply \
        --expect-plan-digest SHA256
    python migrate_public_skill_ids_to_ca.py [ROOT] --check

Preview is the default. The migration reads Git's tracked-file index, renames
only registered public skill package directories, replaces specialist IDs only
at token boundaries, and changes the primary ``dset`` ID only in explicit
skill-identity contexts. It intentionally does not rename the ``dset`` CLI,
Python package, runtime package directory, repository, or historical archives.
"""

from __future__ import annotations

import argparse
import os
import re
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path

from dset_migration_tools.models import (
    DeleteOperation,
    MigrationError,
    MigrationPlan,
    WriteOperation,
)
from dset_migration_tools.safety import read_regular_file, sha256, validate_plan
from dset_migration_tools.transaction import apply_transaction

sys.dont_write_bytecode = True

REPOSITORY_ROOT = Path(__file__).resolve().parents[3]
PRIMARY_SOURCE_ID = "dset"
PRIMARY_TARGET_ID = "carmadio"
SPECIALIST_ACTIONS = (
    "clarify",
    "compile",
    "complete",
    "configure",
    "decisions",
    "decompose",
    "diagnose",
    "implement",
    "init",
    "landscape",
    "overview",
    "plan-implementation",
    "plan-proof",
    "prototype",
    "release",
    "repair-governance",
    "triage",
    "verify",
)
SKILL_ID_MAP = {
    PRIMARY_SOURCE_ID: PRIMARY_TARGET_ID,
    **{f"dset-{action}": f"ca-{action}" for action in SPECIALIST_ACTIONS},
}
REGULAR_FILE_MODE = "100644"
SELF_PATH = Path("15_layer_implementation/tools/migrations") / Path(__file__).name

PRIMARY_CONTEXT_REPLACEMENTS = (
    (r"(?<![A-Za-z0-9-])\$dset(?![A-Za-z0-9-])", "$carmadio"),
    (r"(?<![A-Za-z0-9-])--skill dset(?![A-Za-z0-9-])", "--skill carmadio"),
    (r"(?m)^name: dset$", "name: carmadio"),
    (r"skills/dset(?=/|\b)", "skills/carmadio"),
    (r"\[skills\.dset\]", "[skills.carmadio]"),
    (r'"dset": "lifecycle-orchestration"', '"carmadio": "lifecycle-orchestration"'),
    (r'"dset": None', '"carmadio": None'),
    (r'public_entrypoint == "dset"', 'public_entrypoint == "carmadio"'),
    (r'public_entrypoint="dset"', 'public_entrypoint="carmadio"'),
    (r'skill_id="dset"', 'skill_id="carmadio"'),
    (r'entrypoint != "dset"', 'entrypoint != "carmadio"'),
    (
        r'data\.get\("public_entrypoint", "dset"\)',
        'data.get("public_entrypoint", "carmadio")',
    ),
    (r'"lifecycle-orchestration": "dset"', '"lifecycle-orchestration": "carmadio"'),
    (r'skill = "dset"', 'skill = "carmadio"'),
    (r'name == "dset"', 'name == "carmadio"'),
    (r'_skill_text\("dset"\)', '_skill_text("carmadio")'),
    (r'/ "dset" / "SKILL\.md"', '/ "carmadio" / "SKILL.md"'),
    (r'\["dset", "dset-', '["carmadio", "dset-'),
    (r'enum = \["dset",', 'enum = ["carmadio",'),
)


@dataclass(frozen=True)
class TrackedEntry:
    """One supported stage-zero tracked file in its current location."""

    indexed_relative: Path
    current_relative: Path
    mode: str


def git_index(root: Path) -> tuple[tuple[str, Path], ...]:
    """Return deterministic stage-zero tracked paths and modes."""
    completed = subprocess.run(
        ["git", "ls-files", "--stage", "-z"],
        cwd=root,
        check=True,
        capture_output=True,
    )
    records: list[tuple[str, Path]] = []
    for raw_record in completed.stdout.split(b"\0"):
        if not raw_record:
            continue
        metadata, raw_path = raw_record.split(b"\t", 1)
        mode, _object_id, stage = metadata.decode("ascii").split()
        if stage != "0":
            raise MigrationError(f"unmerged Git index entry: {raw_path!r}")
        try:
            relative = Path(raw_path.decode("utf-8"))
        except UnicodeDecodeError as error:
            raise MigrationError(f"tracked path is not UTF-8: {raw_path!r}") from error
        records.append((mode, relative))
    return tuple(sorted(records, key=lambda item: item[1].as_posix()))


def is_current_surface(relative: Path) -> bool:
    """Return whether a carrier participates in the current skill interface."""
    if relative == SELF_PATH or relative.parts[:1] == ("90_legacy",):
        return False
    if relative.parts[:1] == (".carmadio",):
        return relative == Path(".carmadio/carmadio_settings.toml")
    if relative.name == "bootstrap_bundle.json":
        return False
    return not any(part in {"archive", "_obsolete"} for part in relative.parts)


def replaced_path(relative: Path) -> Path:
    """Rename only a registered package directly below ``skills``."""
    if len(relative.parts) < 2 or relative.parts[0] != "skills":
        return relative
    target = SKILL_ID_MAP.get(relative.parts[1])
    if target is None:
        return relative
    return Path("skills", target, *relative.parts[2:])


def candidate_paths(relative: Path) -> tuple[Path, ...]:
    """Return valid pre- and post-migration filesystem locations."""
    target = replaced_path(relative)
    return (relative,) if target == relative else (relative, target)


def tracked_entries(root: Path) -> tuple[TrackedEntry, ...]:
    """Resolve tracked paths before or after filesystem application."""
    entries: list[TrackedEntry] = []
    desired_owners: dict[Path, Path] = {}
    for mode, indexed_relative in git_index(root):
        desired_relative = replaced_path(indexed_relative)
        existing = tuple(
            candidate
            for candidate in candidate_paths(indexed_relative)
            if (root / candidate).exists()
        )
        if len(existing) != 1:
            raise MigrationError(
                f"expected one path variant for {indexed_relative}, found {existing}"
            )
        owner = desired_owners.setdefault(desired_relative, indexed_relative)
        if owner != indexed_relative:
            raise MigrationError(
                f"multiple tracked paths map to {desired_relative}: "
                f"{owner}, {indexed_relative}"
            )
        entries.append(TrackedEntry(indexed_relative, existing[0], mode))
    return tuple(entries)


def rename_skill_directories(root: Path) -> tuple[tuple[Path, Path], ...]:
    """Atomically rename complete public skill packages before file rewrites."""
    pairs = tuple(
        (root / "skills" / source, root / "skills" / target)
        for source, target in SKILL_ID_MAP.items()
    )
    for source, target in pairs:
        if source.exists() and target.exists():
            raise MigrationError(f"both skill package identities exist: {source}, {target}")
        selected = source if source.exists() else target
        if not selected.is_dir() or selected.is_symlink():
            raise MigrationError(f"skill package is missing or invalid: {selected}")
    renamed: list[tuple[Path, Path]] = []
    try:
        for source, target in pairs:
            if not source.exists():
                continue
            os.replace(source, target)
            renamed.append((source, target))
    except OSError as error:
        rollback_skill_directories(renamed)
        raise MigrationError(f"skill directory rename failed: {error}") from error
    return tuple(renamed)


def rollback_skill_directories(
    renamed: tuple[tuple[Path, Path], ...] | list[tuple[Path, Path]],
) -> None:
    """Restore package directories after a failed content transaction."""
    failures: list[str] = []
    for source, target in reversed(renamed):
        try:
            if source.exists():
                failures.append(f"rollback source already exists: {source}")
            elif not target.exists():
                failures.append(f"rollback target is missing: {target}")
            else:
                os.replace(target, source)
        except OSError as error:
            failures.append(f"{target} -> {source}: {error}")
    if failures:
        raise MigrationError("skill directory rollback failed: " + "; ".join(failures))


def replace_specialist_ids(text: str) -> str:
    """Replace registered specialist IDs without touching longer DSET names."""
    for source, target in SKILL_ID_MAP.items():
        if source == PRIMARY_SOURCE_ID:
            continue
        pattern = rf"(?<![A-Za-z0-9-]){re.escape(source)}(?![A-Za-z0-9-])"
        text = re.sub(pattern, target, text)
    return text


def replace_wrapper_digests(text: str, digests: dict[str, str]) -> str:
    """Refresh hashes inside governance-registry wrapper blocks."""
    lines = text.splitlines(keepends=True)
    in_wrapper = False
    skill_id: str | None = None
    for index, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith("[["):
            in_wrapper = stripped == "[[governance_registry.wrappers]]"
            skill_id = None
            continue
        if not in_wrapper:
            continue
        match = re.fullmatch(r'skill = "([^"]+)"', stripped)
        if match:
            skill_id = match.group(1)
            continue
        if skill_id is None or not stripped.startswith('sha256 = "'):
            continue
        digest = digests.get(skill_id)
        if digest is None:
            raise MigrationError(f"registry names unknown public skill: {skill_id}")
        newline = "\n" if line.endswith("\n") else ""
        lines[index] = f'sha256 = "{digest}"{newline}'
    return "".join(lines)


def migrated_content(
    relative: Path,
    content: bytes,
    skill_digests: dict[str, str] | None = None,
) -> bytes:
    """Return one current carrier with only governed skill identities changed."""
    if not is_current_surface(relative):
        return content
    if b"\0" in content:
        return content
    try:
        text = content.decode("utf-8")
    except UnicodeDecodeError:
        return content
    migrated = replace_specialist_ids(text)
    for pattern, replacement in PRIMARY_CONTEXT_REPLACEMENTS:
        migrated = re.sub(pattern, replacement, migrated)
    if relative.parts[:1] == ("skills",):
        migrated = migrated.replace("DSET", "CARMADIO")
        if relative == Path("skills/README.md"):
            migrated = re.sub(r"(?<![A-Za-z0-9-])`dset`", "`carmadio`", migrated)
            migrated = migrated.replace("(dset/SKILL.md)", "(carmadio/SKILL.md)")
        if relative == Path("skills/host-distribution.md"):
            migrated = migrated.replace(
                "exact 19-skill catalog: `dset`,",
                "exact 19-skill catalog: `carmadio`,",
            )
    if skill_digests is not None:
        migrated = replace_wrapper_digests(migrated, skill_digests)
    return migrated.encode("utf-8")


def target_skill_digests(root: Path) -> dict[str, str]:
    """Compute post-migration source digests for every public SKILL carrier."""
    digests: dict[str, str] = {}
    for entry in tracked_entries(root):
        desired = replaced_path(entry.indexed_relative)
        if (
            len(desired.parts) != 3
            or desired.parts[0] != "skills"
            or desired.name != "SKILL.md"
        ):
            continue
        content = read_regular_file(root / entry.current_relative)
        migrated = migrated_content(entry.current_relative, content)
        digests[desired.parts[1]] = sha256(migrated)
    expected = set(SKILL_ID_MAP.values())
    if set(digests) != expected:
        raise MigrationError(
            f"public SKILL digest set differs: expected={sorted(expected)}, "
            f"actual={sorted(digests)}"
        )
    return digests


def build_plan(root: Path) -> MigrationPlan:
    """Build the collision-free migration plan without mutation."""
    writes: list[WriteOperation] = []
    deletes: list[DeleteOperation] = []
    skill_digests = target_skill_digests(root)
    for entry in tracked_entries(root):
        current_path = root / entry.current_relative
        desired_relative = replaced_path(entry.indexed_relative)
        desired_path = root / desired_relative
        content = read_regular_file(current_path)
        migrated = migrated_content(
            entry.current_relative,
            content,
            skill_digests,
        )
        path_changes = entry.current_relative != desired_relative
        if not path_changes and migrated == content:
            continue
        if entry.mode != REGULAR_FILE_MODE:
            raise MigrationError(
                f"affected tracked file has unsupported mode {entry.mode}: "
                f"{entry.current_relative}"
            )
        writes.append(
            WriteOperation(
                path=desired_path,
                before_sha256=None if path_changes else sha256(content),
                content=migrated,
                reason="rename governed public skill identity",
            )
        )
        if path_changes:
            deletes.append(
                DeleteOperation(
                    path=current_path,
                    before_sha256=sha256(content),
                    reason="remove retired public skill package path",
                )
            )
    plan = MigrationPlan(root, tuple(writes), tuple(deletes))
    validate_plan(plan)
    return plan


def validate_staged(plan: MigrationPlan, staged: dict[Path, Path]) -> None:
    """Prove staged public package identities match their target folders."""
    for operation in plan.writes:
        relative = operation.path.relative_to(plan.root)
        if relative.parts[:1] != ("skills",) or len(relative.parts) < 2:
            continue
        if relative.parts[1] in SKILL_ID_MAP:
            raise MigrationError(f"retired skill package path remains: {relative}")
        if relative.name == "SKILL.md":
            expected = relative.parts[1]
            text = staged[operation.path].read_text(encoding="utf-8")
            if f"name: {expected}\n" not in text:
                raise MigrationError(f"skill name/path mismatch: {relative}")


def verify_complete(root: Path) -> None:
    """Require an idempotent replay and no retired current skill packages."""
    plan = build_plan(root)
    if plan.writes or plan.deletes:
        raise MigrationError(
            f"migration incomplete: writes={len(plan.writes)}, "
            f"deletes={len(plan.deletes)}"
        )
    actual = {
        path.parent.name
        for path in (root / "skills").glob("*/SKILL.md")
        if path.is_file()
    }
    expected = set(SKILL_ID_MAP.values())
    if actual != expected:
        raise MigrationError(
            f"public skill packages differ: expected={sorted(expected)}, "
            f"actual={sorted(actual)}"
        )


def render_summary(plan: MigrationPlan) -> str:
    """Render a stable reviewable preview."""
    lines = [
        "CARMADIO public-skill migration plan",
        f"root: {plan.root}",
        f"writes: {len(plan.writes)}",
        f"deletes: {len(plan.deletes)}",
        f"plan-digest: {plan.digest()}",
    ]
    lines.extend(
        f"{'CREATE' if item.before_sha256 is None else 'UPDATE'} "
        f"{item.path.relative_to(plan.root).as_posix()}"
        for item in plan.writes
    )
    lines.extend(
        f"DELETE {item.path.relative_to(plan.root).as_posix()}"
        for item in plan.deletes
    )
    return "\n".join(lines)


def arguments() -> argparse.Namespace:
    """Parse preview, apply, and check modes."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", nargs="?", type=Path, default=REPOSITORY_ROOT)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--apply", action="store_true")
    mode.add_argument("--check", action="store_true")
    parser.add_argument("--expect-plan-digest")
    return parser.parse_args()


def main() -> int:
    """Preview, apply, or verify the public skill identity cutover."""
    args = arguments()
    root = args.root.resolve()
    try:
        if args.check:
            verify_complete(root)
            print("public-skill migration check: PASS")
            return 0
        plan = build_plan(root)
        if not args.apply:
            print(render_summary(plan))
            return 0
        if not args.expect_plan_digest:
            raise MigrationError("--apply requires --expect-plan-digest")
        if args.expect_plan_digest != plan.digest():
            raise MigrationError(
                f"plan digest changed: expected {args.expect_plan_digest}, "
                f"actual {plan.digest()}"
            )
        renamed = rename_skill_directories(root)
        try:
            filesystem_adjusted_plan = build_plan(root)
            apply_transaction(
                filesystem_adjusted_plan,
                validate_staged,
                verify_complete,
            )
        except Exception:
            rollback_skill_directories(renamed)
            raise
        print(
            "public-skill migration applied: "
            f"writes={len(plan.writes)}, deletes={len(plan.deletes)}"
        )
        return 0
    except (MigrationError, OSError, subprocess.CalledProcessError) as error:
        print(f"BLOCKED: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Rename framework-owned repository paths and identifiers to CARMADIO.

Invocation:
    python migrate_repository_directories_to_carmadio.py [ROOT]
    python migrate_repository_directories_to_carmadio.py [ROOT] --apply \
        --expect-plan-digest SHA256
    python migrate_repository_directories_to_carmadio.py [ROOT] --check

Preview is the default. The tracked inventory comes exclusively from Git's
index. Apply first renames each complete governed directory atomically so
ignored state is preserved, then transactionally rewrites tracked paths, text
references, and corresponding Python identifiers. The reviewed plan digest
binds every tracked preimage, destination, and output byte. Collisions, binary
affected carriers, symlinks, unmerged index entries, and partial layouts fail
closed.
"""

from __future__ import annotations

import argparse
import os
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path

from dset_migration_tools.models import (
    DeleteOperation,
    MigrationError,
    MigrationPlan,
    WriteOperation,
)
from dset_migration_tools.safety import read_regular_file, sha256, validate_plan
from dset_migration_tools.transaction import apply_transaction

sys.dont_write_bytecode = True

REPOSITORY_ROOT = Path(__file__).resolve().parents[3]
SOURCE_GOVERNED_DIRECTORY = "." + "dset"
SOURCE_RUNTIME_DIRECTORY = SOURCE_GOVERNED_DIRECTORY + "_runtime"
TARGET_GOVERNED_DIRECTORY = ".carmadio"
TARGET_RUNTIME_DIRECTORY = ".carmadio_runtime"
SOURCE_METHODOLOGY_DIRECTORY = "000_" + "dset" + "_methodology"
TARGET_METHODOLOGY_DIRECTORY = "000_carmadio_methodology"
SOURCE_SETTINGS_STEM = "dset" + "_settings"
TARGET_SETTINGS_STEM = "carmadio_settings"
TOP_LEVEL_DIRECTORY_REPLACEMENTS = (
    (SOURCE_RUNTIME_DIRECTORY, TARGET_RUNTIME_DIRECTORY),
    (SOURCE_GOVERNED_DIRECTORY, TARGET_GOVERNED_DIRECTORY),
)
NAME_REPLACEMENTS = TOP_LEVEL_DIRECTORY_REPLACEMENTS + (
    (SOURCE_METHODOLOGY_DIRECTORY, TARGET_METHODOLOGY_DIRECTORY),
    (SOURCE_SETTINGS_STEM, TARGET_SETTINGS_STEM),
)
CONTENT_REPLACEMENTS = tuple(
    (source.encode(), target.encode())
    for source, target in NAME_REPLACEMENTS
)
IDENTIFIER_REPLACEMENTS = (
    (("dset" + "_root").encode(), b"carmadio_root"),
)
ALL_CONTENT_REPLACEMENTS = CONTENT_REPLACEMENTS + IDENTIFIER_REPLACEMENTS
REGULAR_FILE_MODE = "100644"


@dataclass(frozen=True)
class TrackedEntry:
    """One stage-zero regular file resolved in the current filesystem."""

    indexed_relative: Path
    current_relative: Path
    mode: str


def git_index(root: Path) -> tuple[tuple[str, Path], ...]:
    """Return deterministic stage-zero tracked paths and Git modes."""
    completed = subprocess.run(
        ["git", "ls-files", "--stage", "-z"],
        cwd=root,
        check=True,
        capture_output=True,
    )
    records: list[tuple[str, Path]] = []
    for raw_record in completed.stdout.split(b"\0"):
        if not raw_record:
            continue
        metadata, raw_path = raw_record.split(b"\t", 1)
        mode, _object_id, stage = metadata.decode("ascii").split()
        if stage != "0":
            raise MigrationError(f"unmerged Git index entry: {raw_path!r}")
        try:
            relative = Path(raw_path.decode("utf-8"))
        except UnicodeDecodeError as error:
            raise MigrationError(f"tracked path is not UTF-8: {raw_path!r}") from error
        records.append((mode, relative))
    return tuple(sorted(records, key=lambda item: item[1].as_posix()))


def replaced_text(value: str) -> str:
    """Replace exact retired directory tokens, longest token first."""
    for source, target in NAME_REPLACEMENTS:
        value = value.replace(source, target)
    return value


def replaced_path(relative: Path) -> Path:
    """Return the target path for one tracked carrier."""
    return Path(replaced_text(relative.as_posix()))


def candidate_paths(relative: Path) -> tuple[Path, ...]:
    """Return every deterministic intermediate path for compound renames."""
    candidates = {relative.as_posix()}
    for source, target in NAME_REPLACEMENTS:
        candidates.update(
            value.replace(source, target) for value in tuple(candidates)
        )
    return tuple(Path(value) for value in sorted(candidates))


def tracked_entries(root: Path) -> tuple[TrackedEntry, ...]:
    """Resolve indexed paths before or after the filesystem cutover."""
    entries: list[TrackedEntry] = []
    desired_owners: dict[Path, Path] = {}
    for mode, indexed_relative in git_index(root):
        desired_relative = replaced_path(indexed_relative)
        existing = tuple(
            candidate
            for candidate in candidate_paths(indexed_relative)
            if (root / candidate).exists()
        )
        if len(existing) > 1:
            raise MigrationError(
                f"multiple migration path variants exist for {indexed_relative}: "
                + ", ".join(item.as_posix() for item in existing)
            )
        if not existing:
            raise MigrationError(
                "tracked source and all expected path variants are missing: "
                f"{indexed_relative} -> {desired_relative}"
            )
        current_relative = existing[0]
        owner = desired_owners.setdefault(desired_relative, indexed_relative)
        if owner != indexed_relative:
            raise MigrationError(
                f"multiple tracked paths map to {desired_relative}: "
                f"{owner}, {indexed_relative}"
            )
        entries.append(TrackedEntry(indexed_relative, current_relative, mode))
    return tuple(entries)


def migrated_content(relative: Path, content: bytes) -> bytes:
    """Rewrite directory references after validating the text boundary."""
    if not any(source in content for source, _target in ALL_CONTENT_REPLACEMENTS):
        return content
    if b"\0" in content:
        raise MigrationError(f"affected tracked file is binary: {relative}")
    try:
        content.decode("utf-8")
    except UnicodeDecodeError as error:
        raise MigrationError(
            f"affected tracked file is not UTF-8: {relative}"
        ) from error
    migrated = content
    for source, target in ALL_CONTENT_REPLACEMENTS:
        migrated = migrated.replace(source, target)
    if any(source in migrated for source, _target in ALL_CONTENT_REPLACEMENTS):
        raise MigrationError(f"retired directory token survived rewrite: {relative}")
    return migrated


def build_plan(root: Path) -> MigrationPlan:
    """Build the complete collision-free tracked-carrier plan."""
    root = root.resolve()
    writes: list[WriteOperation] = []
    deletes: list[DeleteOperation] = []
    for entry in tracked_entries(root):
        current_path = root / entry.current_relative
        desired_relative = replaced_path(entry.indexed_relative)
        desired_path = root / desired_relative
        content = read_regular_file(current_path)
        migrated = migrated_content(entry.current_relative, content)
        path_changes = entry.current_relative != desired_relative
        content_changes = migrated != content
        if not path_changes and not content_changes:
            continue
        if entry.mode != REGULAR_FILE_MODE:
            raise MigrationError(
                f"affected tracked file has unsupported mode {entry.mode}: "
                f"{entry.current_relative}"
            )
        writes.append(
            WriteOperation(
                path=desired_path,
                before_sha256=None if path_changes else sha256(content),
                content=migrated,
                reason="rename governed repository directories and references",
            )
        )
        if path_changes:
            deletes.append(
                DeleteOperation(
                    path=current_path,
                    before_sha256=sha256(content),
                    reason="remove retired repository-directory path",
                )
            )
    plan = MigrationPlan(root, tuple(writes), tuple(deletes))
    validate_plan(plan)
    return plan


def validate_directory_layout(root: Path, allow_source: bool) -> None:
    """Reject ambiguous or partial top-level directory layouts."""
    for source_name, target_name in TOP_LEVEL_DIRECTORY_REPLACEMENTS:
        source = root / source_name
        target = root / target_name
        if source.exists() and target.exists():
            raise MigrationError(
                f"both source and target directories exist: {target_name}"
            )
        if source.exists() and not allow_source:
            raise MigrationError(f"retired directory remains: {source_name}")
        selected = source if source.exists() else target
        if not selected.is_dir():
            raise MigrationError(
                f"required repository directory is missing: {target_name}"
            )
        if selected.is_symlink():
            raise MigrationError(
                f"repository directory cannot be a symlink: {selected}"
            )
    governed_root = (
        root / SOURCE_GOVERNED_DIRECTORY
        if (root / SOURCE_GOVERNED_DIRECTORY).exists()
        else root / TARGET_GOVERNED_DIRECTORY
    )
    source_methodology = governed_root / SOURCE_METHODOLOGY_DIRECTORY
    target_methodology = governed_root / TARGET_METHODOLOGY_DIRECTORY
    if source_methodology.exists() and target_methodology.exists():
        raise MigrationError(
            "both source and target methodology directories exist: "
            f"{target_methodology}"
        )
    if source_methodology.exists() and not allow_source:
        raise MigrationError(
            f"retired methodology directory remains: {source_methodology}"
        )
    selected_methodology = (
        source_methodology if source_methodology.exists() else target_methodology
    )
    if not selected_methodology.is_dir() or selected_methodology.is_symlink():
        raise MigrationError(
            f"required methodology directory is invalid: {selected_methodology}"
        )


def rename_source_directories(root: Path) -> tuple[tuple[Path, Path], ...]:
    """Atomically rename complete source directories and return rollback pairs."""
    validate_directory_layout(root, allow_source=True)
    renamed: list[tuple[Path, Path]] = []
    try:
        for source_name, target_name in TOP_LEVEL_DIRECTORY_REPLACEMENTS:
            source = root / source_name
            target = root / target_name
            if not source.exists():
                continue
            os.replace(source, target)
            renamed.append((source, target))
        source_methodology = (
            root / TARGET_GOVERNED_DIRECTORY / SOURCE_METHODOLOGY_DIRECTORY
        )
        target_methodology = (
            root / TARGET_GOVERNED_DIRECTORY / TARGET_METHODOLOGY_DIRECTORY
        )
        if source_methodology.exists():
            os.replace(source_methodology, target_methodology)
            renamed.append((source_methodology, target_methodology))
    except OSError as error:
        rollback_directory_renames(renamed)
        raise MigrationError(f"directory rename failed: {error}") from error
    return tuple(renamed)


def rollback_directory_renames(
    renamed: tuple[tuple[Path, Path], ...] | list[tuple[Path, Path]],
) -> None:
    """Restore atomically renamed directories after a tracked migration failure."""
    failures: list[str] = []
    for source, target in reversed(renamed):
        try:
            if source.exists():
                failures.append(f"rollback source already exists: {source}")
            elif not target.exists():
                failures.append(f"rollback target is missing: {target}")
            else:
                os.replace(target, source)
        except OSError as error:
            failures.append(f"{target} -> {source}: {error}")
    if failures:
        raise MigrationError("directory rollback failed: " + "; ".join(failures))


def validate_staged(plan: MigrationPlan, staged: dict[Path, Path]) -> None:
    """Prove staged paths and text contain no retired directory identity."""
    source_tokens = tuple(source for source, _target in NAME_REPLACEMENTS)
    for operation in plan.writes:
        relative = operation.path.relative_to(plan.root)
        if any(source in relative.as_posix() for source in source_tokens):
            raise MigrationError(
                f"retired directory remains in target path: {relative}"
            )
        content = staged[operation.path].read_bytes()
        if any(source in content for source, _target in ALL_CONTENT_REPLACEMENTS):
            raise MigrationError(
                f"retired directory remains in staged file: {relative}"
            )
        try:
            content.decode("utf-8")
        except UnicodeDecodeError as error:
            raise MigrationError(f"staged file is not UTF-8: {relative}") from error


def verify_complete(root: Path) -> None:
    """Require target directories, zero-operation replay, and zero residue."""
    validate_directory_layout(root, allow_source=False)
    plan = build_plan(root)
    if plan.writes or plan.deletes:
        raise MigrationError(
            f"migration is incomplete: writes={len(plan.writes)}, "
            f"deletes={len(plan.deletes)}"
        )
    source_tokens = tuple(source for source, _target in NAME_REPLACEMENTS)
    for entry in tracked_entries(root):
        current = root / entry.current_relative
        relative_text = entry.current_relative.as_posix()
        if any(source in relative_text for source in source_tokens):
            raise MigrationError(
                f"retired directory remains in path: {entry.current_relative}"
            )
        content = read_regular_file(current)
        if any(source in content for source, _target in ALL_CONTENT_REPLACEMENTS):
            raise MigrationError(
                f"retired directory remains in content: {entry.current_relative}"
            )


def render_summary(plan: MigrationPlan) -> str:
    """Render a stable reviewable preview."""
    lines = [
        "CARMADIO repository-directory migration plan",
        f"root: {plan.root}",
        f"writes: {len(plan.writes)}",
        f"deletes: {len(plan.deletes)}",
        f"plan-digest: {plan.digest()}",
    ]
    lines.extend(
        f"{'CREATE' if item.before_sha256 is None else 'UPDATE'} "
        f"{item.path.relative_to(plan.root).as_posix()}"
        for item in plan.writes
    )
    lines.extend(
        f"DELETE {item.path.relative_to(plan.root).as_posix()}"
        for item in plan.deletes
    )
    return "\n".join(lines)


def arguments() -> argparse.Namespace:
    """Parse preview, apply, and check modes."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", nargs="?", type=Path, default=REPOSITORY_ROOT)
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--apply", action="store_true")
    mode.add_argument("--check", action="store_true")
    parser.add_argument("--expect-plan-digest")
    return parser.parse_args()


def main() -> int:
    """Preview, apply, or verify the repository-directory cutover."""
    args = arguments()
    root = args.root.resolve()
    try:
        if args.check:
            verify_complete(root)
            print("repository-directory migration check: PASS")
            return 0
        validate_directory_layout(root, allow_source=True)
        reviewed_plan = build_plan(root)
        if not args.apply:
            print(render_summary(reviewed_plan))
            return 0
        if not args.expect_plan_digest:
            raise MigrationError("--apply requires --expect-plan-digest")
        if args.expect_plan_digest != reviewed_plan.digest():
            raise MigrationError(
                "plan digest changed: "
                f"expected {args.expect_plan_digest}, actual {reviewed_plan.digest()}"
            )
        renamed = rename_source_directories(root)
        try:
            filesystem_adjusted_plan = build_plan(root)
            apply_transaction(
                filesystem_adjusted_plan,
                validate_staged,
                verify_complete,
            )
        except Exception:
            rollback_directory_renames(renamed)
            raise
        print(
            "repository-directory migration applied: "
            f"writes={len(reviewed_plan.writes)}, "
            f"deletes={len(reviewed_plan.deletes)}"
        )
        return 0
    except (MigrationError, OSError, subprocess.CalledProcessError) as error:
        print(f"BLOCKED: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
